import { useEffect, useMemo } from 'react';
import { Link, useParams, useNavigate } from 'react-router-dom';
import { ChevronRight, Calendar, Home, ArrowLeft, Clock, Share2 } from 'lucide-react';
import { useI18n } from '@/i18n/I18nContext';
import { useNews } from '@/hooks/useNews';
import { getI18nValue } from '@/lib/i18n-text';
import { imgPath } from '@/utils/img-path';
import { Button } from '@/components/ui/button';
import { useSeo } from '@/hooks/useSeo';
import { toast } from 'sonner';
import { resolveAppUrl } from '@lark-apaas/client-toolkit-lite';

export default function NewsDetailPage() {
  const { t, language } = useI18n();
  const { slug } = useParams<{ slug: string }>();
  const navigate = useNavigate();
  const { articles, getArticleBySlug, getRelatedArticles, loading } = useNews({ preferRemote: true });

  const article = useMemo(() => {
    if (!slug) return null;
    return getArticleBySlug(slug) || null;
  }, [slug, getArticleBySlug]);

  const relatedArticles = useMemo(() => {
    if (!article) return [];
    return getRelatedArticles(article.id, 3);
  }, [article, getRelatedArticles]);

  const title = article ? getI18nValue(article.title, language) : '';
  const content = article ? getI18nValue(article.content, language) : '';
  const summary = article ? getI18nValue(article.summary, language) : '';
  const metaTitle = article ? getI18nValue(article.metaTitle, language) : '';
  const metaDescription = article ? getI18nValue(article.metaDescription, language) : '';

  // SEO
  useSeo({
    title: article ? (metaTitle || title) : 'News | OWELL Industrial',
    description: article ? (metaDescription || summary) : '',
    type: 'article',
  });

  // Article JSON-LD
  useEffect(() => {
    if (!article) return;
    const jsonLd = {
      '@context': 'https://schema.org',
      '@type': 'Article',
      headline: title,
      description: summary,
      image: article.coverImage ? [imgPath(article.coverImage)] : [],
      datePublished: article.publishDate,
      dateModified: new Date(article.updatedAt).toISOString().split('T')[0],
      publisher: {
        '@type': 'Organization',
        name: 'OWELL Industrial',
      },
      mainEntityOfPage: {
        '@type': 'WebPage',
        '@id': window.location.href,
      },
    };

    const existing = document.getElementById('article-jsonld');
    if (existing) existing.remove();

    const script = document.createElement('script');
    script.id = 'article-jsonld';
    script.type = 'application/ld+json';
    script.text = JSON.stringify(jsonLd);
    document.head.appendChild(script);

    return () => {
      const el = document.getElementById('article-jsonld');
      if (el) el.remove();
    };
  }, [article, title, summary]);

  const handleShare = async () => {
    if (!article) return;
    const url = window.location.href;
    if (navigator.share) {
      try {
        await navigator.share({ title, url });
      } catch {
        // user cancelled
      }
    } else {
      try {
        await navigator.clipboard.writeText(url);
        toast.success(t('news.shareLinkCopied'));
      } catch {
        toast.error(t('news.linkCopyFailed'));
      }
    }
  };

  if (loading) {
    return (
      <div className="min-h-screen bg-background flex items-center justify-center">
        <div className="w-8 h-8 border-2 border-primary border-t-transparent rounded-full animate-spin" />
      </div>
    );
  }

  if (!article) {
    return (
      <div className="min-h-screen bg-background">
        <div className="max-w-3xl mx-auto px-4 md:px-6 py-20 text-center">
            <h1 className="text-2xl font-semibold text-foreground mb-3">
              {t('news.articleNotFound')}
            </h1>
            <p className="text-muted-foreground mb-6">
              {t('news.articleNotFoundDesc')}
            </p>
            <Button onClick={() => navigate('/news')} variant="outline">
              <ArrowLeft className="size-4 mr-2" />
              {t('news.backToNews')}
            </Button>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-background">
      {/* Breadcrumb */}
      <div className="w-full border-b border-border/40 bg-card/30">
        <div className="max-w-4xl mx-auto px-4 md:px-6 py-3">
          <nav className="flex items-center gap-2 text-sm text-muted-foreground flex-wrap">
            <Link to="/" className="hover:text-primary transition-colors flex items-center gap-1">
              <Home className="size-3.5" />
              <span>{t('nav.home')}</span>
            </Link>
            <ChevronRight className="size-3.5" />
            <Link to="/news" className="hover:text-primary transition-colors">
              {t('nav.news')}
            </Link>
            <ChevronRight className="size-3.5" />
            <span className="text-foreground font-medium truncate max-w-[50vw]">{title}</span>
          </nav>
        </div>
      </div>

      {/* Article */}
      <article className="w-full">
        {/* Hero Image */}
        {article.coverImage && (
          <div className="w-full max-h-[420px] overflow-hidden bg-muted">
            <img
              src={imgPath(article.coverImage)}
              alt={title}
              className="w-full h-auto object-cover max-h-[420px]"
            />
          </div>
        )}

        {/* Article Content */}
        <div className="max-w-3xl mx-auto px-4 md:px-6 py-10 md:py-14">
          {/* Meta */}
          <div className="flex items-center gap-4 text-sm text-muted-foreground mb-5">
            <div className="flex items-center gap-1.5">
              <Calendar className="size-3.5" />
              <time dateTime={article.publishDate}>
                {new Date(article.publishDate).toLocaleDateString(undefined, {
                  year: 'numeric',
                  month: 'long',
                  day: 'numeric',
                })}
              </time>
            </div>
            <div className="flex items-center gap-1.5">
              <Clock className="size-3.5" />
              <span>{Math.max(1, Math.ceil(content.replace(/<[^>]*>/g, '').length / 1000))} {t('news.minRead')}</span>
            </div>
            <Button
              variant="ghost"
              size="sm"
              className="h-6 px-2 text-xs ml-auto"
              onClick={handleShare}
            >
              <Share2 className="size-3.5 mr-1" />
              Share
            </Button>
          </div>

          {/* Title */}
          <h1 className="text-2xl md:text-3xl font-bold text-foreground mb-5 leading-tight">
            {title}
          </h1>

          {/* Summary / Intro */}
          {summary && (
            <p className="text-lg text-muted-foreground leading-relaxed mb-8 pb-6 border-b border-border/40">
              {summary}
            </p>
          )}

          {/* Body */}
          <div
            className="prose prose-sm md:prose-base max-w-none dark:prose-invert
              prose-headings:font-semibold
              prose-headings:text-foreground
              prose-p:text-foreground/90
              prose-p:leading-relaxed
              prose-a:text-primary
              prose-a:no-underline hover:prose-a:underline
              prose-strong:text-foreground
              prose-ul:text-foreground/90
              prose-ol:text-foreground/90
              prose-li:text-foreground/90
              prose-table:border-collapse
              prose-th:bg-card
              prose-th:border
              prose-th:border-border
              prose-th:px-4
              prose-th:py-2
              prose-td:border
              prose-td:border-border
              prose-td:px-4
              prose-td:py-2
              prose-img:rounded-sm
              prose-img:border
              prose-img:border-border
              prose-blockquote:border-l-primary
              prose-blockquote:text-muted-foreground
              prose-h2:text-xl
              prose-h2:mt-8
              prose-h3:text-lg
              prose-h3:mt-6
              prose-code:text-primary
              prose-code:bg-primary/5
              prose-code:px-1.5
              prose-code:py-0.5
              prose-code:rounded-sm
              prose-code:before:content-none
              prose-code:after:content-none"
            dangerouslySetInnerHTML={{ __html: content }}
          />
        </div>
      </article>

      {/* Related Articles */}
      {relatedArticles.length > 0 && (
        <section className="w-full bg-card/30 border-t border-border/40 py-12 md:py-16">
          <div className="max-w-6xl mx-auto px-4 md:px-6">
            <h2 className="text-xl md:text-2xl font-semibold text-foreground mb-6">
              {t('news.relatedArticles')}
            </h2>
            <div className="grid grid-cols-1 md:grid-cols-3 gap-5">
              {relatedArticles.map((art) => {
                const rTitle = getI18nValue(art.title, language);
                const rSummary = getI18nValue(art.summary, language);
                return (
                  <Link
                    key={art.id}
                    to={`/news/${art.slug}`}
                    className="group bg-background border border-border rounded-sm overflow-hidden hover:border-primary/40 transition-colors"
                  >
                    <div className="aspect-[16/9] overflow-hidden bg-muted">
                      {art.coverImage ? (
                        <img
                          src={imgPath(art.coverImage)}
                          alt={rTitle}
                          loading="lazy"
                          className="w-full h-full object-cover transition-transform duration-500 group-hover:scale-105"
                        />
                      ) : null}
                    </div>
                    <div className="p-4 space-y-2">
                      <div className="text-xs text-muted-foreground">{art.publishDate}</div>
                      <h3 className="text-sm font-semibold text-foreground line-clamp-2 group-hover:text-primary transition-colors">
                        {rTitle}
                      </h3>
                      <p className="text-xs text-muted-foreground line-clamp-2">{rSummary}</p>
                    </div>
                  </Link>
                );
              })}
            </div>
          </div>
        </section>
      )}

      {/* Back to list */}
      <div className="w-full py-8 md:py-10 border-t border-border/40">
        <div className="max-w-3xl mx-auto px-4 md:px-6">
          <Button variant="outline" onClick={() => navigate('/news')}>
            <ArrowLeft className="size-4 mr-2" />
            {t('news.backToList')}
          </Button>
        </div>
      </div>
    </div>
  );
}
