function migrateFromLegacy(raw: unknown): PrivacyPolicyData | null {
  if (!raw || typeof raw !== 'object') return null;
  const obj = raw as Record<string, unknown>;
  if (!Array.isArray(obj.sections)) return null;
  try {
    return {
      version: STORAGE_VERSION,
      lastUpdated: String(obj.lastUpdated ?? 'August 2024'),
      sections: obj.sections.map((s: unknown, idx: number) => {
        const sec = s as Record<string, unknown>;
        return {
          id: String(sec.id ?? `sec_${idx}`),
          icon: String(sec.icon ?? 'FileText'),
          title: migrateI18n(sec.title as string | I18nText),
          content: migrateI18n(sec.content as string | I18nText),
          order: typeof sec.order === 'number' ? sec.order : idx + 1,
        };
      }),
    };
  } catch (err) {
    logger.error('privacy policy migrate failed:', String(err));
    return null;
  }
}

function readLocalPrivacyPolicy(): PrivacyPolicyData {
  try {
    const saved = scopedStorage.getItem(STORAGE_KEY);
    if (saved) {
      const parsed = JSON.parse(saved);
      const migrated = migrateFromLegacy(parsed);
      if (migrated) return migrated;
    }
  } catch {
    // ignore
  }
  return DEFAULT_PRIVACY;
}

export function usePrivacyPolicy(options?: { preferRemote?: boolean }) {
  const preferRemote = options?.preferRemote ?? false;
  const remoteData = useRemoteDataStore<PrivacyPolicyData>('privacy');
  // 🔴 同步初始化：直接读 localStorage 作为初始值，避免首帧默认值 → 第二帧同值不同引用的重渲染
  const [data, setData] = useState<PrivacyPolicyData>(() => {
    try {
      const saved = scopedStorage.getItem(STORAGE_KEY);
      if (saved) {
        const parsed = JSON.parse(saved);
        const migrated = migrateFromLegacy(parsed);
        if (migrated) return migrated;
      }
    } catch (err) {
      logger.error('usePrivacyPolicy init failed:', String(err));
    }
    return DEFAULT_PRIVACY;
  });

  // loading 始终为 false：本地数据同步初始化完成
  const loading = false;

  const displayData = useMemo((): PrivacyPolicyData => {
    if (preferRemote && remoteData && typeof remoteData === 'object' && Array.isArray(remoteData.sections)) {
      return {
        ...remoteData,
        sections: remoteData.sections.map((s) => ({
          ...s,
          title: migrateI18n(s.title as any),
          content: migrateI18n(s.content as any),
        })),
      } as PrivacyPolicyData;
    }
    return data;
  }, [preferRemote, remoteData, data]);

  const updateSection = useCallback(
    (sectionId: string, updates: Partial<PrivacySection>): boolean => {
      try {
        const newSections = data.sections.map((s) =>
          s.id === sectionId ? { ...s, ...updates } : s,
        );
        const next: PrivacyPolicyData = {
          ...data,
          sections: newSections,
          lastUpdated: new Date().toLocaleDateString('en-US', { month: 'long', year: 'numeric' }),
        };
        setData(next);
        scopedStorage.setItem(STORAGE_KEY, JSON.stringify(next));
        return true;
      } catch (err) {
        logger.error('updateSection failed:', String(err));
        return false;
      }
    },
    [data],
  );

  const addSection = useCallback(
    (section: Omit<PrivacySection, 'id' | 'order'>): boolean => {
      try {
        const newSection: PrivacySection = {
          ...section,
          id: `sec_${Date.now()}`,
          order: data.sections.length + 1,
        };
        const next: PrivacyPolicyData = {
          ...data,
          sections: [...data.sections, newSection],
        };
        setData(next);
        scopedStorage.setItem(STORAGE_KEY, JSON.stringify(next));
        return true;
      } catch (err) {
        logger.error('addSection failed:', String(err));
        return false;
      }
    },
    [data],
  );

  const deleteSection = useCallback(
    (sectionId: string): boolean => {
      try {
        const newSections = data.sections
          .filter((s) => s.id !== sectionId)
          .map((s, idx) => ({ ...s, order: idx + 1 }));
        const next: PrivacyPolicyData = {
          ...data,
          sections: newSections,
        };
        setData(next);
        scopedStorage.setItem(STORAGE_KEY, JSON.stringify(next));
        return true;
      } catch (err) {
        logger.error('deleteSection failed:', String(err));
        return false;
      }
    },
    [data],
  );

  const moveSection = useCallback(
    (sectionId: string, direction: 'up' | 'down'): boolean => {
      try {
        const idx = data.sections.findIndex((s) => s.id === sectionId);
        if (idx === -1) return false;
        if (direction === 'up' && idx === 0) return false;
        if (direction === 'down' && idx === data.sections.length - 1) return false;

        const newSections = [...data.sections];
        const targetIdx = direction === 'up' ? idx - 1 : idx + 1;
        [newSections[idx], newSections[targetIdx]] = [newSections[targetIdx], newSections[idx]];
        const reordered = newSections.map((s, i) => ({ ...s, order: i + 1 }));

        const next: PrivacyPolicyData = {
          ...data,
          sections: reordered,
        };
        setData(next);
        scopedStorage.setItem(STORAGE_KEY, JSON.stringify(next));
        return true;
      } catch (err) {
        logger.error('moveSection failed:', String(err));
        return false;
      }
    },
    [data],
  );

  const resetToDefaults = useCallback((): boolean => {
    try {
      setData(DEFAULT_PRIVACY);
      scopedStorage.setItem(STORAGE_KEY, JSON.stringify(DEFAULT_PRIVACY));
      return true;
    } catch (err) {
      logger.error('resetToDefaults failed:', String(err));
      return false;
    }
  }, []);

  return {
    data: displayData,
    loading,
    updateSection,
    addSection,
    deleteSection,
    moveSection,
    resetToDefaults,
    isUsingRemoteData: preferRemote && !!remoteData,
  };
}
