import { useState, useMemo } from 'react';
import { Link, useNavigate } from 'react-router-dom';
import { ChevronRight, ChevronLeft, Calendar, Home } from 'lucide-react';
import { useI18n } from '@/i18n/I18nContext';
import { useNews } from '@/hooks/useNews';
import { getI18nValue } from '@/lib/i18n-text';
import { imgPath } from '@/utils/img-path';
import { Button } from '@/components/ui/button';
import { useSeo } from '@/hooks/useSeo';

const PAGE_SIZE = 9;

export default function NewsPage() {
  const { t, language } = useI18n();
  const { articles, loading, getPublishedArticles } = useNews({ preferRemote: true });
  const navigate = useNavigate();
  const [page, setPage] = useState(1);

  const publishedArticles = useMemo(() => {
    return getPublishedArticles().sort(
      (a, b) => new Date(b.publishDate).getTime() - new Date(a.publishDate).getTime()
    );
  }, [getPublishedArticles]);

  const totalPages = Math.max(1, Math.ceil(publishedArticles.length / PAGE_SIZE));
  const paginatedArticles = useMemo(() => {
    const start = (page - 1) * PAGE_SIZE;
    return publishedArticles.slice(start, start + PAGE_SIZE);
  }, [publishedArticles, page]);

  // SEO
  useSeo({
    title: t('news.metaTitle') + ' | OWELL Industrial',
    description: t('news.metaDescription'),
  });

  return (
    <div className="min-h-screen bg-background">
      {/* Breadcrumb */}
      <div className="w-full border-b border-border/40 bg-card/30">
        <div className="max-w-6xl mx-auto px-4 md:px-6 py-3">
          <nav className="flex items-center gap-2 text-sm text-muted-foreground">
            <Link to="/" className="hover:text-primary transition-colors flex items-center gap-1">
              <Home className="size-3.5" />
              <span>{t('nav.home')}</span>
            </Link>
            <ChevronRight className="size-3.5" />
            <span className="text-foreground font-medium">{t('nav.news')}</span>
          </nav>
        </div>
      </div>

      {/* Page Header */}
      <section className="w-full py-12 md:py-16">
        <div className="max-w-6xl mx-auto px-4 md:px-6">
          <div className="text-center max-w-2xl mx-auto">
            <h1 className="text-3xl md:text-4xl font-bold text-foreground mb-3">
              {t('news.title')}
            </h1>
            <p className="text-muted-foreground text-base">
              {t('news.subtitle')}
            </p>
          </div>
        </div>
      </section>

      {/* Articles Grid */}
      <section className="w-full pb-16 md:pb-20">
        <div className="max-w-6xl mx-auto px-4 md:px-6">
          {loading ? (
            <div className="flex items-center justify-center py-16">
              <div className="w-8 h-8 border-2 border-primary border-t-transparent rounded-full animate-spin" />
            </div>
          ) : paginatedArticles.length === 0 ? (
            <div className="text-center py-16 text-muted-foreground">
              {t('news.noArticles')}
            </div>
          ) : (
            <>
              <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
                {paginatedArticles.map((article) => {
                  const title = getI18nValue(article.title, language);
                  const summary = getI18nValue(article.summary, language);
                  return (
                    <article
                      key={article.id}
                      className="group bg-card border border-border rounded-sm overflow-hidden hover:border-primary/40 transition-colors cursor-pointer"
                      onClick={() => navigate(`/news/${article.slug}`)}
                    >
                      <div className="aspect-[16/9] overflow-hidden bg-muted">
                        {article.coverImage ? (
                          <img
                            src={imgPath(article.coverImage)}
                            alt={title}
                            loading="lazy"
                            className="w-full h-full object-cover transition-transform duration-500 group-hover:scale-105"
                          />
                        ) : (
                          <div className="w-full h-full flex items-center justify-center text-muted-foreground text-sm">
                            {t('news.noImage')}
                          </div>
                        )}
                      </div>
                      <div className="p-5 space-y-2.5">
                        <div className="flex items-center gap-1.5 text-xs text-muted-foreground">
                          <Calendar className="size-3" />
                          <time dateTime={article.publishDate}>
                            {new Date(article.publishDate).toLocaleDateString(undefined, {
                              year: 'numeric',
                              month: 'short',
                              day: 'numeric',
                            })}
                          </time>
                        </div>
                        <h2 className="text-base font-semibold text-foreground line-clamp-2 leading-snug group-hover:text-primary transition-colors">
                          {title}
                        </h2>
                        <p className="text-sm text-muted-foreground line-clamp-3 leading-relaxed">
                          {summary}
                        </p>
                        <div className="pt-1">
                          <span className="text-xs font-medium text-primary inline-flex items-center gap-1 group-hover:gap-1.5 transition-all">
                            {t('news.readMore')}
                            <ChevronRight className="size-3" />
                          </span>
                        </div>
                      </div>
                    </article>
                  );
                })}
              </div>

              {/* Pagination */}
              {totalPages > 1 && (
                <div className="flex items-center justify-center gap-2 pt-10">
                  <Button
                    variant="outline"
                    size="icon"
                    onClick={() => {
                      setPage((p) => Math.max(1, p - 1));
                      window.scrollTo({ top: 0, behavior: 'smooth' });
                    }}
                    disabled={page === 1}
                    className="h-9 w-9"
                  >
                    <ChevronLeft className="size-4" />
                  </Button>
                  {Array.from({ length: totalPages }, (_, i) => i + 1).map((p) => (
                    <Button
                      key={p}
                      variant={page === p ? 'default' : 'outline'}
                      size="icon"
                      onClick={() => {
                        setPage(p);
                        window.scrollTo({ top: 0, behavior: 'smooth' });
                      }}
                      className="h-9 w-9 text-sm"
                    >
                      {p}
                    </Button>
                  ))}
                  <Button
                    variant="outline"
                    size="icon"
                    onClick={() => {
                      setPage((p) => Math.min(totalPages, p + 1));
                      window.scrollTo({ top: 0, behavior: 'smooth' });
                    }}
                    disabled={page === totalPages}
                    className="h-9 w-9"
                  >
                    <ChevronRight className="size-4" />
                  </Button>
                </div>
              )}
            </>
          )}
        </div>
      </section>
    </div>
  );
}
