import { NavLink, Navigate, Outlet, useLocation, useNavigate } from 'react-router-dom';
import { Suspense } from 'react';
import { useEffect, useState } from 'react';
import {
  LayoutDashboard,
  Package,
  Star,
  Award,
  LogOut,
  Menu,
  X,
  Lightbulb,
  CheckCircle2,
  MonitorPlay,
  Building2,
  Languages,
  Search,
  Tag,
  ChevronDown,
  KeyRound,
  MessageSquare,
  Mail,
  BookOpen,
  Footprints,
  ShieldCheck,
  Newspaper,
  Github,
} from 'lucide-react';
import { Button } from '@/components/ui/button';
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuTrigger,
} from '@/components/ui/dropdown-menu';
import {
  SidebarProvider,
  Sidebar,
  SidebarContent,
  SidebarHeader,
  SidebarFooter,
  SidebarGroup,
  SidebarMenu,
  SidebarMenuItem,
  SidebarMenuButton,
  SidebarInset,
  SidebarTrigger,
  useSidebar,
} from '@/components/ui/sidebar';
import { useI18n } from '@/i18n/I18nContext';
import type { Language } from '@/i18n/translations';
import { scopedStorage } from '@lark-apaas/client-toolkit-lite';
import { toast } from 'sonner';
import { useInquiries } from '@/hooks/useInquiries';
import { imgPath } from '@/utils/img-path';
import { useFooterSettings, type FooterSettings } from '@/hooks/useFooterSettings';

const AUTH_KEY = '__app_ledlight_admin_auth';

const NAV_ITEMS = [
  { path: '/admin/dashboard', i18nKey: 'admin.dashboard', icon: LayoutDashboard },
  { path: '/admin/inquiries', i18nKey: 'admin.inquiries', icon: MessageSquare },
  { path: '/admin/hero-slides', i18nKey: 'admin.heroSlides', icon: MonitorPlay },
  { path: '/admin/products', i18nKey: 'admin.products', icon: Package },
  { path: '/admin/categories', i18nKey: 'admin.categories', icon: Tag },
  { path: '/admin/features', i18nKey: 'admin.features', icon: CheckCircle2 },
  { path: '/admin/advantages', i18nKey: 'admin.advantages', icon: Award },
  { path: '/admin/testimonials', i18nKey: 'admin.testimonials', icon: Star },
  { path: '/admin/news', i18nKey: 'admin.news', icon: Newspaper },
  { path: '/admin/about', i18nKey: 'admin.aboutPage', icon: Building2 },
  { path: '/admin/translate-settings', i18nKey: 'admin.translateSettings', icon: Languages },
  { path: '/admin/seo', i18nKey: 'admin.seoSettings', icon: Search },
  { path: '/admin/change-password', i18nKey: 'admin.changePassword', icon: KeyRound },
  { path: '/admin/email-settings', i18nKey: 'admin.emailSettings', icon: Mail },
  { path: '/admin/catalog', i18nKey: 'admin.catalog', icon: BookOpen },
  { path: '/admin/footer', i18nKey: 'admin.footerSettings', icon: Footprints },
  { path: '/admin/privacy-policy', i18nKey: 'admin.privacyPolicy', icon: ShieldCheck },
  { path: '/admin/github-sync', i18nKey: 'admin.githubSync', icon: Github },
];

const LANGUAGE_OPTIONS: { code: Language; label: string }[] = [
  { code: 'zh', label: '简体中文' },
  { code: 'en', label: 'English' },
  { code: 'es', label: 'Español' },
  { code: 'ja', label: '日本語' },
];

function AdminSidebar({ footerSettings }: { footerSettings: FooterSettings }) {
  const { adminT, adminLanguage, setAdminLanguage } = useI18n();
  const navigate = useNavigate();
  const location = useLocation();
  const { unreadCount } = useInquiries();
  const handleLogout = () => {
    try {
      scopedStorage.removeItem(AUTH_KEY);
    } catch {
      // ignore
    }
    toast.success(adminT('admin.loggedOut'));
    navigate('/admin/login', { replace: true });
  };

  const currentLangLabel =
    LANGUAGE_OPTIONS.find((l) => l.code === adminLanguage)?.label || adminLanguage;
  const logoSrc = footerSettings.headerLogo || imgPath('/images/owell-logo.png');

  return (
    <Sidebar collapsible="icon" className="border-r border-sidebar-border">
      <SidebarHeader>
        <div className="flex items-center gap-2 px-2 py-3 group-data-[state=collapsed]:px-0 group-data-[state=collapsed]:justify-center">
           <div className="size-8 shrink-0 overflow-hidden flex items-center justify-center">
              <img
                src={logoSrc}
                alt="OWELL Industrial"
                width={32}
                height={32}
                loading="lazy"
                decoding="async"
                className="w-full h-full object-contain bg-transparent"
              />
           </div>
          <div className="flex-1 min-w-0 group-data-[state=collapsed]:hidden">
             <div className="text-sm font-semibold truncate">{adminT('admin.brand.name')}</div>
            <div className="text-xs text-muted-foreground truncate">{adminT('admin.brand.subtitle')}</div>
          </div>
        </div>
      </SidebarHeader>
      <SidebarContent>
          <SidebarGroup className="p-2">
            <SidebarMenu>
              {NAV_ITEMS.map((item) => {
                const Icon = item.icon;
                const label = adminT(item.i18nKey);
                const isActive =
                  item.path === '/admin/dashboard'
                    ? location.pathname === '/admin/dashboard'
                    : location.pathname === item.path ||
                      location.pathname.startsWith(`${item.path}/`);
               return (
                 <SidebarMenuItem key={item.path}>
                   <SidebarMenuButton
                     asChild
                     tooltip={label}
                     isActive={isActive}
                   >
                     <NavLink
                       to={item.path}
                       end={item.path === '/admin/dashboard'}
                       className="flex items-center gap-2"
                     >
                        <Icon className="size-4 shrink-0" />
                        <span className="group-data-[state=collapsed]:hidden flex-1">{label}</span>
                        {item.path === '/admin/inquiries' && unreadCount > 0 && (
                          <span className="group-data-[state=collapsed]:hidden shrink-0 inline-flex items-center justify-center min-w-[18px] h-[18px] px-1 text-[10px] font-bold rounded-full bg-destructive text-destructive-foreground">
                            {unreadCount > 99 ? '99+' : unreadCount}
                          </span>
                        )}
                     </NavLink>
                   </SidebarMenuButton>
                 </SidebarMenuItem>
               );
            })}
            </SidebarMenu>
          </SidebarGroup>
      </SidebarContent>
      <SidebarFooter>
        <div className="space-y-1 p-2">
          {/* 语言切换 */}
          <DropdownMenu>
            <DropdownMenuTrigger asChild>
              <Button variant="ghost" size="sm" className="w-full justify-start text-muted-foreground">
                <Languages className="size-4 mr-2 shrink-0" />
                <span className="flex-1 text-left truncate group-data-[state=collapsed]:hidden">
                  {currentLangLabel}
                </span>
                <ChevronDown className="size-3 ml-auto opacity-50 group-data-[state=collapsed]:hidden" />
              </Button>
            </DropdownMenuTrigger>
            <DropdownMenuContent align="end" side="right" className="w-36">
              {LANGUAGE_OPTIONS.map((opt) => (
                <DropdownMenuItem
                  key={opt.code}
                  onClick={() => setAdminLanguage(opt.code)}
                  className={adminLanguage === opt.code ? 'text-primary font-medium' : ''}
                >
                  {opt.label}
                </DropdownMenuItem>
              ))}
            </DropdownMenuContent>
          </DropdownMenu>

          <Button
            variant="ghost"
            size="sm"
            className="w-full justify-start text-muted-foreground hover:text-destructive hover:bg-destructive/10"
            onClick={handleLogout}
          >
            <LogOut className="size-4 mr-2 shrink-0" />
            <span className="group-data-[state=collapsed]:hidden">{adminT('admin.logout')}</span>
          </Button>
        </div>
      </SidebarFooter>
    </Sidebar>
  );
}

export default function AdminLayout() {
  const [isAuth, setIsAuth] = useState<boolean | null>(null);
  const location = useLocation();
  const { adminT } = useI18n();
  // 放在顶层早返回之前，保证 hooks 数量稳定
  const { settings: footerSettings } = useFooterSettings();

  useEffect(() => {
    try {
      const auth = scopedStorage.getItem(AUTH_KEY);
      setIsAuth(auth === 'true');
    } catch {
      setIsAuth(false);
    }
  }, [location.pathname]);

  if (isAuth === null) {
    return (
      <div className="min-h-screen bg-background flex items-center justify-center">
        <div className="w-8 h-8 border-2 border-primary border-t-transparent rounded-full animate-spin" />
      </div>
    );
  }

  if (!isAuth) {
    return <Navigate to="/admin/login" replace />;
  }

  return (
    <SidebarProvider className="admin-theme">
      <AdminSidebar footerSettings={footerSettings} />
      <SidebarInset className="flex flex-col min-w-0 overflow-x-hidden bg-muted/20">
        {/* Admin Topbar */}
        <header className="sticky top-0 z-40 h-14 border-b border-border/40 bg-background/80 backdrop-blur-md flex items-center justify-between px-4">
          <div className="flex items-center gap-3">
            <SidebarTrigger className="md:hidden" />
            <h1 className="text-sm font-semibold text-foreground">
               {adminT('admin.brand.name')}
            </h1>
          </div>
          <div className="flex items-center gap-2">
            <Lightbulb className="size-4 text-primary" />
            <span className="text-xs text-muted-foreground">v1.0</span>
          </div>
        </header>

        <main className="flex-1 w-full overflow-y-auto p-4 md:p-6 lg:p-8">
          <Suspense
            fallback={
              <div className="flex items-center justify-center py-24">
                <div className="flex items-center gap-3 text-muted-foreground">
                  <div className="size-5 animate-spin rounded-full border-2 border-primary/30 border-t-primary" />
                  <span className="text-sm">Loading...</span>
                </div>
              </div>
            }
          >
            <Outlet />
          </Suspense>
        </main>
      </SidebarInset>
    </SidebarProvider>
  );
}
