import { useEffect, useState } from 'react';
import { useI18n } from '@/i18n/I18nContext';
import { scopedStorage } from '@lark-apaas/client-toolkit-lite';
import { getDynamicBasename } from '@/utils/basename';

export interface SeoProps {
  title?: string;
  description?: string;
  keywords?: string;
  image?: string;
  type?: 'website' | 'product' | 'article';
  url?: string;
  pageKey?: string; // 'home' | 'products' | 'about' | 'contact' | 'privacy' | 'product-detail'
  schema?: Record<string, unknown> | Record<string, unknown>[];
}

const STORAGE_KEY = '__app_ledlight_seo_settings';

interface SeoSettingsGlobal {
  siteName: string;
  defaultTitle: string;
  defaultDescription: string;
  defaultKeywords: string;
  ogImage: string;
  companyName: string;
  companyAddress: string;
  companyPhone: string;
  companyEmail: string;
  twitterHandle: string;
  facebookUrl: string;
  linkedinUrl: string;
}

interface SeoSettingsPage {
  pageKey: string;
  title: string;
  description: string;
  keywords: string;
}

interface SeoSettings {
  global: SeoSettingsGlobal;
  pages: SeoSettingsPage[];
}

function loadSettings(): SeoSettings | null {
  try {
    const saved = scopedStorage.getItem(STORAGE_KEY);
    if (saved) {
      return JSON.parse(saved) as SeoSettings;
    }
  } catch {
    // ignore
  }
  return null;
}

function setMeta(selector: string, content: string) {
  let el = document.head.querySelector(selector) as HTMLElement | null;
  if (!el) {
    const tag = selector.trim().startsWith('[name=')
      ? 'meta'
      : selector.trim().startsWith('[property=')
        ? 'meta'
        : selector.trim().startsWith('link[rel=')
          ? 'link'
          : 'meta';
    el = document.createElement(tag) as HTMLElement;

    // extract attribute from selector
    const attrMatch = selector.match(/\[(\w+)="([^"]+)"\]/);
    if (attrMatch) {
      el.setAttribute(attrMatch[1], attrMatch[2]);
    }
    document.head.appendChild(el);
  }
  if (el.tagName === 'LINK') {
    el.setAttribute('href', content);
  } else {
    el.setAttribute('content', content);
  }
}

function removeMeta(selector: string) {
  const els = document.head.querySelectorAll(selector);
  els.forEach((el) => el.remove());
}

function upsertScriptLdJson(id: string, data: Record<string, unknown> | Record<string, unknown>[]) {
  let el = document.getElementById(id) as HTMLScriptElement | null;
  if (!el) {
    el = document.createElement('script');
    el.type = 'application/ld+json';
    el.id = id;
    document.head.appendChild(el);
  }
  el.textContent = JSON.stringify(data);
}

function removeScriptLdJson(id: string) {
  const el = document.getElementById(id);
  if (el) el.remove();
}

function buildHreflangs(basePath: string, langs: string[]) {
  // remove existing dynamic hreflang tags first
  removeMeta('link[rel="alternate"][data-seo-hreflang]');
  langs.forEach((lang) => {
    const link = document.createElement('link');
    link.rel = 'alternate';
    link.hreflang = lang === 'zh' ? 'zh-CN' : lang;
    link.href = `${window.location.origin}${basePath}?lang=${lang}`;
    link.setAttribute('data-seo-hreflang', 'true');
    document.head.appendChild(link);
  });
  // x-default
  const xdefault = document.createElement('link');
  xdefault.rel = 'alternate';
  xdefault.hreflang = 'x-default';
  xdefault.href = `${window.location.origin}${basePath}`;
  xdefault.setAttribute('data-seo-hreflang', 'true');
  document.head.appendChild(xdefault);
}

export function useSeo(props: SeoProps = {}) {
  const { title, description, keywords, image, type = 'website', url, pageKey, schema } = props;
  const { language, t, adminT } = useI18n();
  const [settings, setSettings] = useState<SeoSettings | null>(null);

  // Load custom SEO settings from storage on mount
  useEffect(() => {
    setSettings(loadSettings());
  }, []);

  useEffect(() => {
    // Priority: custom per-page settings > passed-in props > i18n defaults
    let resolvedTitle: string;
    let resolvedDesc: string;
    let resolvedKw: string;

    const customPage = pageKey ? settings?.pages.find((p) => p.pageKey === pageKey) : null;

    // Title
    if (customPage?.title) {
      resolvedTitle = customPage.title;
    } else if (title) {
      resolvedTitle = title;
    } else {
      resolvedTitle = settings?.global.defaultTitle || t('seo.defaultTitle');
    }

    const siteName = settings?.global.siteName || 'OWELL Lighting';
    const isHomeDefault = resolvedTitle === (settings?.global.defaultTitle || t('seo.defaultTitle'));
    const fullTitle = isHomeDefault ? resolvedTitle : `${resolvedTitle} | ${siteName}`;
    document.title = fullTitle;

    // Description
    if (customPage?.description) {
      resolvedDesc = customPage.description;
    } else if (description) {
      resolvedDesc = description;
    } else {
      resolvedDesc = settings?.global.defaultDescription || t('seo.defaultDescription');
    }

    // Keywords
    if (customPage?.keywords) {
      resolvedKw = customPage.keywords;
    } else if (keywords) {
      resolvedKw = keywords;
    } else {
      resolvedKw = settings?.global.defaultKeywords || t('seo.defaultKeywords');
    }

    // OG Image
    const ogImage = image || settings?.global.ogImage || '';

    setMeta('meta[name="description"]', resolvedDesc);
    setMeta('meta[name="keywords"]', resolvedKw);

    // Open Graph
    setMeta('meta[property="og:title"]', fullTitle);
    setMeta('meta[property="og:description"]', resolvedDesc);
    setMeta('meta[property="og:type"]', type);
    setMeta('meta[property="og:site_name"]', siteName);
    setMeta('meta[property="og:url"]', url || window.location.href);
    setMeta('meta[property="og:locale"]', language === 'zh' ? 'zh_CN' : `${language}_${language.toUpperCase()}`);
    if (ogImage) {
      setMeta('meta[property="og:image"]', ogImage);
    }

    // Twitter Card
    setMeta('meta[name="twitter:card"]', 'summary_large_image');
    setMeta('meta[name="twitter:title"]', fullTitle);
    setMeta('meta[name="twitter:description"]', resolvedDesc);
    const twitterHandle = settings?.global.twitterHandle || '';
    if (twitterHandle) {
      setMeta('meta[name="twitter:site"]', twitterHandle);
    }
    if (ogImage) {
      setMeta('meta[name="twitter:image"]', ogImage);
    }

    // Canonical
    const canonical = url || window.location.href.split('?')[0];
    setMeta('link[rel="canonical"]', canonical);

    // hreflang (only for main pages, not admin)
    if (!window.location.pathname.startsWith('/admin')) {
      buildHreflangs(window.location.pathname, ['en', 'zh', 'es', 'ja']);
    }

    // Schema.org structured data
    if (schema) {
      upsertScriptLdJson('seo-schema-page', schema);
    } else {
      removeScriptLdJson('seo-schema-page');
    }

    // Organization schema with custom settings
    const base = getDynamicBasename();
    const basePath = base === '/' ? '' : base;
    const orgSchema = {
      '@context': 'https://schema.org',
      '@type': 'Organization',
      name: settings?.global.companyName || siteName,
      url: `${window.location.origin}${basePath}/`,
       logo: `${window.location.origin}${basePath}/favicon.png`,
      description: resolvedDesc,
      contactPoint: {
        '@type': 'ContactPoint',
        contactType: 'sales',
        email: settings?.global.companyEmail || 'sales@owell-lighting.com',
        telephone: settings?.global.companyPhone || undefined,
        availableLanguage: ['English', 'Chinese', 'Spanish', 'Japanese'],
      },
      sameAs: [
        settings?.global.facebookUrl,
        settings?.global.linkedinUrl,
      ].filter(Boolean) as string[],
    };
    upsertScriptLdJson('seo-schema-org', orgSchema);

    // LocalBusiness schema with custom settings
    const address = settings?.global.companyAddress || '';
    const localSchema = {
      '@context': 'https://schema.org',
      '@type': 'LocalBusiness',
      name: settings?.global.companyName || siteName,
      image: ogImage || '',
      '@id': `${window.location.origin}${basePath}/#localbusiness`,
      url: `${window.location.origin}${basePath}/`,
      telephone: settings?.global.companyPhone || '',
      email: settings?.global.companyEmail || '',
      address: {
        '@type': 'PostalAddress',
        streetAddress: address.split(',')[0] || address || '',
        addressLocality: 'Shenzhen',
        addressRegion: 'Guangdong',
        addressCountry: 'CN',
      },
      openingHoursSpecification: {
        '@type': 'OpeningHoursSpecification',
        dayOfWeek: ['Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday'],
        opens: '08:30',
        closes: '18:00',
      },
    };
    upsertScriptLdJson('seo-schema-local', localSchema);

    return () => {
      // Clean up hreflang on unmount / language change
      removeMeta('link[rel="alternate"][data-seo-hreflang]');
      removeScriptLdJson('seo-schema-page');
      removeScriptLdJson('seo-schema-org');
      removeScriptLdJson('seo-schema-local');
    };
  }, [title, description, keywords, image, type, url, pageKey, schema, language, t, adminT, settings]);
}
