import { useState, useMemo, useEffect } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import { useSeo } from '@/hooks/useSeo';
import { motion } from 'framer-motion';
import {
  ChevronLeft,
  ChevronRight,
  ArrowLeft,
  CheckCircle2,
  MessageCircle,
  Package,
  ShieldCheck,
  Zap,
  Globe,
  ImageOff,
} from 'lucide-react';
import { Button } from '@/components/ui/button';
import { Badge } from '@/components/ui/badge';
import { Image } from '@/components/ui/image';
import { useProducts } from '@/hooks/useProducts';
import { useI18n } from '@/i18n/I18nContext';
import { getI18nValue } from '@/lib/i18n-text';
import PageBreadcrumb from '@/components/PageBreadcrumb';
import { useFooterSettings } from '@/hooks/useFooterSettings';
import { normalizeWhatsAppUrl } from '@/lib/whatsapp';
import { toast } from 'sonner';

export default function ProductDetailPage() {
  const { t, language } = useI18n();
  const { id } = useParams<{ id: string }>();
  const navigate = useNavigate();
  const { products } = useProducts({ preferRemote: true });

  const { settings: footerSettings } = useFooterSettings({ preferRemote: true });

  const product = useMemo(() => products.find((p) => p.id === id), [products, id]);

  const productName = useMemo(
    () => (product ? getI18nValue(product.name, language) : ''),
    [product, language]
  );
  const productDesc = useMemo(
    () => (product ? getI18nValue(product.description, language) : ''),
    [product, language]
  );

  const seoDescription = useMemo(() => {
    if (!product) return t('seo.productDetailDescription');
    const getField = (key: string) => {
      const f = product.customFields.find((cf) => {
        const k = typeof cf.key === 'string' ? cf.key : cf.key[language] ?? cf.key.en ?? '';
        return k.toLowerCase() === key.toLowerCase();
      });
      if (!f) return '';
      return typeof f.value === 'string' ? f.value : f.value[language] ?? f.value.en ?? '';
    };
    const specStr = [
      getField('Power') && `Power: ${getField('Power')}`,
      getField('IP Rating') && `IP Rating: ${getField('IP Rating')}`,
      getField('Material') && `Material: ${getField('Material')}`,
    ].filter(Boolean).join(', ');
    return `${productName}. ${specStr}. ${t('seo.productDetailDescription')}`.slice(0, 160);
  }, [product, productName, language, t]);

  useSeo({
    title: productName ? `${productName} - OWELL Lighting` : t('seo.productDetailTitle'),
    description: seoDescription,
    keywords: `${productName}, LED sensor light, ${t('seo.productDetailKeywords')}`,
    image: product?.image,
    type: 'product',
    schema: product
      ? {
          '@context': 'https://schema.org',
          '@type': 'Product',
          name: productName,
          image: product.image,
          description: productDesc,
          brand: { '@type': 'Brand', name: 'OWELL Lighting' },
          sku: product.id,
          offers: {
            '@type': 'Offer',
            priceCurrency: 'USD',
            price: '0',
            availability: 'https://schema.org/InStock',
            url: window.location.href,
          },
          aggregateRating: {
            '@type': 'AggregateRating',
            ratingValue: '4.9',
            reviewCount: '50',
          },
        }
      : undefined,
  });

  const images = useMemo(() => {
    if (!product) return [];
    if (product.gallery && product.gallery.length > 0) {
      return product.gallery.filter((g) => g && g.length > 0);
    }
    if (product.image) return [product.image];
    return [];
  }, [product]);

  const [activeImageIndex, setActiveImageIndex] = useState(0);
  const [imgErrors, setImgErrors] = useState<Record<number, boolean>>({});

  useEffect(() => {
    setActiveImageIndex(0);
    setImgErrors({});
  }, [id]);

  const hasImages = images.length > 0;

  const handlePrev = () => {
    if (!hasImages) return;
    setActiveImageIndex((prev) => (prev <= 0 ? images.length - 1 : prev - 1));
  };

  const handleNext = () => {
    if (!hasImages) return;
    setActiveImageIndex((prev) => (prev >= images.length - 1 ? 0 : prev + 1));
  };

  const handleInquiry = () => {
    if (product) {
      navigate(`/contact?product=${encodeURIComponent(product.id)}`);
    }
  };

  const handleWhatsApp = () => {
    if (product) {
      const msg = `Hi, I'm interested in ${productName}. Could you send me more details and a quotation?`;
      const url = normalizeWhatsAppUrl(footerSettings.whatsappUrl, msg);
      if (url) {
        window.open(url, '_blank');
      }
    }
  };

  if (!product) {
    return (
      <div className="min-h-screen bg-background flex items-center justify-center">
        <div className="text-center space-y-4">
          <Package className="size-16 mx-auto text-muted-foreground/50" />
          <h1 className="text-xl font-semibold text-foreground">
            {t('productDetail.notFound')}
          </h1>
          <Button variant="outline" onClick={() => navigate('/products')}>
            <ArrowLeft className="size-4 mr-2" />
            {t('productDetail.backToList')}
          </Button>
        </div>
      </div>
    );
  }

  const allFields = product.customFields;

  return (
    <div className="min-h-screen bg-background">
      {/* Breadcrumb */}
      <div className="border-b border-border bg-card/30">
        <div className="max-w-7xl mx-auto px-4 md:px-6 py-4">
          <PageBreadcrumb
            firstItem={{ label: t('nav.home'), href: '/', icon: 'home' }}
            items={[
              { label: t('nav.products'), href: '/products' },
              { label: productName },
            ]}
          />
        </div>
      </div>

      {/* ========== Main Product Section ========== */}
      <section className="w-full py-8 md:py-12">
        <div className="max-w-7xl mx-auto px-4 md:px-6">
          <div className="grid grid-cols-1 lg:grid-cols-2 gap-8 md:gap-12">
            {/* ===== Left: Image Gallery ===== */}
            <motion.div
              initial={{ opacity: 0, x: -20 }}
              animate={{ opacity: 1, x: 0 }}
              transition={{ duration: 0.5 }}
            >
              {/* Main Image */}
              <div className="relative aspect-square overflow-hidden group">
                {hasImages && !imgErrors[activeImageIndex] ? (
                  <Image
                    src={images[activeImageIndex]}
                    alt={`${productName} - view ${activeImageIndex + 1}`}
                    className="w-full h-full object-contain"
                    onError={() =>
                      setImgErrors((prev) => ({ ...prev, [activeImageIndex]: true }))
                    }
                  />
                ) : (
                  <div className="w-full h-full flex items-center justify-center">
                    <div className="text-center text-muted-foreground">
                      <ImageOff className="size-12 mx-auto mb-2 opacity-50" />
                      <p className="text-sm">
                        {t('productDetail.noImage')}
                      </p>
                    </div>
                  </div>
                )}

                {/* Arrow buttons */}
                {hasImages && images.length > 1 && (
                  <>
                    <button
                      onClick={handlePrev}
                      className="absolute left-3 top-1/2 -translate-y-1/2 size-10 rounded-full bg-background/90 backdrop-blur border border-border flex items-center justify-center text-foreground hover:bg-primary hover:text-primary-foreground transition-colors z-10 md:opacity-0 md:group-hover:opacity-100"
                      aria-label="Previous image"
                    >
                      <ChevronLeft className="size-5" />
                    </button>
                    <button
                      onClick={handleNext}
                      className="absolute right-3 top-1/2 -translate-y-1/2 size-10 rounded-full bg-background/90 backdrop-blur border border-border flex items-center justify-center text-foreground hover:bg-primary hover:text-primary-foreground transition-colors z-10 md:opacity-0 md:group-hover:opacity-100"
                      aria-label="Next image"
                    >
                      <ChevronRight className="size-5" />
                    </button>
                  </>
                )}

                {/* Dot indicators */}
                {hasImages && images.length > 1 && (
                  <div className="absolute bottom-4 left-1/2 -translate-x-1/2 flex gap-2">
                    {images.map((_, i) => (
                      <button
                        key={i}
                        onClick={() => setActiveImageIndex(i)}
                        className={`size-2 rounded-full transition-colors ${
                          i === activeImageIndex
                            ? 'bg-primary w-6'
                            : 'bg-foreground/30 hover:bg-foreground/50'
                        }`}
                        aria-label={`Go to image ${i + 1}`}
                      />
                    ))}
                  </div>
                )}
              </div>

              {/* Thumbnails */}
              {hasImages && images.length > 1 && (
                <div className="mt-4 flex gap-2 overflow-x-auto pb-2">
                  {images.map((img, i) => (
                    <button
                      key={i}
                      onClick={() => setActiveImageIndex(i)}
                      className={`shrink-0 w-20 h-20 border rounded-sm overflow-hidden transition-colors ${
                        i === activeImageIndex
                          ? 'border-primary ring-2 ring-primary/30'
                          : 'border-border hover:border-muted-foreground'
                      }`}
                    >
                      {!imgErrors[i + 100] ? (
                        <Image
                          src={img}
                          alt={`Thumbnail ${i + 1}`}
                          className="w-full h-full object-contain p-1 bg-background"
                          onError={() =>
                            setImgErrors((prev) => ({ ...prev, [i + 100]: true }))
                          }
                        />
                      ) : (
                        <div className="w-full h-full flex items-center justify-center bg-background">
                          <ImageOff className="size-5 text-muted-foreground/50" />
                        </div>
                      )}
                      {i === 0 && (
                        <div className="absolute -mt-5 ml-1">
                          <Badge className="bg-primary text-[10px] px-1.5 py-0">
                            Main
                          </Badge>
                        </div>
                      )}
                    </button>
                  ))}
                  {images.length < 6 &&
                    Array.from({ length: 6 - images.length }).map((_, i) => (
                      <div
                        key={`empty-${i}`}
                        className="shrink-0 w-20 h-20 border border-dashed border-border/50 rounded-sm bg-background/50"
                      />
                    ))}
                </div>
              )}
            </motion.div>

            {/* ===== Right: Product Info ===== */}
            <motion.div
              initial={{ opacity: 0, x: 20 }}
              animate={{ opacity: 1, x: 0 }}
              transition={{ duration: 0.5, delay: 0.1 }}
              className="flex flex-col"
            >
              <h1 className="text-2xl md:text-3xl font-bold text-foreground mb-4 tracking-tight">
                {productName}
              </h1>

              {/* Feature Badges */}
              {product.features && product.features.length > 0 && (
                <div className="flex flex-wrap gap-2 mb-5">
                  {product.features.slice(0, 6).map((feat, i) => (
                    <Badge
                      key={i}
                      variant="outline"
                      className="border-border/70 text-muted-foreground bg-card/50"
                    >
                      <CheckCircle2 className="size-3 mr-1 text-primary" />
                      {getI18nValue(feat, language)}
                    </Badge>
                  ))}
                </div>
              )}

              <p className="text-muted-foreground leading-relaxed mb-6">
                {productDesc}
              </p>

              {/* Specs Section - Modern Soft Style */}
              {allFields.length > 0 && (
                <div className="mb-6">
                  {/* Section Header */}
                  <div className="mb-5">
                    <div className="flex items-center gap-2.5 mb-2">
                      <div className="w-8 h-[3px] rounded-full bg-gradient-to-r from-primary to-primary/30" />
                      <h3 className="text-lg font-semibold text-foreground">
                        {t('productDetail.specs')}
                      </h3>
                    </div>
                    <p className="text-sm text-muted-foreground ml-10.5">
                      {t('productDetail.specsHint')}
                    </p>
                  </div>

                  {/* Spec Cards - Soft info grid */}
                  <div className="grid grid-cols-2 gap-3">
                    {allFields.map((f, i) => (
                      <div
                        key={i}
                        className="group bg-card/40 hover:bg-card/70 transition-all duration-200 rounded-lg p-3.5 border border-border/40 hover:border-border/80"
                      >
                        <div className="text-xs text-muted-foreground mb-1">
                          {getI18nValue(f.key, language)}
                        </div>
                        <div className="text-sm font-medium text-foreground">
                          {getI18nValue(f.value, language)}
                        </div>
                      </div>
                    ))}
                  </div>

                  {/* Bottom hint */}
                  <div className="mt-3 flex items-center justify-center gap-2">
                    <div className="size-1 rounded-full bg-primary/40" />
                    <span className="text-xs text-muted-foreground/70">
                       {t('productDetail.specsCount').replace('{n}', String(allFields.length))}
                    </span>
                    <div className="size-1 rounded-full bg-primary/40" />
                  </div>
                </div>
              )}

              {/* CTA Buttons */}
              <div className="flex flex-col sm:flex-row gap-3 mt-auto pt-2">
                <Button
                  className="flex-1 bg-primary hover:bg-primary/90 text-primary-foreground h-11"
                  onClick={handleInquiry}
                >
                  <ShieldCheck className="size-4 mr-2" />
                  {t('productDetail.getQuotation')}
                </Button>
                <Button
                  variant="outline"
                  className="flex-1 h-11 border-green-600/50 text-green-400 hover:bg-green-600/10 hover:text-green-300 hover:border-green-500"
                  onClick={handleWhatsApp}
                >
                  <MessageCircle className="size-4 mr-2" />
                  WhatsApp
                </Button>
              </div>
            </motion.div>
          </div>
        </div>
      </section>

      {/* ========== Product Gallery (Large Views) ========== */}
      {images.length > 1 && (
        <section className="w-full py-10 md:py-14 border-t border-border bg-muted/20">
          <div className="max-w-7xl mx-auto px-4 md:px-6">
            <div className="text-center mb-8 md:mb-10">
              <h2 className="text-2xl md:text-3xl font-bold text-foreground mb-2">
                {t('productDetail.gallery')}
              </h2>
              <p className="text-muted-foreground max-w-xl mx-auto text-sm">
                {t('productDetail.gallerySubtitle')}
              </p>
            </div>

            <div className="grid grid-cols-1 gap-8 max-w-4xl mx-auto">
              {images.slice(1).map((img, i) => {
                const realIndex = i + 1;
                const isError = imgErrors[realIndex + 200];
                return (
                  <div key={realIndex} className="group">
                    <div className="relative aspect-square overflow-hidden">
                      {!isError ? (
                        <Image
                          src={img}
                          alt={`${productName} - view ${realIndex + 1}`}
                          className="w-full h-full object-contain transition-transform duration-700 group-hover:scale-105"
                          onError={() =>
                            setImgErrors((prev) => ({ ...prev, [realIndex + 200]: true }))
                          }
                        />
                      ) : (
                        <div className="w-full h-full flex items-center justify-center">
                          <ImageOff className="size-10 text-muted-foreground/50" />
                        </div>
                      )}
                    </div>
                  </div>
                );
              })}
            </div>
          </div>
        </section>
      )}

      {/* ========== Application Scenarios ========== */}
      {product.applicationScenes && product.applicationScenes.length > 0 && (
        <section className="w-full py-10 md:py-14 border-t border-border">
          <div className="max-w-7xl mx-auto px-4 md:px-6">
            <div className="text-center mb-8">
              <Badge
                variant="outline"
                className="border-primary/40 text-primary bg-primary/5 mb-3"
              >
                 <Globe className="size-3 mr-1" />
                 {t('productDetail.applicationsBadge')}
               </Badge>
              <h2 className="text-2xl md:text-3xl font-bold text-foreground mb-2">
                {t('productDetail.applications')}
              </h2>
              <p className="text-muted-foreground max-w-xl mx-auto">
                {t('productDetail.applicationsDesc') ||
                  'Versatile design suitable for various indoor and outdoor environments.'}
              </p>
            </div>

            <div className="flex flex-wrap justify-center gap-3">
              {product.applicationScenes.map((scene, i) => (
                <motion.div
                  key={i}
                  initial={{ opacity: 0, y: 16 }}
                  whileInView={{ opacity: 1, y: 0 }}
                  viewport={{ once: true }}
                  transition={{ duration: 0.4, delay: i * 0.05 }}
                  className="px-5 py-2.5 bg-card border border-border rounded-sm flex items-center gap-2 group"
                >
                  <CheckCircle2 className="size-4 text-primary shrink-0" />
                  <span className="text-sm font-medium text-foreground whitespace-nowrap">{getI18nValue(scene, language)}</span>
                </motion.div>
              ))}
            </div>
          </div>
        </section>
      )}

      {/* Back to products */}
      <section className="w-full py-8 border-t border-border">
        <div className="max-w-7xl mx-auto px-4 md:px-6">
          <Button variant="outline" onClick={() => navigate('/products')}>
            <ArrowLeft className="size-4 mr-2" />
            {t('productDetail.backToList')}
          </Button>
        </div>
      </section>
    </div>
  );
}
