import { useCallback, useEffect, useMemo, useRef, useState } from 'react';
import {
  BookOpen,
  ChevronLeft,
  ChevronRight,
  Download,
  FileText,
  Loader2,
  Minus,
  Plus,
  RotateCw,
  ZoomIn,
  AlertTriangle,
  RefreshCw,
} from 'lucide-react';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { useI18n } from '@/i18n/I18nContext';
import { logger } from '@lark-apaas/client-toolkit-lite';
import { UniversalLink } from '@lark-apaas/client-toolkit-lite';

interface PDFViewerProps {
  pdfUrl: string;
  fileName?: string;
  containerHeight?: string;
  minHeight?: string;
  maxHeight?: string;
  showToolbar?: boolean;
}

const PDF_JS_VERSION = '3.11.174';
const PDF_JS_URL = `https://cdnjs.cloudflare.com/ajax/libs/pdf.js/${PDF_JS_VERSION}/pdf.min.js`;
const PDF_WORKER_URL = `https://cdnjs.cloudflare.com/ajax/libs/pdf.js/${PDF_JS_VERSION}/pdf.worker.min.js`;

declare global {
  interface Window {
    pdfjsLib?: {
      getDocument: (src: string | { url: string; data?: ArrayBuffer | Uint8Array }) => {
        promise: Promise<any>;
        onProgress: (callback: (data: { loaded: number; total: number }) => void) => void;
        destroy: () => void;
      };
      GlobalWorkerOptions: {
        workerSrc: string;
      };
    };
  }
}

let pdfJsLoadingPromise: Promise<void> | null = null;

function loadPdfJs(): Promise<void> {
  if (typeof window === 'undefined') return Promise.resolve();
  if (window.pdfjsLib) return Promise.resolve();
  if (pdfJsLoadingPromise) return pdfJsLoadingPromise;

  pdfJsLoadingPromise = new Promise((resolve, reject) => {
    const script = document.createElement('script');
    script.src = PDF_JS_URL;
    script.async = true;
    script.onload = () => {
      if (window.pdfjsLib) {
        window.pdfjsLib.GlobalWorkerOptions.workerSrc = PDF_WORKER_URL;
        resolve();
      } else {
        reject(new Error('PDF.js failed to load'));
      }
    };
    script.onerror = () => reject(new Error('Failed to load PDF.js script'));
    document.head.appendChild(script);
  });

  return pdfJsLoadingPromise;
}

export default function PDFViewer({
  pdfUrl,
  fileName = 'catalog.pdf',
  minHeight = '500px',
  maxHeight = '900px',
  showToolbar = true,
}: PDFViewerProps) {
  const { t } = useI18n();
  const containerRef = useRef<HTMLDivElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const loadingTaskRef = useRef<any>(null);
  const pdfDocRef = useRef<any>(null);

  const [pdfReady, setPdfReady] = useState(false);
  const [currentPage, setCurrentPage] = useState(1);
  const [totalPages, setTotalPages] = useState(0);
  const [scale, setScale] = useState(1.5);
  const [rotation, setRotation] = useState(0);
  const [loading, setLoading] = useState(true);
  const [rendering, setRendering] = useState(false);
  const [loadProgress, setLoadProgress] = useState(0);
  const [error, setError] = useState<string | null>(null);
  const [pageInput, setPageInput] = useState('1');

  // Load PDF.js + PDF document
  useEffect(() => {
    let cancelled = false;

    async function init() {
      setLoading(true);
      setError(null);
      setLoadProgress(0);
      setPdfReady(false);
      setCurrentPage(1);
      setPageInput('1');
      setTotalPages(0);

      try {
        await loadPdfJs();
        if (cancelled || !window.pdfjsLib) return;

        // Destroy previous loading task if exists
        if (loadingTaskRef.current) {
          try {
            loadingTaskRef.current.destroy();
          } catch (e) {
            logger.warn('PDF loadingTask destroy error:', String(e));
          }
          loadingTaskRef.current = null;
        }

        const loadingTask = window.pdfjsLib.getDocument({ url: pdfUrl });
        loadingTaskRef.current = loadingTask;

        // @ts-expect-error - pdf.js onProgress is a property setter in runtime but typed as method
        loadingTask.onProgress = (data: { loaded: number; total: number }) => {
          if (cancelled) return;
          if (data.total > 0) {
            setLoadProgress(Math.min(99, Math.round((data.loaded / data.total) * 100)));
          }
        };

        const doc = await loadingTask.promise;
        if (cancelled) return;

        pdfDocRef.current = doc;
        setTotalPages(doc.numPages);
        setPdfReady(true);
        setLoading(false);
      } catch (err) {
        if (cancelled) return;
        logger.warn('PDF load failed:', String(err));
        setError(err instanceof Error ? err.message : String(err));
        setLoading(false);
      }
    }

    init();

    return () => {
      cancelled = true;
      if (loadingTaskRef.current) {
        try {
          loadingTaskRef.current.destroy();
        } catch (e) {
          // ignore
        }
        loadingTaskRef.current = null;
      }
      pdfDocRef.current = null;
    };
  }, [pdfUrl]);

  // Render current page (supports cancellation on unmount / param change)
  const renderTaskRef = useRef<any>(null);
  const renderPage = useCallback(async (pageNum: number, currentScale: number, currentRotation: number) => {
    const doc = pdfDocRef.current;
    const canvas = canvasRef.current;
    if (!doc || !canvas) return;

    // Cancel any in-progress render before starting a new one
    if (renderTaskRef.current) {
      try {
        renderTaskRef.current.cancel();
      } catch (e) {
        logger.warn('PDF render cancel error:', String(e));
      }
      renderTaskRef.current = null;
    }

    setRendering(true);
    try {
      const page = await doc.getPage(pageNum);
      const viewport = page.getViewport({ scale: currentScale, rotation: currentRotation });

      // Handle high DPI screens
      const outputScale = window.devicePixelRatio || 1;
      const context = canvas.getContext('2d');
      if (!context) return;

      canvas.width = Math.floor(viewport.width * outputScale);
      canvas.height = Math.floor(viewport.height * outputScale);
      canvas.style.width = `${Math.floor(viewport.width)}px`;
      canvas.style.height = `${Math.floor(viewport.height)}px`;

      const transform = outputScale !== 1 ? [outputScale, 0, 0, outputScale, 0, 0] : undefined;

      const renderTask = page.render({
        canvasContext: context,
        viewport,
        transform,
      });
      renderTaskRef.current = renderTask;

      await renderTask.promise;
      renderTaskRef.current = null;
    } catch (err: any) {
      // RenderingCancelledException is expected when user navigates away / changes page/scale quickly
      if (err?.name === 'RenderingCancelledException' || err?.message?.includes('Rendering cancelled')) {
        logger.info('PDF render cancelled (expected)');
      } else {
        logger.warn('PDF render error:', String(err));
      }
    } finally {
      setRendering(false);
    }
  }, []);

  // Trigger render when page/scale/rotation changes or pdf becomes ready
  useEffect(() => {
    if (!pdfReady || !canvasRef.current) return;
    renderPage(currentPage, scale, rotation);

    return () => {
      // Cancel in-progress render when effect re-runs (page/scale/rotation change)
      if (renderTaskRef.current) {
        try {
          renderTaskRef.current.cancel();
        } catch (e) {
          // ignore
        }
        renderTaskRef.current = null;
      }
    };
  }, [pdfReady, currentPage, scale, rotation, renderPage]);

  const handlePrevPage = useCallback(() => {
    setCurrentPage((prev) => Math.max(1, prev - 1));
  }, []);

  const handleNextPage = useCallback(() => {
    setCurrentPage((prev) => Math.min(totalPages, prev + 1));
  }, [totalPages]);

  const handleZoomIn = useCallback(() => {
    setScale((prev) => Math.min(prev + 0.25, 4));
  }, []);

  const handleZoomOut = useCallback(() => {
    setScale((prev) => Math.max(prev - 0.25, 0.5));
  }, []);

  const handleFitWidth = useCallback(async () => {
    const doc = pdfDocRef.current;
    const container = containerRef.current;
    if (!doc || !container) return;
    try {
      const page = await doc.getPage(currentPage);
      const viewport = page.getViewport({ scale: 1, rotation });
      const containerWidth = container.clientWidth - 32; // padding
      const newScale = containerWidth / viewport.width;
      setScale(Math.max(0.5, Math.min(newScale, 4)));
    } catch (e) {
      logger.warn('fit width error:', String(e));
    }
  }, [currentPage, rotation]);

  const handleRotate = useCallback(() => {
    setRotation((prev) => (prev + 90) % 360);
  }, []);

  const handlePageInputChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    setPageInput(e.target.value);
  };

  const handlePageInputBlur = () => {
    const num = parseInt(pageInput, 10);
    if (!Number.isNaN(num) && num >= 1 && num <= totalPages) {
      setCurrentPage(num);
    } else {
      setPageInput(String(currentPage));
    }
  };

  const handlePageInputKeyDown = (e: React.KeyboardEvent<HTMLInputElement>) => {
    if (e.key === 'Enter') {
      handlePageInputBlur();
      (e.target as HTMLInputElement).blur();
    }
  };

  const handleRetry = useCallback(() => {
    setError(null);
    setLoading(true);
    setLoadProgress(0);
    // Force re-mount effect by toggling state is complex; instead re-trigger via url change
    // Simplest: reload the page's current state by recreating the loading
    pdfJsLoadingPromise = null;
    // Re-trigger by assigning same url - but effect depends on pdfUrl.
    // Use a key pattern instead - we'll reload by destroying and re-initing.
    if (loadingTaskRef.current) {
      try {
        loadingTaskRef.current.destroy();
      } catch (e) {
        // ignore
      }
      loadingTaskRef.current = null;
    }
    pdfDocRef.current = null;
    setPdfReady(false);

    async function reload() {
      try {
        await loadPdfJs();
        if (!window.pdfjsLib) throw new Error('PDF.js not available');

        const loadingTask = window.pdfjsLib.getDocument({ url: pdfUrl });
        loadingTaskRef.current = loadingTask;

        // @ts-expect-error - pdf.js onProgress is a property setter in runtime but typed as method
        loadingTask.onProgress = (data: { loaded: number; total: number }) => {
          if (data.total > 0) {
            setLoadProgress(Math.min(99, Math.round((data.loaded / data.total) * 100)));
          }
        };

        const doc = await loadingTask.promise;
        pdfDocRef.current = doc;
        setTotalPages(doc.numPages);
        setPdfReady(true);
        setLoading(false);
        setCurrentPage(1);
        setPageInput('1');
      } catch (err) {
        logger.warn('PDF reload failed:', String(err));
        setError(err instanceof Error ? err.message : String(err));
        setLoading(false);
      }
    }

    reload();
  }, [pdfUrl]);

  const handleDownload = useCallback(async () => {
    try {
      const res = await fetch(pdfUrl);
      const blob = await res.blob();
      const url = URL.createObjectURL(blob);
      const a = document.createElement('a');
      a.href = url;
      a.download = fileName;
      document.body.appendChild(a);
      a.click();
      document.body.removeChild(a);
      URL.revokeObjectURL(url);
    } catch (err) {
      logger.warn('PDF download failed:', String(err));
      // 兜底：直接在新窗口打开
      window.open(pdfUrl, '_blank', 'noopener,noreferrer');
    }
  }, [pdfUrl, fileName]);

  const progressLabel = useMemo(() => {
    if (!loading) return '';
    return loadProgress > 0 ? `${loadProgress}%` : '';
  }, [loading, loadProgress]);

  return (
    <div className="flex flex-col w-full bg-card border border-border/40 rounded-sm overflow-hidden">
      {/* Toolbar */}
      {showToolbar && (
        <div className="flex flex-wrap items-center gap-2 px-3 py-2 border-b border-border/40 bg-muted/30">
          {/* Page navigation */}
          <div className="flex items-center gap-1">
            <Button
              variant="ghost"
              size="icon"
              className="size-8"
              onClick={handlePrevPage}
              disabled={!pdfReady || currentPage <= 1 || rendering}
              aria-label={t('pdf.prevPage') || 'Previous page'}
            >
              <ChevronLeft className="size-4" />
            </Button>
            <div className="flex items-center gap-1 text-sm">
              <Input
                type="text"
                inputMode="numeric"
                value={pageInput}
                onChange={handlePageInputChange}
                onBlur={handlePageInputBlur}
                onKeyDown={handlePageInputKeyDown}
                className="w-12 h-8 text-center text-xs bg-background/60"
                disabled={!pdfReady}
                aria-label={t('pdf.pageNumber') || 'Page number'}
              />
              <span className="text-muted-foreground whitespace-nowrap">
                / {totalPages || '—'}
              </span>
            </div>
            <Button
              variant="ghost"
              size="icon"
              className="size-8"
              onClick={handleNextPage}
              disabled={!pdfReady || currentPage >= totalPages || rendering}
              aria-label={t('pdf.nextPage') || 'Next page'}
            >
              <ChevronRight className="size-4" />
            </Button>
          </div>

          <div className="h-5 w-px bg-border/60 mx-1 hidden sm:block" />

          {/* Zoom controls */}
          <div className="flex items-center gap-1">
            <Button
              variant="ghost"
              size="icon"
              className="size-8"
              onClick={handleZoomOut}
              disabled={!pdfReady || scale <= 0.5 || rendering}
              aria-label={t('pdf.zoomOut') || 'Zoom out'}
            >
              <Minus className="size-4" />
            </Button>
            <span className="text-xs text-muted-foreground w-14 text-center tabular-nums">
              {Math.round(scale * 100)}%
            </span>
            <Button
              variant="ghost"
              size="icon"
              className="size-8"
              onClick={handleZoomIn}
              disabled={!pdfReady || scale >= 4 || rendering}
              aria-label={t('pdf.zoomIn') || 'Zoom in'}
            >
              <Plus className="size-4" />
            </Button>
            <Button
              variant="ghost"
              size="icon"
              className="size-8"
              onClick={handleFitWidth}
              disabled={!pdfReady || rendering}
              aria-label={t('pdf.fitWidth') || 'Fit width'}
              title={t('pdf.fitWidth') || 'Fit width'}
            >
              <ZoomIn className="size-4" />
            </Button>
            <Button
              variant="ghost"
              size="icon"
              className="size-8"
              onClick={handleRotate}
              disabled={!pdfReady || rendering}
              aria-label={t('pdf.rotate') || 'Rotate'}
              title={t('pdf.rotate') || 'Rotate'}
            >
              <RotateCw className="size-4" />
            </Button>
          </div>

          <div className="flex-1" />

          {/* Actions */}
          <div className="flex items-center gap-1">
            <Button variant="outline" size="sm" asChild disabled={!pdfReady}>
              <UniversalLink to={pdfUrl} target="_blank" rel="noopener noreferrer">
                <BookOpen className="size-3.5 mr-1.5" />
                <span className="hidden sm:inline">{t('pdf.openNewTab') || 'Open'}</span>
              </UniversalLink>
            </Button>
            <Button size="sm" onClick={handleDownload} disabled={!pdfReady}>
              <Download className="size-3.5 mr-1.5" />
              <span className="hidden sm:inline">{t('pdf.download') || 'Download'}</span>
            </Button>
          </div>
        </div>
      )}

      {/* PDF canvas area */}
      <div
        ref={containerRef}
        className="w-full relative flex items-start justify-center overflow-auto bg-muted/20"
        style={{ minHeight, maxHeight }}
      >
        {loading && (
          <div className="absolute inset-0 flex flex-col items-center justify-center p-8 text-center bg-card/60 backdrop-blur-sm z-10">
            <Loader2 className="size-10 text-primary animate-spin mb-4" />
            <div className="text-sm text-foreground font-medium mb-2">
              {t('pdf.loading') || 'Loading PDF...'}
            </div>
            <div className="w-64 h-1.5 bg-muted rounded-full overflow-hidden mb-2">
              <div
                className="h-full bg-primary transition-all duration-300"
                style={{ width: `${loadProgress}%` }}
              />
            </div>
            {progressLabel && (
              <div className="text-xs text-muted-foreground tabular-nums">
                {progressLabel}
              </div>
            )}
          </div>
        )}

        {error && (
          <div className="absolute inset-0 flex flex-col items-center justify-center p-8 text-center bg-card/80 backdrop-blur-sm z-10">
            <div className="size-14 rounded-full bg-destructive/10 flex items-center justify-center mb-4">
              <AlertTriangle className="size-7 text-destructive" />
            </div>
            <h3 className="text-base font-semibold text-foreground mb-2">
              {t('pdf.loadFailed') || 'Failed to load PDF'}
            </h3>
            <p className="text-sm text-muted-foreground max-w-md mb-5">
              {t('pdf.loadFailedDesc') || 'The PDF could not be loaded. Please try again or download the file directly.'}
            </p>
            {error && !pdfUrl.startsWith('blob:') && (
              <p className="text-xs text-muted-foreground/70 font-mono mb-5 max-w-md break-all">
                URL: {pdfUrl}
              </p>
            )}
            <div className="flex flex-wrap items-center justify-center gap-2">
              <Button size="sm" onClick={handleRetry}>
                <RefreshCw className="size-4 mr-1.5" />
                {t('pdf.retry') || 'Retry'}
              </Button>
              <Button size="sm" onClick={handleDownload}>
                  <Download className="size-4 mr-1.5" />
                  {t('pdf.download') || 'Download PDF'}
                </Button>
              <Button size="sm" variant="outline" asChild>
                <UniversalLink to={pdfUrl} target="_blank" rel="noopener noreferrer">
                  <BookOpen className="size-4 mr-1.5" />
                  {t('pdf.openNewTab') || 'Open in new tab'}
                </UniversalLink>
              </Button>
            </div>
          </div>
        )}

        {rendering && !loading && !error && (
          <div className="absolute top-3 right-3 z-10 flex items-center gap-2 px-2.5 py-1.5 rounded-md bg-card/80 backdrop-blur-sm text-xs text-muted-foreground border border-border/40">
            <Loader2 className="size-3.5 animate-spin" />
            {t('pdf.rendering') || 'Rendering...'}
          </div>
        )}

        {pdfReady && !error && (
          <div className="p-4">
            <div className="bg-white shadow-lg inline-block">
              <canvas ref={canvasRef} className="block" />
            </div>
          </div>
        )}

        {!pdfReady && !loading && !error && (
          <div className="absolute inset-0 flex items-center justify-center text-muted-foreground text-sm">
            <FileText className="size-8 mr-2" />
            {t('pdf.placeholder') || 'PDF viewer'}
          </div>
        )}
      </div>

      {/* Bottom info bar */}
      {showToolbar && fileName && (
        <div className="flex items-center justify-between gap-3 px-3 py-2 border-t border-border/40 bg-muted/20 text-xs text-muted-foreground">
          <div className="flex items-center gap-2 min-w-0">
            <FileText className="size-4 text-primary shrink-0" />
            <span className="truncate">{fileName}</span>
          </div>
          {pdfReady && (
            <div className="shrink-0 tabular-nums">
              {t('pdf.page') || 'Page'} {currentPage} / {totalPages}
            </div>
          )}
        </div>
      )}
    </div>
  );
}
