/**
 * WhatsApp 链接规范化工具
 *
 * 支持以下输入格式，统一输出完整的 wa.me 链接：
 * - 纯号码："8613800138000" / "13800138000" / "+86 138 0013 8000"
 * - wa.me 链接："https://wa.me/8613800138000" / "wa.me/8613800138000"
 * - api.whatsapp.com 链接："https://api.whatsapp.com/send?phone=8613800138000"
 * - 带 text 参数的完整链接（原样透传 text 参数）
 *
 * @param input 用户输入的 WhatsApp 号码或链接
 * @param defaultText 可选的默认预填文本（仅当输入未包含 text 参数时追加）
 * @returns 规范化后的 wa.me URL 字符串；输入为空时返回空字符串
 */
export function normalizeWhatsAppUrl(input: string, defaultText?: string): string {
  if (!input || !input.trim()) return '';

  const trimmed = input.trim();

  // 提取号码：去掉所有非数字字符
  const extractPhone = (raw: string): string => raw.replace(/\D/g, '');

  let phone = '';
  let textParam = '';

  // 情况 1：完整 URL（含 https:// 或 http:// 或 以 wa.me / api.whatsapp.com 开头）
  if (/^(https?:\/\/)?(wa\.me|api\.whatsapp\.com)\//i.test(trimmed)) {
    try {
      const urlStr = trimmed.startsWith('http') ? trimmed : `https://${trimmed}`;
      const url = new URL(urlStr);

      if (url.hostname.endsWith('wa.me')) {
        // wa.me/8613800138000
        const pathPhone = url.pathname.replace(/\//g, '');
        phone = extractPhone(pathPhone);
      } else if (url.hostname.endsWith('api.whatsapp.com')) {
        // api.whatsapp.com/send?phone=xxx
        phone = extractPhone(url.searchParams.get('phone') || '');
      }

      // 保留已有的 text 参数
      const existingText = url.searchParams.get('text');
      if (existingText) textParam = existingText;
    } catch {
      // URL 解析失败，回退到纯号码处理
      phone = extractPhone(trimmed);
    }
  } else {
    // 情况 2：纯号码（可能含 +、空格、-、括号等）
    phone = extractPhone(trimmed);
  }

  if (!phone) return '';

  // 若号码以 0 开头且长度合理，假定是国内手机号，补 86 前缀
  if (phone.startsWith('0') && phone.length >= 11) {
    phone = '86' + phone.replace(/^0+/, '');
  }

  const baseUrl = `https://wa.me/${phone}`;

  // 优先使用 URL 中已有的 text；否则追加默认文本
  const text = textParam || defaultText;
  if (text) {
    return `${baseUrl}?text=${encodeURIComponent(text)}`;
  }

  return baseUrl;
}
