import { useState } from 'react';
import { NavLink, useNavigate } from 'react-router-dom';
import { Menu, X, ChevronDown, Globe } from 'lucide-react';
import { useI18n } from '@/i18n/I18nContext';
import { Button } from '@/components/ui/button';
import { imgPath } from '@/utils/img-path';
import type { Language } from '@/i18n/translations';
import { useFooterSettings } from '@/hooks/useFooterSettings';

const NAV_ITEMS = [
  { path: '/', key: 'nav.home' },
  { path: '/products', key: 'nav.products' },
  { path: '/news', key: 'nav.news' },
  { path: '/about', key: 'nav.about' },
  { path: '/contact', key: 'nav.contact' },
];

const LANGUAGES: { code: Language; label: string; flag: string }[] = [
  { code: 'en', label: 'English', flag: 'EN' },
  { code: 'zh', label: '中文', flag: '中' },
  { code: 'es', label: 'Español', flag: 'ES' },
  { code: 'ja', label: '日本語', flag: '日' },
];

export default function Header() {
  const { t, language, setLanguage } = useI18n();
  const navigate = useNavigate();
  const [mobileMenuOpen, setMobileMenuOpen] = useState(false);
  const [langDropdown, setLangDropdown] = useState(false);
  const { settings } = useFooterSettings({ preferRemote: true });

  const logoSrc = settings.headerLogo || imgPath('/images/owell-logo.png');

  const currentLang = LANGUAGES.find((l) => l.code === language) ?? LANGUAGES[0];

  return (
    <header className="sticky top-0 z-50 w-full bg-background/80 backdrop-blur-xl border-b border-border/40 shadow-[0_1px_0_0_rgba(255,255,255,0.02)]">
      {/* Top red beam accent */}
      <div className="absolute top-0 left-0 right-0 h-[2px] bg-gradient-to-r from-transparent via-primary/80 to-transparent opacity-90" />
      <div className="max-w-7xl mx-auto px-4 md:px-6">
        <div className="flex h-16 items-center justify-between">
          {/* Logo */}
          <NavLink to="/" className="flex items-center gap-2 shrink-0">
            <img
              src={logoSrc}
              alt="OWELL Industrial"
              width={44}
              height={44}
              loading="eager"
              fetchPriority="high"
              className="h-10 md:h-11 w-auto object-contain bg-transparent"
            />
          </NavLink>

          {/* Desktop Nav */}
          <nav className="hidden md:flex items-center gap-1">
            {NAV_ITEMS.map((item) => (
              <NavLink
                key={item.path}
                to={item.path}
                end={item.path === '/'}
                className={({ isActive }) =>
                  `relative px-4 py-2 text-sm font-medium transition-all duration-200 ${
                    isActive
                      ? 'text-foreground'
                      : 'text-muted-foreground hover:text-foreground'
                  }`
                }
              >
                {({ isActive }) => (
                  <>
                    <span>{t(item.key)}</span>
                    <span
                      className={`absolute bottom-0 left-1/2 -translate-x-1/2 h-[2px] bg-primary rounded-full transition-all duration-300 ${
                        isActive ? 'w-6 opacity-100' : 'w-0 opacity-0'
                      }`}
                    />
                  </>
                )}
              </NavLink>
            ))}
          </nav>

          {/* Right actions */}
          <div className="flex items-center gap-2">
            {/* Language Switcher */}
            <div className="relative">
              <Button
                variant="ghost"
                size="sm"
                onClick={() => setLangDropdown(!langDropdown)}
                className="gap-1 text-muted-foreground hover:text-foreground"
              >
                <Globe className="size-4" />
                <span className="hidden sm:inline text-sm">{currentLang.flag}</span>
                <ChevronDown className="size-3 hidden sm:inline" />
              </Button>
              {langDropdown && (
                <div className="absolute right-0 top-full mt-1 w-40 rounded-lg border border-border bg-card shadow-lg overflow-hidden z-50">
                  {LANGUAGES.map((lang) => (
                    <button
                      key={lang.code}
                      onClick={() => {
                        setLanguage(lang.code);
                        setLangDropdown(false);
                      }}
                      className={`w-full px-4 py-2 text-left text-sm flex items-center justify-between transition-colors ${
                        language === lang.code
                          ? 'bg-primary/10 text-primary'
                          : 'text-foreground hover:bg-accent/10'
                      }`}
                    >
                      <span>{lang.label}</span>
                      <span className="text-xs text-muted-foreground">{lang.flag}</span>
                    </button>
                  ))}
                </div>
              )}
            </div>

            {/* Get Quote CTA */}
            <Button
              onClick={() => navigate('/contact')}
              className="hidden sm:inline-flex bg-primary hover:bg-primary/90 text-primary-foreground shadow-[0_0_20px_rgba(230,57,70,0.25)] hover:shadow-[0_0_28px_rgba(230,57,70,0.4)] transition-shadow duration-300"
              size="sm"
            >
              {t('nav.getQuote')}
            </Button>

            {/* Mobile menu button */}
            <Button
              variant="ghost"
              size="icon"
              className="md:hidden"
              onClick={() => setMobileMenuOpen(!mobileMenuOpen)}
            >
              {mobileMenuOpen ? <X className="size-5" /> : <Menu className="size-5" />}
            </Button>
          </div>
        </div>
      </div>

      {/* Mobile Menu */}
      {mobileMenuOpen && (
        <div className="md:hidden border-t border-border/60 bg-background/95 backdrop-blur-md">
          <nav className="flex flex-col p-4 gap-1">
            {NAV_ITEMS.map((item) => (
              <NavLink
                key={item.path}
                to={item.path}
                end={item.path === '/'}
                onClick={() => setMobileMenuOpen(false)}
                className={({ isActive }) =>
                  `px-4 py-3 rounded-md text-sm font-medium transition-colors ${
                    isActive
                      ? 'text-primary bg-primary/10'
                      : 'text-muted-foreground hover:text-foreground hover:bg-accent/10'
                  }`
                }
              >
                {t(item.key)}
              </NavLink>
            ))}
            <Button
              onClick={() => {
                navigate('/contact');
                setMobileMenuOpen(false);
              }}
              className="mt-2 bg-primary text-primary-foreground w-full"
            >
              {t('nav.getQuote')}
            </Button>
          </nav>
        </div>
      )}
    </header>
  );
}
