/**
 * 全站模块同步服务
 * 提供统一的同步接口，管理各模块的 dirty 状态
 * 使用 React Context 实现跨页面共享
 */

import {
  createContext,
  useContext,
  useState,
  useEffect,
  useCallback,
  useRef,
  useMemo,
  type ReactNode,
} from 'react';
import { scopedStorage, logger } from '@lark-apaas/client-toolkit-lite';
import { toast } from 'sonner';
import {
  createOrUpdateFile,
  getFileContent,
  decodeBase64Content,
  type GithubConfig,
} from '@/lib/github-api';
import { useGithubConfig } from '@/hooks/useGithubConfig';
import {
  generateImageFilename,
  extractBase64FromDataUrl,
  isLocalBase64Image,
} from '@/hooks/useGithubSync';

const SYNC_STATUS_KEY = '__app_ledlight_sync_status_v1';

export type SyncModuleKey =
  | 'products'
  | 'advantages'
  | 'testimonials'
  | 'features'
  | 'heroSlides'
  | 'about'
  | 'news'
  | 'footer'
  | 'seo'
  | 'categories'
  | 'privacy'
  | 'translations';

export type SyncStatus = 'synced' | 'dirty' | 'syncing' | 'error';

interface SyncStatusMap {
  [key: string]: SyncStatus;
}

const DEFAULT_STATUS: SyncStatusMap = {
  products: 'synced',
  advantages: 'synced',
  testimonials: 'synced',
  features: 'synced',
  heroSlides: 'synced',
  about: 'synced',
  news: 'synced',
  footer: 'synced',
  seo: 'synced',
  categories: 'synced',
  privacy: 'synced',
  translations: 'synced',
};

interface SyncServiceContextType {
  statusMap: SyncStatusMap;
  markDirty: (module: SyncModuleKey) => void;
  markSynced: (module: SyncModuleKey) => void;
  markSyncing: (module: SyncModuleKey) => void;
  markError: (module: SyncModuleKey) => void;
  getStatus: (module: SyncModuleKey) => SyncStatus;
  isDirty: (module: SyncModuleKey) => boolean;
  dirtyCount: number;
  getGithubApiConfig: () => GithubConfig | null;
  syncModule: (
    module: SyncModuleKey,
    label: string,
    syncFn: (config: GithubConfig) => Promise<void>
  ) => Promise<boolean>;
  syncJsonFile: (
    config: GithubConfig,
    path: string,
    data: unknown,
    commitMsg: string
  ) => Promise<void>;
  syncBase64Image: (
    config: GithubConfig,
    dataUrl: string,
    targetPath: string,
    commitMsg: string
  ) => Promise<string>;
  syncImagesInData: <T>(
    config: GithubConfig,
    data: T,
    moduleDir: string,
    imageFields: (keyof T)[]
  ) => Promise<T>;
  fetchRemoteJson: <T>(
    config: GithubConfig | null,
    path: string,
    fallback: T
  ) => Promise<{ data: T; source: 'remote' | 'fallback' }>;
}

const SyncServiceContext = createContext<SyncServiceContextType | null>(null);

function loadSyncStatus(): SyncStatusMap {
  try {
    const saved = scopedStorage.getItem(SYNC_STATUS_KEY);
    if (saved) {
      return { ...DEFAULT_STATUS, ...JSON.parse(saved) };
    }
  } catch {
    // ignore
  }
  return { ...DEFAULT_STATUS };
}

export function SyncServiceProvider({ children }: { children: ReactNode }) {
  const { getGithubApiConfig, isConfigured } = useGithubConfig();
  const [statusMap, setStatusMap] = useState<SyncStatusMap>(loadSyncStatus);
  const initializedRef = useRef(false);

  // 持久化同步状态
  useEffect(() => {
    if (!initializedRef.current) {
      initializedRef.current = true;
      return;
    }
    try {
      scopedStorage.setItem(SYNC_STATUS_KEY, JSON.stringify(statusMap));
    } catch {
      // ignore
    }
  }, [statusMap]);

  const markDirty = useCallback((module: SyncModuleKey) => {
    setStatusMap((prev) => {
      if (prev[module] === 'dirty') return prev;
      return { ...prev, [module]: 'dirty' };
    });
  }, []);

  const markSynced = useCallback((module: SyncModuleKey) => {
    setStatusMap((prev) => ({ ...prev, [module]: 'synced' }));
  }, []);

  const markSyncing = useCallback((module: SyncModuleKey) => {
    setStatusMap((prev) => ({ ...prev, [module]: 'syncing' }));
  }, []);

  const markError = useCallback((module: SyncModuleKey) => {
    setStatusMap((prev) => ({ ...prev, [module]: 'error' }));
  }, []);

  const getStatus = useCallback(
    (module: SyncModuleKey) => statusMap[module] || 'synced',
    [statusMap]
  );

  const isDirty = useCallback(
    (module: SyncModuleKey) => statusMap[module] === 'dirty',
    [statusMap]
  );

  const dirtyCount = Object.values(statusMap).filter((s) => s === 'dirty').length;

  /**
   * 同步单个模块（带 toast 进度和错误处理）
   */
  const syncModule = useCallback(
    async (
      module: SyncModuleKey,
      label: string,
      syncFn: (config: GithubConfig) => Promise<void>
    ): Promise<boolean> => {
      const config = getGithubApiConfig();
      if (!config) {
        toast.warning('GitHub sync not configured', {
          description: 'Go to GitHub Sync settings to set up your repository.',
        });
        return false;
      }

      markSyncing(module);
      const loadingId = toast.loading(`Syncing ${label} to GitHub...`);

      try {
        await syncFn(config);
        markSynced(module);
        toast.success(`${label} synced to GitHub!`, {
          id: loadingId,
          description:
            'GitHub Pages is deploying. Changes will be live in 1-5 minutes.',
        });
        return true;
      } catch (err) {
        markError(module);
        const msg = err instanceof Error ? err.message : 'Unknown error';
        const errStack = err instanceof Error ? err.stack || '' : '';
        toast.error(`Sync failed: ${msg}`, { id: loadingId });
        logger.error(
          `[SyncService] syncModule failed: module=${module}, label=${label}, error=${msg}`
        );
        if (errStack) {
          logger.error(`[SyncService] stack: ${errStack}`);
        }
        return false;
      }
    },
    [getGithubApiConfig, markSyncing, markSynced, markError]
  );

  /**
   * 同步 JSON 文件到 GitHub
   */
  const syncJsonFile = useCallback(
    async (
      config: GithubConfig,
      path: string,
      data: unknown,
      commitMsg: string
    ) => {
      const jsonStr = JSON.stringify(data, null, 2);
      await createOrUpdateFile(config, path, jsonStr, commitMsg, false);
    },
    []
  );

  /**
   * 同步 base64 图片到 GitHub，返回仓库路径
   */
  const syncBase64Image = useCallback(
    async (
      config: GithubConfig,
      dataUrl: string,
      targetPath: string,
      commitMsg: string
    ): Promise<string> => {
      const { base64 } = extractBase64FromDataUrl(dataUrl);
      await createOrUpdateFile(config, targetPath, base64, commitMsg, true);
      return targetPath;
    },
    []
  );

  /**
   * 递归扫描数据中的 base64 图片，同步到 GitHub 后替换路径
   * 支持对象数组中的图片字段
   *
   * 注意：图片上传使用串行方式，避免并发触发 GitHub secondary rate limit
   * image 字段与 gallery[0] 去重，避免同一张图上传两次
   */
  const syncImagesInData = useCallback(
    async <T,>(
      config: GithubConfig,
      data: T,
      moduleDir: string,
      imageFields: (keyof T)[]
    ): Promise<T> => {
      // 提取纯 base64 内容用于去重判断（去掉 data:image/...;base64, 前缀）
      const extractPureBase64 = (dataUrl: string): string => {
        const idx = dataUrl.indexOf(',');
        return idx >= 0 ? dataUrl.slice(idx + 1) : dataUrl;
      };
      // 缓存：已上传的 base64 → 目标路径，避免同一张图重复上传
      const uploadedCache = new Map<string, string>();

      const uploadOne = async (dataUrl: string): Promise<string> => {
        const pure = extractPureBase64(dataUrl);
        const cached = uploadedCache.get(pure);
        if (cached) {
          logger.info(`[Sync] image dedup hit, reuse path: ${cached}`);
          return cached;
        }
        const targetPath = generateImageFilename('image.jpg', moduleDir);
        await syncBase64Image(config, dataUrl, targetPath, `Upload ${targetPath}`);
        uploadedCache.set(pure, targetPath);
        return targetPath;
      };

      const processImageField = (obj: Record<string, unknown>, field: string) => {
        const val = obj[field];
        if (typeof val === 'string' && isLocalBase64Image(val)) {
          return uploadOne(val).then((targetPath) => {
            obj[field] = `/${targetPath}`;
          });
        }
        return Promise.resolve();
      };

      const processGalleryField = async (obj: Record<string, unknown>, field: string) => {
        const val = obj[field];
        if (field === 'gallery' && Array.isArray(val)) {
          // 串行上传 gallery 图片，避免并发触发 GitHub 速率限制
          const newGallery: string[] = [];
          for (const img of val) {
            if (typeof img === 'string' && isLocalBase64Image(img)) {
              const targetPath = await uploadOne(img);
              newGallery.push(`/${targetPath}`);
            } else if (typeof img === 'string') {
              newGallery.push(img);
            }
          }
          obj[field] = newGallery;
        }
      };

      if (!Array.isArray(data)) {
        // 单个对象的情况
        const obj = { ...(data as Record<string, unknown>) };
        for (const field of imageFields as string[]) {
          await processImageField(obj, field);
          await processGalleryField(obj, field);
        }
        // image 与 gallery[0] 去重同步：如果 image 是 base64 且 gallery[0] 也是同一张 base64，
        // 上传后把 image 同步设为 gallery[0] 的路径
        const imgVal = obj['image'];
        const galVal = obj['gallery'];
        if (
          typeof imgVal === 'string' &&
          imgVal.startsWith('/') &&
          Array.isArray(galVal) &&
          galVal[0] &&
          typeof galVal[0] === 'string' &&
          galVal[0].startsWith('/') &&
          imgVal !== galVal[0] &&
          isLocalBase64Image((data as Record<string, unknown>)['image'] as string) &&
          isLocalBase64Image(((data as Record<string, unknown>)['gallery'] as string[])[0] || '')
        ) {
          // 两者都是 base64 上传后的结果，若内容相同则缓存已命中；这里兜底把 image 设为 gallery[0]
          const origImg = (data as Record<string, unknown>)['image'] as string;
          const origGal0 = ((data as Record<string, unknown>)['gallery'] as string[])[0] || '';
          if (extractPureBase64(origImg) === extractPureBase64(origGal0)) {
            obj['image'] = galVal[0];
          }
        }
        return obj as T;
      }

      // 数组的情况：逐项串行处理，避免整个数组 Promise.all 大并发
      const result: unknown[] = [];
      for (const item of data as unknown[]) {
        if (!item || typeof item !== 'object') {
          result.push(item);
          continue;
        }
        const obj = { ...(item as Record<string, unknown>) };
        for (const field of imageFields as string[]) {
          await processImageField(obj, field);
          await processGalleryField(obj, field);
        }
        // image 与 gallery[0] 去重同步
        const imgVal = obj['image'];
        const galVal = obj['gallery'];
        const origItem = item as Record<string, unknown>;
        const origImg = typeof origItem['image'] === 'string' ? origItem['image'] : '';
        const origGalArr = Array.isArray(origItem['gallery']) ? (origItem['gallery'] as string[]) : [];
        const origGal0 = origGalArr[0] || '';
        if (
          typeof imgVal === 'string' &&
          imgVal.startsWith('/') &&
          Array.isArray(galVal) &&
          galVal[0] &&
          typeof galVal[0] === 'string' &&
          galVal[0].startsWith('/') &&
          isLocalBase64Image(origImg) &&
          isLocalBase64Image(origGal0) &&
          extractPureBase64(origImg) === extractPureBase64(origGal0)
        ) {
          obj['image'] = galVal[0];
        }
        result.push(obj);
      }
      return result as unknown as T;
    },
    [syncBase64Image]
  );

  /**
   * 从 GitHub 远程获取 JSON 数据（前台用，带回退）
   */
  const fetchRemoteJson = useCallback(
    async <T,>(
      config: GithubConfig | null,
      path: string,
      fallback: T
    ): Promise<{ data: T; source: 'remote' | 'fallback' }> => {
      if (!config) {
        return { data: fallback, source: 'fallback' };
      }
      try {
        const file = await getFileContent(config, path);
        if (!file || !file.content) {
          return { data: fallback, source: 'fallback' };
        }
        const decoded = decodeBase64Content(file.content);
        const parsed = JSON.parse(decoded) as T;
        return { data: parsed, source: 'remote' };
      } catch (err) {
        logger.warn(`Failed to fetch remote data ${path}:`, String(err));
        return { data: fallback, source: 'fallback' };
      }
    },
    []
  );

  // 🔴 用 useMemo 缓存 value，避免每次渲染新建对象导致所有消费者级联重渲染
  const value: SyncServiceContextType = useMemo(
    () => ({
      statusMap,
      markDirty,
      markSynced,
      markSyncing,
      markError,
      getStatus,
      isDirty,
      dirtyCount,
      getGithubApiConfig,
      syncModule,
      syncJsonFile,
      syncBase64Image,
      syncImagesInData,
      fetchRemoteJson,
    }),
    [
      statusMap,
      markDirty,
      markSynced,
      markSyncing,
      markError,
      getStatus,
      isDirty,
      dirtyCount,
      getGithubApiConfig,
      syncModule,
      syncJsonFile,
      syncBase64Image,
      syncImagesInData,
      fetchRemoteJson,
    ]
  );

  return (
    <SyncServiceContext.Provider value={value}>
      {children}
    </SyncServiceContext.Provider>
  );
}

export function useSyncService() {
  const ctx = useContext(SyncServiceContext);
  if (!ctx) {
    throw new Error('useSyncService must be used within SyncServiceProvider');
  }
  return ctx;
}
