function migrateFromLegacy(raw: unknown): ITestimonial[] | null {
  let arr: unknown[] = [];
  if (Array.isArray(raw)) arr = raw;
  else if (raw && typeof raw === 'object' && Array.isArray((raw as { data?: unknown[] }).data))
    arr = (raw as { data: unknown[] }).data;
  if (!arr.length) return null;
  try {
    return arr.map((item, idx) => {
      const t = item as Record<string, unknown>;
      return {
        id: String(t.id ?? `test_${idx}`),
        customerName: migrateI18n(t.customerName as string | I18nText | undefined),
        company: String(t.company ?? ''),
        avatar: String(t.avatar ?? LOCAL_AVATARS[0]),
        content: migrateI18n(t.content as string | I18nText),
        rating: Number(t.rating ?? 5),
        createdAt: Number(t.createdAt ?? Date.now()),
      };
    });
  } catch {
    return null;
  }
}

function readLocalTestimonials(): ITestimonial[] {
  try {
    const saved = scopedStorage.getItem(STORAGE_KEY);
    if (saved) {
      const parsed = JSON.parse(saved);
      if (
        parsed.__version === STORAGE_VERSION &&
        Array.isArray(parsed.data) &&
        parsed.data.length > 0
      ) {
        return parsed.data
          .map((t: Record<string, unknown>) => ({
            ...t,
            customerName: migrateI18n(t.customerName as string | I18nText | undefined),
            content: migrateI18n(t.content as string | I18nText | undefined),
          }))
          .sort((a: ITestimonial, b: ITestimonial) => b.createdAt - a.createdAt);
      }
      const migrated = migrateFromLegacy(parsed);
      if (migrated && migrated.length > 0) {
        return migrated.sort((a, b) => b.createdAt - a.createdAt);
      }
    }
  } catch {
    // ignore
  }
  return DEFAULT_TESTIMONIALS;
}

export function useTestimonials(options?: { preferRemote?: boolean }) {
  const preferRemote = options?.preferRemote ?? false;
  const remoteData = useRemoteDataStore<ITestimonial[]>('testimonials');
  // 🔴 同步初始化：直接读 localStorage 作为初始值，避免首帧默认值 → 第二帧同值不同引用的重渲染
  const [testimonials, setTestimonials] = useState<ITestimonial[]>(() => {
    try {
      const saved = scopedStorage.getItem(STORAGE_KEY);
      if (saved) {
        const parsed = JSON.parse(saved);
        if (
          parsed.__version === STORAGE_VERSION &&
          Array.isArray(parsed.data) &&
          parsed.data.length > 0
        ) {
          const mapped = parsed.data.map((t: Record<string, unknown>) => ({
            ...t,
            customerName: migrateI18n(t.customerName as string | I18nText | undefined),
            content: migrateI18n(t.content as string | I18nText | undefined),
          }));
          return mapped.sort((a: ITestimonial, b: ITestimonial) => b.createdAt - a.createdAt);
        }
        const migrated = migrateFromLegacy(parsed);
        if (migrated && migrated.length > 0) {
          return migrated.sort((a, b) => b.createdAt - a.createdAt);
        }
      }
    } catch {
      // ignore
    }
    // 没有本地数据或读取失败，用默认值并持久化
    setTimeout(() => persist(DEFAULT_TESTIMONIALS), 0);
    return DEFAULT_TESTIMONIALS;
  });

  // loading 始终为 false：本地数据同步初始化完成
  const loading = false;

  const displayTestimonials = useMemo(() => {
    if (preferRemote && remoteData && Array.isArray(remoteData) && remoteData.length > 0) {
      return remoteData
        .map((t) => ({
          ...t,
          customerName: migrateI18n(t.customerName),
          content: migrateI18n(t.content),
        }))
        .sort((a: ITestimonial, b: ITestimonial) => b.createdAt - a.createdAt);
    }
    return testimonials;
  }, [preferRemote, remoteData, testimonials]);

  const persist = (items: ITestimonial[]) => {
    try {
      scopedStorage.setItem(
        STORAGE_KEY,
        JSON.stringify({ __version: STORAGE_VERSION, data: items })
      );
    } catch {
      // ignore
    }
  };

  const saveTestimonials = useCallback((items: ITestimonial[]) => {
    setTestimonials(items);
    persist(items);
  }, []);

  const addTestimonial = useCallback(
    (t: Omit<ITestimonial, 'id'>) => {
      const newItem: ITestimonial = {
        ...t,
        id: `test_${Date.now()}`,
      };
      saveTestimonials([newItem, ...testimonials]);
      return newItem;
    },
    [testimonials, saveTestimonials]
  );

  const updateTestimonial = useCallback(
    (id: string, updates: Partial<ITestimonial>) => {
      const updated = testimonials.map((t) => (t.id === id ? { ...t, ...updates } : t));
      saveTestimonials(updated);
    },
    [testimonials, saveTestimonials]
  );

  const deleteTestimonial = useCallback(
    (id: string) => {
      saveTestimonials(testimonials.filter((t) => t.id !== id));
    },
    [testimonials, saveTestimonials]
  );

  return {
    testimonials: displayTestimonials,
    loading,
    addTestimonial,
    updateTestimonial,
    deleteTestimonial,
    saveTestimonials,
    isUsingRemoteData: preferRemote && !!remoteData,
  };
}
