import { useState, useEffect, useMemo, type FormEvent } from 'react';
import { useSeo } from '@/hooks/useSeo';
import { Link, useNavigate } from 'react-router-dom';
import { motion, AnimatePresence } from 'framer-motion';
import {
  Factory,
  ShieldCheck,
  Settings,
  ChevronLeft,
  ChevronRight,
  CheckCircle2,
  Clock,
  Globe,
  Headphones,
  Package,
  Star,
  Send,
  ArrowRight,
} from 'lucide-react';
import { Button } from '@/components/ui/button';
import {
  Carousel,
  CarouselContent,
  CarouselItem,
  CarouselNext,
  CarouselPrevious,
} from '@/components/ui/carousel';
import { Input } from '@/components/ui/input';
import { Textarea } from '@/components/ui/textarea';
import { Badge } from '@/components/ui/badge';
import { Card, CardContent } from '@/components/ui/card';
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@/components/ui/select';
import { useI18n } from '@/i18n/I18nContext';
import { useProducts, type IProduct } from '@/hooks/useProducts';
import { useCategories } from '@/hooks/useCategories';
import { useAdvantages } from '@/hooks/useAdvantages';
import { useTestimonials } from '@/hooks/useTestimonials';
import { useSiteImages } from '@/hooks/useSiteImages';
import { useFeatures } from '@/hooks/useFeatures';
import { useHeroSlides } from '@/hooks/useHeroSlides';
import { useInquiries } from '@/hooks/useInquiries';
import { useEmailSettings } from '@/hooks/useEmailSettings';
import { useAboutContent } from '@/hooks/useAboutContent';
import { Image } from '@/components/ui/image';
import { getI18nValue, createI18nText, type I18nText } from '@/lib/i18n-text';
import { toast } from 'sonner';
import { logger } from '@lark-apaas/client-toolkit-lite';
import * as Icons from 'lucide-react';
import { imgPath } from '@/utils/img-path';

const HERO_SLIDES = [
  {
    image: imgPath('/images/hero-slide-1.jpg'),
    titleKey: 'hero.headline',
    subKey: 'hero.subheadline',
    ctaKey: 'hero.cta',
    ctaLink: '/contact',
  },
  {
    image: imgPath('/images/hero-slide-2.jpg'),
    titleKey: 'hero.slide2Title',
    subKey: 'hero.slide2Sub',
    ctaKey: 'hero.slide2Cta',
    ctaLink: '/products',
  },
  {
    image: imgPath('/images/hero-slide-3.jpg'),
    titleKey: 'hero.slide3Title',
    subKey: 'hero.slide3Sub',
    ctaKey: 'hero.slide3Cta',
    ctaLink: '/about',
  },
];


export default function HomePage() {
  const { t, language } = useI18n();
  const navigate = useNavigate();
  const { products, productSettings } = useProducts({ preferRemote: true });
  // 从产品中提取所有类目（去重），询盘表单只选类目不选具体产品
  const categories = Array.from(new Set(products.map((p) => p.category))).sort();
  const { enabledCategories } = useCategories({ preferRemote: true });
  const { advantages, loading: advLoading } = useAdvantages({ preferRemote: true });
  const { testimonials, loading: testLoading } = useTestimonials({ preferRemote: true });
  const { features, loading: featuresLoading, sectionImage } = useFeatures({ preferRemote: true });
  const { getImage } = useSiteImages();
  const { content: aboutContent, loading: aboutLoading } = useAboutContent({ preferRemote: true });

  useSeo({
    title: t('seo.homeTitle'),
    description: t('seo.homeDescription'),
    keywords: t('seo.homeKeywords'),
    type: 'website',
    pageKey: 'home',
  });

  const heroImages = useMemo(
    () => [getImage('hero_slide_1'), getImage('hero_slide_2'), getImage('hero_slide_3')],
    [getImage]
  );
  const { slides: heroSlides, loading: heroLoading } = useHeroSlides({ preferRemote: true });
  const factoryImage = sectionImage || getImage('home_factory');

  const HERO_SLIDES_WITH_IMG = useMemo(() => {
    if (heroSlides.length > 0) {
      return heroSlides.map((s) => ({
        id: s.id,
        badge: getI18nValue(s.badge, language),
        title: getI18nValue(s.title, language),
        subtitle: getI18nValue(s.subtitle, language),
        ctaText: getI18nValue(s.ctaText, language),
        ctaLink: s.ctaLink,
        secondCtaText: getI18nValue(s.secondCtaText, language),
        secondCtaLink: s.secondCtaLink,
        image: s.image || getImage(s.imageKey),
      }));
    }
    // Fallback to i18n static data when hook not yet loaded
    return HERO_SLIDES.map((s, i) => ({
      ...s,
      image: heroImages[i] || s.image,
      badge: t('hero.badge'),
      title: t(s.titleKey),
      subtitle: t(s.subKey),
      ctaText: t(s.ctaKey),
      secondCtaText: t('nav.products'),
      secondCtaLink: '/products',
    }));
  }, [heroSlides, heroImages, getImage, t, language]);

  // Hero carousel - auto play starts only after image fully loads
  const [currentSlide, setCurrentSlide] = useState(0);
  const [slideLoaded, setSlideLoaded] = useState(false);
  const [failedSlides, setFailedSlides] = useState<Set<string>>(new Set());
  const [isPaused, setIsPaused] = useState(false);
  const slideCount = HERO_SLIDES_WITH_IMG.length;

  // Preload next slide image for smoother transition
  useEffect(() => {
    if (slideCount === 0) return;
    const nextIdx = (currentSlide + 1) % slideCount;
    const nextSrc = HERO_SLIDES_WITH_IMG[nextIdx]?.image;
    if (nextSrc) {
      const preloader = document.createElement('img');
      preloader.src = nextSrc;
    }
  }, [currentSlide, slideCount, HERO_SLIDES_WITH_IMG]);

  // Auto-play timer: starts after current image loads + not paused
  useEffect(() => {
    if (slideCount === 0) return;
    if (!slideLoaded || isPaused) return;
    const timer = setTimeout(() => {
      setCurrentSlide((prev) => (prev + 1) % slideCount);
    }, 5000);
    return () => clearTimeout(timer);
  }, [slideLoaded, isPaused, currentSlide, slideCount]);

  // Reset loaded state when slide changes
  useEffect(() => {
    setSlideLoaded(false);
  }, [currentSlide]);

  const handleImageLoad = () => {
    setSlideLoaded(true);
  };

  const handleImageError = (src: string) => {
    logger.warn('Hero image failed to load: ' + src);
    setFailedSlides((prev) => new Set(prev).add(src));
    // 错误图片不阻塞轮播继续播放
    setSlideLoaded(true);
    // 如果所有 slide 都失败了，至少显示第 1 张（用第 2 张兜底）
    if (failedSlides.size >= slideCount - 1 && slideCount > 1) {
      // 已记录所有失败，交给渲染层用兜底图
    }
  };

  // Quote form
  const [formData, setFormData] = useState({
    name: '',
    company: '',
    email: '',
    country: '',
    category: 'all',
    message: '',
  });
  const [submitting, setSubmitting] = useState(false);

  const { addInquiry, buildMailto, sendInquiryEmail } = useInquiries();
  const { settings: emailSettings, isConfigured: emailConfigured } = useEmailSettings();

  const handleSubmit = async (e: FormEvent) => {
    e.preventDefault();
    if (!formData.name || !formData.email) {
      toast.error('Please fill in required fields');
      return;
    }
    setSubmitting(true);
    await new Promise((r) => setTimeout(r, 1000));
    const categoryName = formData.category === 'all' ? t('products.allCategories') : formData.category;
    const inquiryData = {
      name: formData.name,
      company: formData.company,
      email: formData.email,
      country: formData.country,
      product: '',
      productName: '',
      category: formData.category,
      categoryName,
      message: formData.message,
      source: 'home' as const,
      createdAt: Date.now(),
    };
    const newInquiry = addInquiry(inquiryData);
    // 自动发送邮件（异步，不阻塞 UI）
    if (emailConfigured) {
      sendInquiryEmail(newInquiry, emailSettings.endpoint, emailSettings.recipientEmail);
    }
    toast.success(t('contact.successMsg'), {
      action: {
        label: t('contact.sendEmailNotify'),
        onClick: () => {
          const link = document.createElement('a');
          link.href = buildMailto(inquiryData);
          link.rel = 'noopener noreferrer';
          document.body.appendChild(link);
          link.click();
          document.body.removeChild(link);
        },
      },
    });
    setFormData({ name: '', company: '', email: '', country: '', category: 'all', message: '' });
    setSubmitting(false);
  };

  const featuredProducts = useMemo(() => {
    const featured = products.filter((p) => p.featuredOnHomepage);
    // 如果没有任何推荐产品，回退到前 N 个保证展示不空
    const base = featured.length > 0 ? featured : products.slice(0, 4);
    return base.slice(0, productSettings.carouselMaxCount || 8);
  }, [products, productSettings.carouselMaxCount]);

  const displayTestimonials = useMemo(() => {
    if (testimonials.length > 0) return testimonials;
    // Fallback
    return [
      { id: '1', customerName: createI18nText('James Wilson'), company: 'BrightElectronics', avatar: imgPath('/images/avatars/avatar-1.jpg'), content: createI18nText('Excellent quality products and professional service.'), rating: 5, createdAt: Date.now() },
    ];
  }, [testimonials]);

  return (
    <div className="min-h-screen bg-background">
      {/* Hero Carousel */}
        <section
          className="relative w-full h-[70vh] md:h-[85vh] max-h-[900px] overflow-hidden"
          onMouseEnter={() => setIsPaused(true)}
          onMouseLeave={() => setIsPaused(false)}
        >
        <AnimatePresence mode="wait">
          <motion.div
            key={currentSlide}
            initial={{ opacity: 0, scale: 1.05 }}
            animate={{ opacity: 1, scale: 1 }}
            exit={{ opacity: 0 }}
            transition={{ duration: 1, ease: 'easeOut' }}
            className="absolute inset-0"
          >
            <Image
              src={HERO_SLIDES_WITH_IMG[currentSlide].image}
              alt={HERO_SLIDES_WITH_IMG[currentSlide].title}
              width={1920}
              height={1080}
              loading="eager"
              fetchPriority="high"
              onLoad={handleImageLoad}
              onError={(e) => {
                const src = HERO_SLIDES_WITH_IMG[currentSlide]?.image || '';
                // 失败时尝试用第 1 张作为兜底（避免用户看到空白）
                const fallbackIdx = currentSlide === 0 ? 1 : 0;
                const fallbackSrc = HERO_SLIDES_WITH_IMG[fallbackIdx]?.image;
                if (fallbackSrc && e.currentTarget.src !== fallbackSrc) {
                  e.currentTarget.src = fallbackSrc;
                }
                handleImageError(src);
              }}
              className="absolute inset-0 w-full h-full object-cover"
            />
            <div className="absolute inset-0 bg-gradient-to-r from-black/85 via-black/60 to-black/30" />
            <div className="absolute inset-0 bg-gradient-to-t from-background via-transparent to-transparent" />
          </motion.div>
        </AnimatePresence>

        <div className="relative h-full max-w-7xl mx-auto px-4 md:px-6 flex items-center">
          <motion.div
            key={`text-${currentSlide}`}
            initial={{ opacity: 0, y: 30 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ duration: 0.7, delay: 0.2 }}
            className="max-w-2xl"
          >
            <h1 className="text-4xl md:text-6xl lg:text-7xl font-black text-foreground leading-[1.1] tracking-tight mb-5">
              {HERO_SLIDES_WITH_IMG[currentSlide]?.title || ''}
            </h1>
            <p className="text-lg md:text-xl text-muted-foreground mb-8 max-w-xl">
              {HERO_SLIDES_WITH_IMG[currentSlide]?.subtitle || ''}
            </p>
            <div className="flex flex-wrap gap-3">
              <Button
                size="lg"
                onClick={() => navigate(HERO_SLIDES_WITH_IMG[currentSlide]?.ctaLink || '/contact')}
                className="bg-primary hover:bg-primary/90 text-primary-foreground rounded-md px-8"
              >
                {HERO_SLIDES_WITH_IMG[currentSlide]?.ctaText || 'Get a Quote'}
                <ArrowRight className="size-4 ml-2" />
              </Button>
              <Button
                size="lg"
                variant="outline"
                onClick={() => navigate(HERO_SLIDES_WITH_IMG[currentSlide]?.secondCtaLink || '/products')}
                className="rounded-md px-8 border-border/60"
              >
                {HERO_SLIDES_WITH_IMG[currentSlide]?.secondCtaText || t('nav.products')}
              </Button>
            </div>
          </motion.div>
        </div>

        {/* Carousel controls */}
        <button
          onClick={() => setCurrentSlide((prev) => (prev - 1 + HERO_SLIDES_WITH_IMG.length) % HERO_SLIDES_WITH_IMG.length)}
          className="absolute left-4 md:left-8 top-1/2 -translate-y-1/2 z-20 w-10 h-10 md:w-12 md:h-12 rounded-full bg-black/50 backdrop-blur-sm border border-white/10 flex items-center justify-center text-white hover:bg-primary/80 transition-colors"
          aria-label="Previous slide"
        >
          <ChevronLeft className="size-5 md:size-6" />
        </button>
        <button
          onClick={() => setCurrentSlide((prev) => (prev + 1) % HERO_SLIDES_WITH_IMG.length)}
          className="absolute right-4 md:right-8 top-1/2 -translate-y-1/2 z-20 w-10 h-10 md:w-12 md:h-12 rounded-full bg-black/50 backdrop-blur-sm border border-white/10 flex items-center justify-center text-white hover:bg-primary/80 transition-colors"
          aria-label="Next slide"
        >
          <ChevronRight className="size-5 md:size-6" />
        </button>

        {/* Dots */}
        <div className="absolute bottom-6 left-1/2 -translate-x-1/2 flex gap-2 z-20">
          {HERO_SLIDES_WITH_IMG.map((_, idx) => (
            <button
              key={idx}
              onClick={() => setCurrentSlide(idx)}
              className={`h-1.5 rounded-full transition-all duration-300 ${
                idx === currentSlide ? 'w-8 bg-primary' : 'w-3 bg-white/30 hover:bg-white/50'
              }`}
              aria-label={`Slide ${idx + 1}`}
            />
          ))}
        </div>
      </section>

      {/* Stats Bar */}
      {aboutContent.showStats && aboutContent.showStatsOnHome && aboutContent.stats.length > 0 && (
        <section className="w-full py-10 md:py-14 bg-card/40 border-y border-border/40 -mt-1 relative z-10">
          <div className="max-w-7xl mx-auto px-4 md:px-6">
            <div
              className="grid gap-6"
              style={{
                gridTemplateColumns: `repeat(${Math.min(aboutContent.stats.length, 4)}, minmax(0, 1fr))`,
              }}
            >
              {aboutContent.stats.map((stat, idx) => (
                <motion.div
                  key={stat.id}
                  initial={{ opacity: 0, y: 20 }}
                  whileInView={{ opacity: 1, y: 0 }}
                  viewport={{ once: true }}
                  transition={{ duration: 0.5, delay: idx * 0.1 }}
                  className="text-center"
                >
                  <div className="text-4xl md:text-5xl font-black text-primary mb-2 tabular-nums tracking-tight">
                    {stat.value}
                  </div>
                  <div className="text-sm text-muted-foreground font-medium">
                    {getI18nValue(stat.label, language)}
                  </div>
                </motion.div>
              ))}
            </div>
          </div>
        </section>
      )}

      {/* Three Core Advantages */}
      {aboutContent.showCoreAdvantages && aboutContent.showCoreAdvantagesOnHome && advantages.length > 0 && (
        <section className="w-full py-10 md:py-14 bg-card/40 border-y border-border/40 -mt-1 relative z-10">
          <div className="max-w-7xl mx-auto px-4 md:px-6">
            <div
              className="grid gap-6"
              style={{
                gridTemplateColumns: `repeat(${Math.min(advantages.length, 4)}, minmax(0, 1fr))`,
              }}
            >
              {advantages.slice(0, 3).map((adv, idx) => {
                const Icon =
                  adv.icon === 'Factory'
                    ? Factory
                    : adv.icon === 'ShieldCheck'
                      ? ShieldCheck
                      : adv.icon === 'Settings'
                        ? Settings
                        : Star;
                return (
                  <motion.div
                    key={adv.id}
                    initial={{ opacity: 0, y: 20 }}
                    whileInView={{ opacity: 1, y: 0 }}
                    viewport={{ once: true }}
                    transition={{ duration: 0.5, delay: idx * 0.1 }}
                    className="text-center"
                  >
                     <div className="w-14 h-14 mx-auto mb-3 rounded-md bg-primary/10 border border-primary/20 flex items-center justify-center">
                       <Icon className="size-7 text-primary" strokeWidth={1.75} />
                     </div>
                    <h3 className="text-lg md:text-xl font-bold text-foreground mb-2 tracking-tight">
                      {getI18nValue(adv.title, language)}
                    </h3>
                    <p className="text-sm text-muted-foreground leading-relaxed max-w-xs mx-auto">
                      {getI18nValue(adv.description, language)}
                    </p>
                  </motion.div>
                );
              })}
            </div>
          </div>
        </section>
      )}

      {/* Product Categories / Featured Products */}
      {productSettings.showProductCarousel && featuredProducts.length > 0 && (
        <section className="w-full py-12 md:py-16 bg-muted/30">
          <div className="max-w-7xl mx-auto px-4 md:px-6">
          <div className="text-center mb-8 md:mb-12">
            <h2 className="text-3xl md:text-4xl font-bold text-foreground mb-3">
              {t('products.title')}
            </h2>
            <p className="text-muted-foreground max-w-2xl mx-auto">
              {t('products.subtitle')}
            </p>
          </div>

          {/* Carousel container with relative positioning for nav buttons */}
          <div className="relative">
            <Carousel
              opts={{
                align: 'start',
                loop: true,
              }}
              className="w-full"
            >
              <CarouselContent>
                {featuredProducts.map((product: IProduct) => (
                  <CarouselItem key={product.id} className="basis-full sm:basis-1/2 lg:basis-1/3 xl:basis-1/4">
                    <FeaturedProductCard product={product} />
                  </CarouselItem>
                ))}
              </CarouselContent>
              <div className="hidden md:block">
                <CarouselPrevious className="-left-4 top-1/2 -translate-y-1/2 bg-card border-border/60 hover:bg-primary hover:text-primary-foreground hover:border-primary z-10" />
                <CarouselNext className="-right-4 top-1/2 -translate-y-1/2 bg-card border-border/60 hover:bg-primary hover:text-primary-foreground hover:border-primary z-10" />
              </div>
            </Carousel>
          </div>

          <div className="text-center mt-8">
            <Button
              size="lg"
              variant="outline"
              onClick={() => navigate('/products')}
              className="rounded-md px-8"
            >
              {t('products.viewDetails')}
              <ArrowRight className="size-4 ml-2" />
            </Button>
          </div>
          </div>
        </section>
      )}

      {/* Why Choose Us */}
      {aboutContent.showWhyChooseUs && features.length > 0 && (
        <section className="w-full py-12 md:py-16">
        <div className="max-w-7xl mx-auto px-4 md:px-6">
          <div className="grid grid-cols-1 lg:grid-cols-2 gap-10 lg:gap-12 items-center">
            <div>
              <h2 className="text-3xl md:text-4xl font-bold text-foreground mb-3">
                {t('home.whyChooseTitle')}
              </h2>
              <p className="text-muted-foreground mb-6">{t('home.whyChooseSubtitle')}</p>

              <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                {features.map((feat) => {
                  const IconComp = (Icons as unknown as Record<string, React.ComponentType<{ className?: string; strokeWidth?: number }>>)[feat.icon] || Icons.Circle;
                  return (
                    <div key={feat.id} className="flex items-start gap-3 p-4 rounded-lg border border-border/40 hover:border-primary/20 transition-colors">
                      <div className="w-10 h-10 shrink-0 rounded-md bg-primary/10 flex items-center justify-center">
                        <IconComp className="size-5 text-primary" strokeWidth={1.8} />
                      </div>
                      <div>
                        <h4 className="text-sm font-semibold text-foreground mb-0.5">{getI18nValue(feat.title, language)}</h4>
                        <p className="text-xs text-muted-foreground">{getI18nValue(feat.description, language)}</p>
                      </div>
                    </div>
                  );
                })}
              </div>
            </div>

            <div className="relative">
              <div className="absolute -inset-4 bg-gradient-to-br from-primary/20 to-transparent rounded-3xl blur-2xl" />
              <div className="relative rounded-2xl overflow-hidden border border-border/40 h-[500px]">
                <Image
                  src={factoryImage}
                  alt="Factory"
                  className="absolute inset-0 w-full h-full object-cover"
                />
              </div>
              <div className="absolute -bottom-6 -left-6 w-40 h-40 rounded-2xl bg-card border border-border/60 p-5 shadow-xl">
                <div className="text-4xl font-black text-primary">24+</div>
                <div className="text-xs text-muted-foreground mt-1">Years Manufacturing Experience</div>
              </div>
            </div>
          </div>
        </div>
       </section>
      )}

      {/* Testimonials */}
      <section className="w-full py-12 md:py-16 bg-muted/30">
        <div className="max-w-7xl mx-auto px-4 md:px-6">
          <div className="text-center mb-8 md:mb-12">
            <h2 className="text-3xl md:text-4xl font-bold text-foreground mb-3">
              {t('home.testimonialsTitle')}
            </h2>
            <p className="text-muted-foreground max-w-2xl mx-auto">
              {t('home.testimonialsSubtitle')}
            </p>
          </div>

          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-5">
            {displayTestimonials.slice(0, 4).map((tItem, idx) => (
              <motion.div
                key={tItem.id}
                initial={{ opacity: 0, y: 24 }}
                whileInView={{ opacity: 1, y: 0 }}
                viewport={{ once: true }}
                transition={{ duration: 0.5, delay: idx * 0.1 }}
              >
                <Card className="h-full border-border/40 bg-card/80">
                  <CardContent className="p-5">
                    <div className="flex gap-0.5 mb-3">
                      {Array.from({ length: tItem.rating }).map((_, i) => (
                        <Star key={i} className="size-4 fill-warning text-warning" strokeWidth={0} />
                      ))}
                    </div>
                    <p className="text-sm text-foreground/90 leading-relaxed mb-4 line-clamp-5">
                      &ldquo;{getI18nValue(tItem.content, language)}&rdquo;
                    </p>
                    <div className="flex items-center gap-3 pt-3 border-t border-border/40">
                      <div className="w-10 h-10 rounded-full bg-muted overflow-hidden shrink-0 relative">
                        <Image src={tItem.avatar} alt={getI18nValue(tItem.customerName, language)} className="absolute inset-0 w-full h-full object-cover" />
                      </div>
                      <div className="min-w-0">
                        <div className="text-sm font-semibold text-foreground truncate">
                          {getI18nValue(tItem.customerName, language)}
                        </div>
                        <div className="text-xs text-muted-foreground truncate">{tItem.company}</div>
                      </div>
                    </div>
                  </CardContent>
                </Card>
              </motion.div>
            ))}
          </div>
        </div>
      </section>

      {/* Quote Form Section */}
      <section className="w-full py-16 md:py-24">
        <div className="max-w-7xl mx-auto px-4 md:px-6">
          <div className="relative overflow-hidden rounded-2xl border border-border/40 bg-gradient-to-br from-card via-card to-muted/30">
            <div className="absolute top-0 right-0 w-96 h-96 bg-primary/10 rounded-full blur-3xl -translate-y-1/2 translate-x-1/2" />
            <div className="relative grid grid-cols-1 lg:grid-cols-2 gap-10 p-6 md:p-10 lg:p-14">
              <div>
                <h2 className="text-3xl md:text-4xl font-bold text-foreground mb-3">
                  {t('home.quoteTitle')}
                </h2>
                <p className="text-muted-foreground mb-6">{t('home.quoteSubtitle')}</p>

                <div className="space-y-4">
                  {[
                    { icon: Clock, text: '12-hour fast response' },
                    { icon: CheckCircle2, text: 'Competitive factory direct price' },
                    { icon: Package, text: 'Custom OEM / ODM support' },
                  ].map((item, i) => (
                    <div key={i} className="flex items-center gap-3">
                      <div className="w-8 h-8 shrink-0 rounded-full bg-primary/10 flex items-center justify-center">
                        <item.icon className="size-4 text-primary" strokeWidth={2} />
                      </div>
                      <span className="text-sm text-foreground/90">{item.text}</span>
                    </div>
                  ))}
                </div>
              </div>

              <form onSubmit={handleSubmit} className="space-y-4">
                <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                  <div>
                    <label className="text-xs font-medium text-foreground mb-1.5 block">
                      {t('contact.name')} *
                    </label>
                    <Input
                      value={formData.name}
                      onChange={(e) => setFormData({ ...formData, name: e.target.value })}
                      placeholder="Your Name"
                      className="bg-background/60"
                      required
                    />
                  </div>
                  <div>
                    <label className="text-xs font-medium text-foreground mb-1.5 block">
                      {t('contact.company')}
                    </label>
                    <Input
                      value={formData.company}
                      onChange={(e) => setFormData({ ...formData, company: e.target.value })}
                      placeholder="Your Company"
                      className="bg-background/60"
                    />
                  </div>
                </div>
                <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                  <div>
                    <label className="text-xs font-medium text-foreground mb-1.5 block">
                      {t('contact.email')} *
                    </label>
                    <Input
                      type="email"
                      value={formData.email}
                      onChange={(e) => setFormData({ ...formData, email: e.target.value })}
                      placeholder="you@example.com"
                      className="bg-background/60"
                      required
                    />
                  </div>
                  <div>
                    <label className="text-xs font-medium text-foreground mb-1.5 block">
                      {t('contact.country')}
                    </label>
                    <Input
                      value={formData.country}
                      onChange={(e) => setFormData({ ...formData, country: e.target.value })}
                      placeholder="Country"
                      className="bg-background/60"
                    />
                  </div>
                  <div>
                    <label className="text-xs font-medium text-foreground mb-1.5 block">
                      {t('contact.interestedProduct')}
                    </label>
                    <Select
                      value={formData.category}
                      onValueChange={(v) => setFormData({ ...formData, category: v })}
                    >
                      <SelectTrigger className="bg-background/60">
                        <SelectValue />
                      </SelectTrigger>
                      <SelectContent>
                        <SelectItem value="all">{t('products.allCategories')}</SelectItem>
                        {categories.map((cat) => (
                           <SelectItem key={cat} value={cat}>
                             {cat}
                           </SelectItem>
                        ))}
                      </SelectContent>
                    </Select>
                  </div>
                </div>
                <div>
                  <label className="text-xs font-medium text-foreground mb-1.5 block">
                    {t('contact.message')}
                  </label>
                  <Textarea
                    value={formData.message}
                    onChange={(e) => setFormData({ ...formData, message: e.target.value })}
                    placeholder="Tell us about your requirements..."
                    rows={4}
                    className="bg-background/60 resize-none"
                  />
                </div>
                <Button
                  type="submit"
                  size="lg"
                  className="w-full bg-primary hover:bg-primary/90 text-primary-foreground"
                  disabled={submitting}
                >
                  {submitting ? t('contact.submitting') : t('contact.submit')}
                  {!submitting && <Send className="size-4 ml-2" />}
                </Button>
              </form>
            </div>
          </div>
        </div>
      </section>
    </div>
  );
}

/* ========== Featured Product Card ========== */
interface FeaturedProductCardProps {
  product: IProduct;
}

function FeaturedProductCard({ product }: FeaturedProductCardProps) {
  const navigate = useNavigate();
  const { t, language } = useI18n();
  const [imgError, setImgError] = useState(false);
  const productName = getI18nValue(product.name, language);

  return (
    <div className="group h-full w-full flex flex-col min-w-0">
      <div
        className="overflow-hidden cursor-pointer flex-shrink-0 w-full"
        onClick={() => navigate(`/products/${product.id}`)}
      >
        <div className="relative w-full aspect-square overflow-hidden rounded-sm border border-border/50 bg-[hsl(0_0%_96%)]">
          {imgError || !product.image ? (
            <div className="absolute inset-0 flex items-center justify-center">
              <Package className="size-12 text-muted-foreground/30" />
            </div>
          ) : (
            <Image
              src={product.image}
              alt={productName}
              className="absolute inset-0 w-full h-full object-contain transition-transform duration-500 group-hover:scale-105"
              onError={() => setImgError(true)}
            />
          )}
        </div>
      </div>
    </div>
  );
}
