/* ========== 图片路径迁移 ========== */
const EXTERNAL_IMAGE_PATTERNS = [/unsplash\.com/i, /doubaocdn\.com/i, /picsum\.photos/i, /pexels\.com/i];

function migrateImageUrl(url: string, fallback: string): string {
  if (!url) return fallback;
  // 外部链接 → 替换为本地默认图
  if (EXTERNAL_IMAGE_PATTERNS.some((p) => p.test(url))) return fallback;
  // 裸 /images/ 路径 → 补全 basename
  if (url.startsWith('/images/')) return imgPath(url);
  return url;
}

const STORAGE_KEY = '__app_ledlight_about_content_v1';
const STORAGE_VERSION = 2;

/* ===== 图片压缩配置 ===== */
// 超过此大小的 base64 图片会被自动重新压缩（单位：字节）
const LARGE_IMAGE_THRESHOLD = 200 * 1024; // 200KB

// Hero 横幅图压缩参数
const HERO_COMPRESS_OPTS = { maxWidth: 1600, maxHeight: 900, quality: 0.7 };
// 工厂实景画廊图压缩参数
const GALLERY_COMPRESS_OPTS = { maxWidth: 1280, maxHeight: 960, quality: 0.7 };
// 认证证书图压缩参数
const CERT_COMPRESS_OPTS = { maxWidth: 400, maxHeight: 400, quality: 0.75 };
// OEM 配图压缩参数（与画廊同档）
const OEM_COMPRESS_OPTS = { maxWidth: 1280, maxHeight: 960, quality: 0.7 };

