import { useState, useEffect, useCallback } from 'react';
import { scopedStorage } from '@lark-apaas/client-toolkit-lite';

const SETTINGS_KEY = '__app_ledlight_email_settings';

export interface IEmailSettings {
  enabled: boolean;
  endpoint: string; // Formspree endpoint URL, e.g. https://formspree.io/f/xxxxxxx
  recipientEmail: string; // default: sherwin@tanjeon.com
}

const DEFAULT_SETTINGS: IEmailSettings = {
  enabled: false,
  endpoint: '',
  recipientEmail: 'sherwin@tanjeon.com',
};

function loadSettings(): IEmailSettings {
  try {
    const raw = scopedStorage.getItem(SETTINGS_KEY);
    if (raw) {
      const parsed = JSON.parse(raw);
      return { ...DEFAULT_SETTINGS, ...parsed };
    }
  } catch {
    // ignore
  }
  return { ...DEFAULT_SETTINGS };
}

function saveSettings(settings: IEmailSettings) {
  try {
    scopedStorage.setItem(SETTINGS_KEY, JSON.stringify(settings));
  } catch {
    // ignore
  }
}

export function useEmailSettings() {
  const [settings, setSettings] = useState<IEmailSettings>(DEFAULT_SETTINGS);
  const [loaded, setLoaded] = useState(false);

  useEffect(() => {
    setSettings(loadSettings());
    setLoaded(true);
  }, []);

  const updateSettings = useCallback((next: Partial<IEmailSettings>) => {
    setSettings((prev) => {
      const merged = { ...prev, ...next };
      saveSettings(merged);
      return merged;
    });
  }, []);

  const resetSettings = useCallback(() => {
    setSettings({ ...DEFAULT_SETTINGS });
    saveSettings({ ...DEFAULT_SETTINGS });
  }, []);

  return {
    settings,
    loaded,
    updateSettings,
    resetSettings,
    isConfigured: settings.enabled && settings.endpoint.trim().length > 0,
  };
}
