function readLocalNews(): INewsArticle[] {
  try {
    const raw = scopedStorage.getItem(STORAGE_KEY);
    if (raw) {
      const parsed = JSON.parse(raw);
      if (parsed && parsed.__version === STORAGE_VERSION && Array.isArray(parsed.data)) {
        return parsed.data;
      }
    }
  } catch {
    // ignore
  }
  return DEFAULT_NEWS;
}

export function useNews(options?: { preferRemote?: boolean }) {
  const preferRemote = options?.preferRemote ?? false;
  const remoteData = useRemoteDataStore<INewsArticle[]>('news');
  // 🔴 同步初始化：直接读 localStorage 作为初始值，避免首帧默认值 → 第二帧同值不同引用的重渲染
  const [articles, setArticles] = useState<INewsArticle[]>(() => {
    try {
      const raw = scopedStorage.getItem(STORAGE_KEY);
      if (raw) {
        const parsed = JSON.parse(raw);
        if (parsed && parsed.__version === STORAGE_VERSION && Array.isArray(parsed.data)) {
          return parsed.data;
        }
      }
    } catch {
      // ignore parse errors
    }
    // 没有本地数据或读取失败，用默认值并持久化
    setTimeout(() => persist(DEFAULT_NEWS), 0);
    return DEFAULT_NEWS;
  });

  // loading 始终为 false：本地数据同步初始化完成
  const loading = false;

  const displayArticles = useMemo(() => {
    if (preferRemote && remoteData && Array.isArray(remoteData) && remoteData.length > 0) {
      return [...remoteData].sort((a, b) => new Date(b.publishDate).getTime() - new Date(a.publishDate).getTime());
    }
    return articles;
  }, [preferRemote, remoteData, articles]);

  const persist = (items: INewsArticle[]) => {
    try {
      scopedStorage.setItem(
        STORAGE_KEY,
        JSON.stringify({ __version: STORAGE_VERSION, data: items })
      );
    } catch (err) {
      const msg = err instanceof Error ? err.message : String(err);
      logger.error('Failed to save news to storage:', msg);
      if (msg.includes('QuotaExceededError') || msg.includes('exceeded the quota')) {
        throw new Error(
          'Storage is full. The uploaded cover image is too large. '
          + 'Please use a smaller image or a URL instead of uploading.'
        );
      }
      throw new Error('Failed to save: ' + msg);
    }
  };

  const saveArticles = useCallback((items: INewsArticle[]) => {
    const sorted = [...items].sort((a, b) => {
      if (a.order !== b.order) return a.order - b.order;
      return new Date(b.publishDate).getTime() - new Date(a.publishDate).getTime();
    });
    try {
      persist(sorted);
    } catch (err) {
      const msg = err instanceof Error ? err.message : String(err);
      throw new Error(`Failed to save news to storage: ${msg}`);
    }
    setArticles(sorted);
  }, []);

  const addArticle = useCallback(
    (article: Omit<INewsArticle, 'id' | 'createdAt' | 'updatedAt'>): INewsArticle => {
      const now = Date.now();
      const newItem: INewsArticle = {
        ...article,
        id: `news_${now}_${Math.random().toString(36).slice(2, 8)}`,
        createdAt: now,
        updatedAt: now,
      };
      saveArticles([...articles, newItem]);
      return newItem;
    },
    [articles, saveArticles]
  );

  const updateArticle = useCallback(
    (id: string, updates: Partial<INewsArticle>) => {
      const updated = articles.map((a) =>
        a.id === id ? { ...a, ...updates, updatedAt: Date.now() } : a
      );
      saveArticles(updated);
    },
    [articles, saveArticles]
  );

  const deleteArticle = useCallback(
    (id: string) => {
      saveArticles(articles.filter((a) => a.id !== id));
    },
    [articles, saveArticles]
  );

  const getArticleBySlug = useCallback(
    (slug: string): INewsArticle | undefined => {
      return displayArticles.find((a) => a.slug === slug);
    },
    [displayArticles]
  );

  const getPublishedArticles = useCallback((): INewsArticle[] => {
    return displayArticles.filter((a) => a.published);
  }, [displayArticles]);

  const getRelatedArticles = useCallback(
    (currentId: string, limit = 3): INewsArticle[] => {
      return displayArticles
        .filter((a) => a.id !== currentId && a.published)
        .slice(0, limit);
    },
    [displayArticles]
  );

  return {
    articles: displayArticles,
    loading,
    addArticle,
    updateArticle,
    deleteArticle,
    getArticleBySlug,
    getPublishedArticles,
    getRelatedArticles,
    saveArticles,
    isUsingRemoteData: preferRemote && !!remoteData,
  };
}
