import { useState, useEffect, useCallback, useMemo } from 'react';
import { scopedStorage, logger } from '@lark-apaas/client-toolkit-lite';

const STORAGE_KEY = '__app_ledlight_footer_settings';

import { useRemoteDataStore } from '@/context/RemoteDataContext';

export interface FooterSettings {
  brandText: string;
  email: string;
  phone: string;
  address: string;
  copyright: string;
  certifications: string[];
  whatsappUrl: string;
  whatsappEnabled: boolean;
  facebookUrl: string;
  facebookEnabled: boolean;
  linkedinUrl: string;
  linkedinEnabled: boolean;
  twitterHandle: string;
  twitterEnabled: boolean;
  instagramUrl: string;
  instagramEnabled: boolean;
  wechatUrl: string;
  wechatEnabled: boolean;
  wechatQrImage: string;
  headerLogo: string;
  footerLogo: string;
  updatedAt: number;
}

const DEFAULT_SETTINGS: FooterSettings = {
  brandText:
    'Professional LED sensor light manufacturer from Jiujiang, China. Your trusted partner for security lighting solutions.',
  email: 'sherwin@tanjeon.com',
  phone: '+86 755 8888 6666',
  address: 'Jiujiang, Jiangxi, China',
  copyright: 'Jiujiang Ouwei Industrial Co.LTD',
  certifications: ['CE', 'RoHS', 'ISO9001', 'FCC'],
  whatsappUrl: 'https://wa.me/8613800138000?text=Hello%2C%20I%20am%20interested%20in%20your%20LED%20products',
  whatsappEnabled: true,
  facebookUrl: 'https://www.facebook.com/owelllighting',
  facebookEnabled: true,
  linkedinUrl: 'https://www.linkedin.com/company/owell-industrial',
  linkedinEnabled: true,
  twitterHandle: '@owell_lighting',
  twitterEnabled: true,
  instagramUrl: 'https://www.instagram.com/owell.industrial',
  instagramEnabled: true,
  wechatUrl: 'https://mp.weixin.qq.com/',
  wechatEnabled: true,
  wechatQrImage: '',
  headerLogo: '',
  footerLogo: '',
  updatedAt: Date.now(),
};

function deepMergeWithDefaults(saved: Partial<FooterSettings>): FooterSettings {
  const merged: FooterSettings = { ...DEFAULT_SETTINGS, ...saved };
  // Ensure arrays are arrays
  if (!Array.isArray(merged.certifications)) merged.certifications = DEFAULT_SETTINGS.certifications;
  return merged;
}

function readLocalFooterSettings(): FooterSettings {
  try {
    const saved = scopedStorage.getItem(STORAGE_KEY);
    if (saved) {
      const parsed = JSON.parse(saved) as Partial<FooterSettings>;
      return deepMergeWithDefaults(parsed);
    }
  } catch {
    // ignore
  }
  return DEFAULT_SETTINGS;
}

export function useFooterSettings(options?: { preferRemote?: boolean }) {
  const preferRemote = options?.preferRemote ?? false;
  const remoteData = useRemoteDataStore<Partial<FooterSettings>>('footer');
  // 🔴 同步初始化：直接读 localStorage 作为初始值，避免首帧默认值 → 第二帧同值不同引用的重渲染
  const [settings, setSettings] = useState<FooterSettings>(() => {
    try {
      const saved = scopedStorage.getItem(STORAGE_KEY);
      if (saved) {
        const parsed = JSON.parse(saved) as Partial<FooterSettings>;
        return deepMergeWithDefaults(parsed);
      }
    } catch (err) {
      logger.error('useFooterSettings init failed:', String(err));
    }
    return DEFAULT_SETTINGS;
  });

  // loading 始终为 false：本地数据同步初始化完成
  const loading = false;

  const displaySettings = useMemo((): FooterSettings => {
    if (preferRemote && remoteData && typeof remoteData === 'object') {
      return deepMergeWithDefaults(remoteData);
    }
    return settings;
  }, [preferRemote, remoteData, settings]);

  // 监听 storage 事件，跨组件实时同步（同页面不同组件间通过 CustomEvent 同步）
  useEffect(() => {
    const handleStorageChange = (e: StorageEvent) => {
      if (e.key !== STORAGE_KEY || !e.newValue) return;
      try {
        const parsed = JSON.parse(e.newValue) as Partial<FooterSettings>;
        setSettings(deepMergeWithDefaults(parsed));
      } catch {
        // ignore
      }
    };

    const handleCustomChange = (e: Event) => {
      const detail = (e as CustomEvent<FooterSettings>).detail;
      if (detail) setSettings(detail);
    };

    window.addEventListener('storage', handleStorageChange);
    window.addEventListener('footer-settings-change', handleCustomChange);
    return () => {
      window.removeEventListener('storage', handleStorageChange);
      window.removeEventListener('footer-settings-change', handleCustomChange);
    };
  }, []);

  const updateSettings = useCallback((data: Partial<FooterSettings>): boolean => {
    try {
      const next: FooterSettings = {
        ...settings,
        ...data,
        updatedAt: Date.now(),
      };
      setSettings(next);
      scopedStorage.setItem(STORAGE_KEY, JSON.stringify(next));
      window.dispatchEvent(new CustomEvent('footer-settings-change', { detail: next }));
      return true;
    } catch (err) {
      logger.error('useFooterSettings save failed:', String(err));
      return false;
    }
  }, [settings]);

  const resetToDefaults = useCallback((): boolean => {
    try {
      const def = { ...DEFAULT_SETTINGS, updatedAt: Date.now() };
      setSettings(def);
      scopedStorage.setItem(STORAGE_KEY, JSON.stringify(def));
      window.dispatchEvent(new CustomEvent('footer-settings-change', { detail: def }));
      return true;
    } catch (err) {
      logger.error('useFooterSettings reset failed:', String(err));
      return false;
    }
  }, []);

  return { settings: displaySettings, loading, updateSettings, resetToDefaults, isUsingRemoteData: preferRemote && !!remoteData };
}
