import { useState, useEffect, useMemo } from 'react';
import { useSeo } from '@/hooks/useSeo';
import { motion } from 'framer-motion';
import {
  FileText,
  Eye,
  Settings,
  Share2,
  Lock,
  ShieldCheck,
  Cookie,
  Mail,
  HelpCircle,
  Tag,
  Sparkles,
  Globe,
  Star,
  CheckCircle2,
  AlertTriangle,
  Award,
  Zap,
  Lightbulb,
  Package,
} from 'lucide-react';
import { useI18n } from '@/i18n/I18nContext';
import { getI18nValue, type I18nText } from '@/lib/i18n-text';
import { usePrivacyPolicy } from '@/hooks/usePrivacyPolicy';
import PageBreadcrumb from '@/components/PageBreadcrumb';

const ICON_MAP: Record<string, React.ComponentType<{ className?: string }>> = {
  FileText,
  Eye,
  Settings,
  Share2,
  Lock,
  ShieldCheck,
  Cookie,
  Mail,
  HelpCircle,
  Tag,
  Sparkles,
  Globe,
  Star,
  CheckCircle2,
  AlertTriangle,
  Award,
  Zap,
  Lightbulb,
  Package,
};

function getIcon(name: string): React.ComponentType<{ className?: string }> {
  return ICON_MAP[name] ?? FileText;
}

export default function PrivacyPolicyPage() {
  const { t, language } = useI18n();
  const { data, loading } = usePrivacyPolicy({ preferRemote: true });
  const [activeSection, setActiveSection] = useState('intro');

  const sections = useMemo(() => {
    return [...data.sections]
      .sort((a, b) => a.order - b.order)
      .map((s) => ({
        id: s.id,
        icon: getIcon(s.icon),
        title: getI18nValue(s.title, language) || s.title.en,
        content: getI18nValue(s.content, language) || s.content.en,
      }));
  }, [data.sections, language]);

  useSeo({
    title: t('seo.privacyTitle'),
    description: t('seo.privacyDescription'),
    keywords: t('seo.privacyKeywords'),
    type: 'article',
    pageKey: 'privacy',
  });

  const scrollToSection = (id: string) => {
    setActiveSection(id);
    const el = document.getElementById(id);
    if (el) {
      el.scrollIntoView({ behavior: 'smooth', block: 'start' });
    }
  };

  useEffect(() => {
    if (loading) return;
    const observer = new IntersectionObserver(
      (entries) => {
        entries.forEach((entry) => {
          if (entry.isIntersecting) {
            setActiveSection(entry.target.id);
          }
        });
      },
      { threshold: 0.2, rootMargin: '-80px 0px -50% 0px' }
    );

    sections.forEach((s) => {
      const el = document.getElementById(s.id);
      if (el) observer.observe(el);
    });

    return () => observer.disconnect();
  }, [loading, sections]);

  return (
    <div className="min-h-screen bg-background">
      {/* Breadcrumb */}
      <div className="w-full border-b border-border bg-card/20">
        <div className="max-w-7xl mx-auto px-4 md:px-6 py-3">
          <PageBreadcrumb
            firstItem={{ label: t('nav.home'), href: '/', icon: 'home' }}
            items={[{ label: t('privacy.title') }]}
          />
        </div>
      </div>

      {/* Header */}
      <section className="w-full py-12 md:py-16 bg-muted/30 border-b border-border/40">
        <div className="max-w-7xl mx-auto px-4 md:px-6">
          <h1 className="text-3xl md:text-4xl font-bold text-foreground mb-3">
            {t('privacy.title')}
          </h1>
          <p className="text-sm text-muted-foreground">
            {t('privacy.lastUpdated')}: {data.lastUpdated}
          </p>
        </div>
      </section>

      <section className="w-full py-10 md:py-12">
        <div className="max-w-7xl mx-auto px-4 md:px-6">
          <div className="grid grid-cols-1 lg:grid-cols-[240px_1fr] gap-8">
            {/* Sidebar nav */}
            <aside className="hidden lg:block">
              <div className="sticky top-24 space-y-1">
                {sections.map((s) => {
                  const Icon = s.icon;
                  const isActive = activeSection === s.id;
                  return (
                    <button
                      key={s.id}
                      onClick={() => scrollToSection(s.id)}
                      className={`w-full flex items-center gap-3 px-3 py-2.5 rounded-md text-left text-sm transition-colors ${
                        isActive
                          ? 'bg-primary/10 text-primary font-medium'
                          : 'text-muted-foreground hover:text-foreground hover:bg-accent/10'
                      }`}
                    >
                      <Icon className="size-4 shrink-0" />
                      <span>{s.title}</span>
                    </button>
                  );
                })}
              </div>
            </aside>

            {/* Content */}
            <div className="space-y-10">
              {sections.map((s, idx) => (
                <motion.article
                  key={s.id}
                  id={s.id}
                  initial={{ opacity: 0, y: 20 }}
                  whileInView={{ opacity: 1, y: 0 }}
                  viewport={{ once: true }}
                  transition={{ duration: 0.4, delay: idx * 0.05 }}
                  className="scroll-mt-24"
                >
                  <div className="flex items-center gap-3 mb-4">
                    <div className="w-10 h-10 rounded-lg bg-primary/10 flex items-center justify-center">
                      <s.icon className="size-5 text-primary" />
                    </div>
                    <h2 className="text-xl md:text-2xl font-bold text-foreground">
                      {s.title}
                    </h2>
                  </div>
                  <div className="prose prose-sm max-w-none text-muted-foreground leading-relaxed space-y-3">
                    {s.content.split('\n\n').map((para, i) => (
                      <p key={i}>{para}</p>
                    ))}
                  </div>
                </motion.article>
              ))}
            </div>
          </div>
        </div>
      </section>
    </div>
  );
}
