import { motion } from 'framer-motion';
import {
  ShieldCheck,
  Award,
  CheckCircle2,
  Factory,
  Zap,
  Target,
  Palette,
  Box,
} from 'lucide-react';
import { Badge } from '@/components/ui/badge';
import { Card, CardContent } from '@/components/ui/card';
import { useI18n } from '@/i18n/I18nContext';
import { useSeo } from '@/hooks/useSeo';
import { Image } from '@/components/ui/image';
import { useAdvantages } from '@/hooks/useAdvantages';
import PageBreadcrumb from '@/components/PageBreadcrumb';
import { useSiteImages } from '@/hooks/useSiteImages';
import { useAboutContent } from '@/hooks/useAboutContent';
import { getI18nValue } from '@/lib/i18n-text';
import { useCatalogPDF } from '@/hooks/useCatalogPDF';
import PDFViewer from '@/components/PDFViewer';

// OEM 服务图标映射（按 id 或 index 兜底）
const OEM_ICONS = [Factory, Zap, Target, Palette, Box, Award];

export default function AboutPage() {
  const { t, language } = useI18n();
  const { advantages, loading: advLoading } = useAdvantages({ preferRemote: true });
  const { getImage } = useSiteImages();
  const { content, loading: aboutLoading } = useAboutContent({ preferRemote: true });

  useSeo({
    title: t('seo.aboutTitle'),
    description: t('seo.aboutDescription'),
    keywords: t('seo.aboutKeywords'),
    type: 'article',
    pageKey: 'about',
  });

  const heroImg = content.heroImage || getImage('about_hero');
  const oemImg = getImage('about_oem');
  const { pdfInfo } = useCatalogPDF();

  const galleryImgs = (content.showGallery ? content.gallery.filter((g) => g.visible !== false) : []).length > 0
    ? content.gallery.filter((g) => g.visible !== false)
    : ['about_gallery_1', 'about_gallery_2', 'about_gallery_3', 'about_gallery_4'].map((k) => ({
        id: k,
        image: getImage(k),
        title: undefined,
        description: undefined,
        visible: true,
      }));

  const loading = aboutLoading || advLoading;

  if (loading || !content) {
    return (
      <div className="min-h-screen bg-background flex items-center justify-center">
        <div className="text-muted-foreground">Loading...</div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-background">
      {/* Breadcrumb */}
      <div className="w-full border-b border-border bg-card/20">
        <div className="max-w-7xl mx-auto px-4 md:px-6 py-3">
          <PageBreadcrumb
            firstItem={{ label: t('nav.home'), href: '/', icon: 'home' }}
            items={[{ label: t('nav.about') }]}
          />
        </div>
      </div>

      {/* Hero */}
      {content.showHero && (
        <section className="w-full py-20 md:py-28 bg-muted/30 border-b border-border/40 relative overflow-hidden">
        <div className="absolute inset-0 bg-gradient-to-r from-black/70 to-black/40 z-10" />
        <div className="absolute inset-0">
          <Image
            src={heroImg}
            alt={getI18nValue(content.heroTitle, language)}
            className="absolute inset-0 w-full h-full object-cover"
          />
        </div>
        <div className="relative z-20 max-w-7xl mx-auto px-4 md:px-6">
          <h1 className="text-4xl md:text-5xl lg:text-6xl font-black text-white mb-4 max-w-3xl leading-tight">
            {getI18nValue(content.heroTitle, language)}
          </h1>
          <p className="text-lg text-white/80 max-w-2xl">
            {getI18nValue(content.heroSubtitle, language)}
          </p>
        </div>
      </section>
      )}

      {/* Company intro with stats & gallery */}
      {(content.showIntro || (content.showGallery && galleryImgs.length > 0) || (content.showStats && content.stats.length > 0)) && (
        <section className="w-full py-16 md:py-20">
        <div className="max-w-7xl mx-auto px-4 md:px-6">
            <div className="grid grid-cols-1 lg:grid-cols-2 gap-12 items-center">
              {content.showIntro ? (
                <motion.div
                  initial={{ opacity: 0, x: -20 }}
                  whileInView={{ opacity: 1, x: 0 }}
                  viewport={{ once: true }}
                  transition={{ duration: 0.6 }}
                >
                  <h2 className="text-3xl md:text-4xl font-bold text-foreground mb-4">
                    {getI18nValue(content.introTitle, language)}
                  </h2>
                  <div className="space-y-4 mb-8">
                    {content.introParagraphs.map((p) => (
                      <p key={p.id} className="text-muted-foreground leading-relaxed">
                        {getI18nValue(p.text, language)}
                      </p>
                    ))}
                  </div>
                  {content.showStats && content.stats.length > 0 && (
                    <div
                      className="grid gap-4"
                      style={{ gridTemplateColumns: `repeat(${Math.min(content.stats.length, 4)}, minmax(0, 1fr))` }}
                    >
                      {content.stats.map((stat) => (
                        <div
                          key={stat.id}
                          className="text-center p-4 rounded-lg border border-border/40 bg-card/50"
                        >
                          <div className="text-2xl md:text-3xl font-black text-primary mb-1">{stat.value}</div>
                          <div className="text-xs text-muted-foreground">
                            {getI18nValue(stat.label, language)}
                          </div>
                        </div>
                      ))}
                    </div>
                  )}
                </motion.div>
              ) : content.showStats && content.stats.length > 0 ? (
                <motion.div
                  initial={{ opacity: 0, y: 20 }}
                  whileInView={{ opacity: 1, y: 0 }}
                  viewport={{ once: true }}
                  transition={{ duration: 0.6 }}
                >
                  <div
                    className="grid gap-4"
                    style={{ gridTemplateColumns: `repeat(${Math.min(content.stats.length, 4)}, minmax(0, 1fr))` }}
                  >
                    {content.stats.map((stat) => (
                      <div
                        key={stat.id}
                        className="text-center p-4 rounded-lg border border-border/40 bg-card/50"
                      >
                        <div className="text-2xl md:text-3xl font-black text-primary mb-1">{stat.value}</div>
                        <div className="text-xs text-muted-foreground">
                          {getI18nValue(stat.label, language)}
                        </div>
                      </div>
                    ))}
                  </div>
                </motion.div>
              ) : (
                <div />
              )}

            <motion.div
              initial={{ opacity: 0, x: 20 }}
              whileInView={{ opacity: 1, x: 0 }}
              viewport={{ once: true }}
              transition={{ duration: 0.6, delay: 0.1 }}
              className="relative"
            >
              {content.showGallery && galleryImgs.length > 0 && (
                <div className="grid grid-cols-2 gap-3">
                <div className="space-y-3">
                  {galleryImgs[0] && (
                    <div className="relative aspect-[3/4] rounded-xl overflow-hidden">
                      <Image
                        src={galleryImgs[0].image}
                        alt={galleryImgs[0].title ? getI18nValue(galleryImgs[0].title, language) : 'Factory'}
                        className="absolute inset-0 w-full h-full object-cover"
                      />
                    </div>
                  )}
                  {galleryImgs[2] && (
                    <div className="relative aspect-square rounded-xl overflow-hidden">
                      <Image
                        src={galleryImgs[2].image}
                        alt={galleryImgs[2].title ? getI18nValue(galleryImgs[2].title, language) : 'Factory'}
                        className="absolute inset-0 w-full h-full object-cover"
                      />
                    </div>
                  )}
                </div>
                <div className="space-y-3 pt-8">
                  {galleryImgs[1] && (
                    <div className="relative aspect-square rounded-xl overflow-hidden">
                      <Image
                        src={galleryImgs[1].image}
                        alt={galleryImgs[1].title ? getI18nValue(galleryImgs[1].title, language) : 'Factory'}
                        className="absolute inset-0 w-full h-full object-cover"
                      />
                    </div>
                  )}
                  {galleryImgs[3] && (
                    <div className="relative aspect-[3/4] rounded-xl overflow-hidden">
                      <Image
                        src={galleryImgs[3].image}
                        alt={galleryImgs[3].title ? getI18nValue(galleryImgs[3].title, language) : 'Factory'}
                        className="absolute inset-0 w-full h-full object-cover"
                      />
                    </div>
                  )}
                </div>
                </div>
              )}
            </motion.div>
            </div>
        </div>
      </section>
      )}

      {/* Milestones Timeline */}
      {content.showMilestones && content.milestones.length > 0 && (
        <section className="w-full py-16 md:py-20 bg-muted/30">
          <div className="max-w-5xl mx-auto px-4 md:px-6">
            <div className="text-center mb-14">
                <h2 className="text-3xl md:text-4xl font-bold text-foreground">
                 {getI18nValue(content.milestonesTitle, language)}
               </h2>
            </div>

            <div className="relative">
              <div className="absolute left-4 md:left-1/2 top-0 bottom-0 w-px bg-border" />

              {content.milestones.map((milestone, idx) => (
                <motion.div
                  key={milestone.id}
                  initial={{ opacity: 0, y: 24 }}
                  whileInView={{ opacity: 1, y: 0 }}
                  viewport={{ once: true }}
                  transition={{ duration: 0.5, delay: idx * 0.1 }}
                  className={`relative mb-10 last:mb-0 ${
                    idx % 2 === 0
                      ? 'md:pr-[calc(50%+2rem)] md:text-right'
                      : 'md:pl-[calc(50%+2rem)] md:ml-auto'
                  } pl-12 md:pl-0`}
                >
                  <div className="absolute left-4 md:left-1/2 top-1.5 -translate-x-1/2 w-3 h-3 rounded-full bg-primary ring-4 ring-background z-10" />
                  <Card className="border-border/40 bg-card">
                    <CardContent className="p-5">
                      <div className="text-primary font-bold text-lg mb-1">{milestone.year}</div>
                      <h3 className="font-semibold text-foreground mb-2">
                        {getI18nValue(milestone.title, language)}
                      </h3>
                      <p className="text-sm text-muted-foreground">
                        {getI18nValue(milestone.description, language)}
                      </p>
                    </CardContent>
                  </Card>
                </motion.div>
              ))}
            </div>
          </div>
        </section>
      )}

      {/* Product Catalog */}
      {content.showProductCatalog && (
        <section className="w-full py-16 md:py-20">
        <div className="max-w-7xl mx-auto px-4 md:px-6">
          <div className="text-center mb-10">
            <h2 className="text-3xl md:text-4xl font-bold text-foreground mb-3">
              {t('about.catalogTitle')}
            </h2>
            <p className="text-muted-foreground max-w-2xl mx-auto">
              {t('about.catalogSubtitle')}
            </p>
          </div>

          <PDFViewer
            pdfUrl={pdfInfo.url}
            fileName={pdfInfo.name}
            minHeight="500px"
            maxHeight="900px"
          />
        </div>
      </section>
      )}

      {/* Quality Control */}
      {content.showStrictQC && content.qualitySteps.length > 0 && (
        <section className="w-full py-16 md:py-20">
          <div className="max-w-7xl mx-auto px-4 md:px-6">
            <div className="text-center mb-12">
              <h2 className="text-3xl md:text-4xl font-bold text-foreground mb-3">
                {getI18nValue(content.qualityTitle, language)}
              </h2>
              <p className="text-muted-foreground max-w-2xl mx-auto">
                {getI18nValue(content.qualitySubtitle, language)}
              </p>
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-5">
              {content.qualitySteps.map((step, idx) => (
                <motion.div
                  key={step.id}
                  initial={{ opacity: 0, y: 24 }}
                  whileInView={{ opacity: 1, y: 0 }}
                  viewport={{ once: true }}
                  transition={{ duration: 0.5, delay: idx * 0.1 }}
                >
                  <Card className="h-full border-border/40 bg-card/80 relative overflow-hidden group hover:border-primary/30 transition-colors">
                    <div className="absolute top-0 left-0 right-0 h-1 bg-primary scale-x-0 group-hover:scale-x-100 transition-transform origin-left" />
                    <CardContent className="p-6">
                      <div className="w-12 h-12 rounded-lg bg-primary/10 flex items-center justify-center mb-4 text-primary font-bold text-lg">
                        {step.order.toString().padStart(2, '0')}
                      </div>
                      <h3 className="text-lg font-semibold text-foreground mb-2">
                        {getI18nValue(step.title, language)}
                      </h3>
                      <p className="text-sm text-muted-foreground leading-relaxed">
                        {getI18nValue(step.description, language)}
                      </p>
                    </CardContent>
                  </Card>
                </motion.div>
              ))}
            </div>
          </div>
        </section>
      )}

      {/* Certifications */}
      {content.showGlobalCertifications && content.certifications.length > 0 && (
        <section className="w-full py-16 md:py-20 bg-muted/30">
          <div className="max-w-7xl mx-auto px-4 md:px-6">
            <div className="text-center mb-12">
                <h2 className="text-3xl md:text-4xl font-bold text-foreground mb-3">
                {getI18nValue(content.certificationsTitle, language)}
              </h2>
              <p className="text-muted-foreground max-w-2xl mx-auto">
                {getI18nValue(content.certificationsSubtitle, language)}
              </p>
            </div>

            <div
              className="grid gap-4 md:gap-6"
              style={{
                gridTemplateColumns: `repeat(${Math.min(content.certifications.length, 4)}, minmax(0, 1fr))`,
              }}
            >
              {content.certifications.map((cert, idx) => {
                const Icon = idx % 2 === 0 ? ShieldCheck : Award;
                return (
                  <motion.div
                    key={cert.id}
                    initial={{ opacity: 0, scale: 0.9 }}
                    whileInView={{ opacity: 1, scale: 1 }}
                    viewport={{ once: true }}
                    transition={{ duration: 0.4, delay: idx * 0.1 }}
                  >
                    <Card className="border-border/40 bg-card text-center hover:border-primary/30 transition-colors h-full">
                      <CardContent className="p-6 md:p-8">
                        {cert.image ? (
                          <div className="w-14 h-14 mx-auto mb-4 flex items-center justify-center">
                            <Image
                              src={cert.image}
                              alt={getI18nValue(cert.name, language)}
                              className="max-w-full max-h-full object-contain"
                            />
                          </div>
                        ) : (
                          <div className="w-14 h-14 mx-auto rounded-full bg-primary/10 flex items-center justify-center mb-4">
                            <Icon className="size-7 text-primary" strokeWidth={1.8} />
                          </div>
                        )}
                        <h3 className="text-lg font-bold text-foreground mb-1">
                          {getI18nValue(cert.name, language)}
                        </h3>
                        <p className="text-xs text-muted-foreground">
                          {getI18nValue(cert.authority, language)}
                        </p>
                      </CardContent>
                    </Card>
                  </motion.div>
                );
              })}
            </div>
          </div>
        </section>
      )}

      {/* OEM Capabilities */}
      {content.showOEM && (
        <section className="w-full py-16 md:py-20">
        <div className="max-w-7xl mx-auto px-4 md:px-6">
          <div className="grid grid-cols-1 lg:grid-cols-2 gap-12 items-center">
            <div>
               <h2 className="text-3xl md:text-4xl font-bold text-foreground mb-4">
                {getI18nValue(content.oemTitle, language)}
              </h2>
              <p className="text-muted-foreground mb-8 leading-relaxed">
                {getI18nValue(content.oemDescription, language)}
              </p>

              <div className="space-y-3">
                {content.oemServices.map((service, idx) => {
                  const Icon = OEM_ICONS[idx % OEM_ICONS.length];
                  return (
                    <motion.div
                      key={service.id}
                      initial={{ opacity: 0, x: -20 }}
                      whileInView={{ opacity: 1, x: 0 }}
                      viewport={{ once: true }}
                      transition={{ duration: 0.4, delay: idx * 0.05 }}
                      className="flex items-start gap-3"
                    >
                      <CheckCircle2 className="size-5 text-primary shrink-0 mt-0.5" />
                      <div>
                        <div className="font-semibold text-foreground">
                          {getI18nValue(service.title, language)}
                        </div>
                        <div className="text-sm text-muted-foreground">
                          {getI18nValue(service.description, language)}
                        </div>
                      </div>
                    </motion.div>
                  );
                })}
              </div>
            </div>

            <div className="relative">
              <div className="absolute -inset-4 bg-gradient-to-br from-primary/15 to-transparent rounded-3xl blur-2xl" />
              <div className="relative rounded-2xl overflow-hidden border border-border/40">
                <Image
                  src={oemImg}
                  alt="OEM manufacturing"
                  className="w-full h-[400px] object-cover"
                />
                <div className="absolute inset-0 bg-gradient-to-t from-black/60 to-transparent" />
                 <div className="absolute bottom-6 left-6 right-6">
                   <h3 className="text-xl font-bold text-white mb-1">
                     {t('about.yourBrandOurExpertise')}
                   </h3>
                   <p className="text-sm text-white/80">
                     {t('about.buildYourBrand')}
                   </p>
                 </div>
              </div>
            </div>
          </div>
        </div>
      </section>
      )}
    </div>
  );
}
