import { useState, useEffect, useCallback, useMemo } from 'react';
import { scopedStorage } from '@lark-apaas/client-toolkit-lite';
import { createI18nText, migrateI18n, type I18nText } from '@/lib/i18n-text';
import { useRemoteDataStore } from '@/context/RemoteDataContext';

const STORAGE_KEY = '__app_ledlight_advantages_v3';
const STORAGE_VERSION = 3;

export interface IAdvantage {
  id: string;
  title: I18nText;
  icon: string;
  description: I18nText;
  order: number;
}

const DEFAULT_ADVANTAGES: IAdvantage[] = [
  {
    id: '1',
    title: createI18nText('Industry Experience'),
    icon: 'Factory',
    description: createI18nText(
      '10+ years of professional LED lighting manufacturing experience with 20,000㎡ production facility.'
    ),
    order: 1,
  },
  {
    id: '2',
    title: createI18nText('Global Certification'),
    icon: 'ShieldCheck',
    description: createI18nText(
      'CE, RoHS, ISO9001, FCC certified products ensuring quality and compliance for global markets.'
    ),
    order: 2,
  },
  {
    id: '3',
    title: createI18nText('OEM/ODM/JDM Customization'),
    icon: 'Settings',
    description: createI18nText(
      'Custom logo, housing design, packaging, and technical parameters to perfectly fit your brand identity.'
    ),
    order: 3,
  },
];

function migrateFromLegacy(raw: unknown): IAdvantage[] | null {
  let arr: unknown[] = [];
  if (Array.isArray(raw)) {
    arr = raw;
  } else if (raw && typeof raw === 'object' && Array.isArray((raw as { data?: unknown[] }).data)) {
    arr = (raw as { data: unknown[] }).data;
  }
  if (!arr.length) return null;
  try {
    return arr.map((item, idx) => {
      const a = item as Record<string, unknown>;
      return {
        id: String(a.id ?? `adv_${idx}`),
        title: migrateI18n(a.title as string | I18nText),
        icon: String(a.icon ?? 'Award'),
        description: migrateI18n(a.description as string | I18nText),
        order: Number(a.order ?? idx + 1),
      };
    });
  } catch {
    return null;
  }
}

function readLocalAdvantages(): IAdvantage[] {
  try {
    const saved = scopedStorage.getItem(STORAGE_KEY);
    if (saved) {
      const parsed = JSON.parse(saved);
      if (
        parsed.__version === STORAGE_VERSION &&
        Array.isArray(parsed.data) &&
        parsed.data.length > 0
      ) {
        return parsed.data
          .map((a: Record<string, unknown>) => ({
            ...a,
            title: migrateI18n(a.title as string | I18nText | undefined),
            description: migrateI18n(a.description as string | I18nText | undefined),
          }))
          .sort((a: IAdvantage, b: IAdvantage) => a.order - b.order);
      }
      const migrated = migrateFromLegacy(parsed);
      if (migrated && migrated.length > 0) {
        return migrated.sort((a, b) => a.order - b.order);
      }
    }
  } catch {
    // ignore
  }
  return DEFAULT_ADVANTAGES;
}

export function useAdvantages(options?: { preferRemote?: boolean }) {
  const preferRemote = options?.preferRemote ?? false;
  const remoteData = useRemoteDataStore<IAdvantage[]>('advantages');
  // 🔴 同步初始化：直接读 localStorage 作为初始值，避免首帧默认值 → 第二帧读 localStorage 同值不同引用的重渲染
  // 为什么不在 useEffect 里再读一次？—— 内容可能完全相同但引用不同，仍会触发整棵子树 re-render，用户感知为闪烁
  // preferRemote 模式下：首屏直接展示本地数据，远程数据到达后静默替换
  const [advantages, setAdvantages] = useState<IAdvantage[]>(() => {
    try {
      const saved = scopedStorage.getItem(STORAGE_KEY);
      if (saved) {
        const parsed = JSON.parse(saved);
        if (
          parsed.__version === STORAGE_VERSION &&
          Array.isArray(parsed.data) &&
          parsed.data.length > 0
        ) {
          const mapped = parsed.data.map((a: Record<string, unknown>) => ({
            ...a,
            title: migrateI18n(a.title as string | I18nText | undefined),
            description: migrateI18n(a.description as string | I18nText | undefined),
          }));
          return mapped.sort((a, b) => a.order - b.order);
        }
        const migrated = migrateFromLegacy(parsed);
        if (migrated && migrated.length > 0) {
          return migrated.sort((a, b) => a.order - b.order);
        }
      }
    } catch {
      // ignore
    }
    // 没有本地数据或读取失败，用默认值并持久化
    setTimeout(() => persist(DEFAULT_ADVANTAGES), 0);
    return DEFAULT_ADVANTAGES;
  });

  // loading 始终为 false：本地数据同步初始化完成，不存在 loading 态
  const loading = false;

  // 最终展示的数据：优先远程数据，失败回退本地
  // 🔴 防闪烁：remoteData 为 null（未加载或加载失败）时直接返回本地 advantages
  const displayAdvantages = useMemo(() => {
    if (preferRemote && remoteData && Array.isArray(remoteData) && remoteData.length > 0) {
      return remoteData
        .map((a) => ({
          ...a,
          title: migrateI18n(a.title as string | I18nText | undefined),
          description: migrateI18n(a.description as string | I18nText | undefined),
        }))
        .sort((a, b) => a.order - b.order);
    }
    return advantages;
  }, [preferRemote, remoteData, advantages]);

  const persist = (items: IAdvantage[]) => {
    try {
      scopedStorage.setItem(
        STORAGE_KEY,
        JSON.stringify({ __version: STORAGE_VERSION, data: items })
      );
    } catch {
      // ignore
    }
  };

  const saveAdvantages = useCallback((items: IAdvantage[]) => {
    const sorted = [...items].sort((a, b) => a.order - b.order);
    try {
      persist(sorted);
    } catch (err) {
      const msg = err instanceof Error ? err.message : String(err);
      throw new Error(`Failed to save advantages to storage: ${msg}`);
    }
    setAdvantages(sorted);
  }, []);

  const addAdvantage = useCallback(
    (advantage: Omit<IAdvantage, 'id'>): IAdvantage => {
      const newItem: IAdvantage = {
        ...advantage,
        id: `adv_${Date.now()}_${Math.random().toString(36).slice(2, 8)}`,
      };
      saveAdvantages([...advantages, newItem]);
      return newItem;
    },
    [advantages, saveAdvantages]
  );

  const updateAdvantage = useCallback(
    (id: string, updates: Partial<IAdvantage>) => {
      const updated = advantages.map((a) => (a.id === id ? { ...a, ...updates } : a));
      saveAdvantages(updated);
    },
    [advantages, saveAdvantages]
  );

  const deleteAdvantage = useCallback(
    (id: string) => {
      saveAdvantages(advantages.filter((a) => a.id !== id));
    },
    [advantages, saveAdvantages]
  );

  return {
    advantages: displayAdvantages,
    loading,
    addAdvantage,
    updateAdvantage,
    deleteAdvantage,
    isUsingRemoteData: preferRemote && !!remoteData,
  };
}
