import { StrictMode } from "react";
import { createRoot } from "react-dom/client";
import { BrowserRouter } from "react-router-dom";
import { ErrorBoundary } from "react-error-boundary";
import { AppContainer, ErrorRender } from "@lark-apaas/client-toolkit-lite";
import App from "./app";
import { getDynamicBasename } from "./utils/basename";
import "./index.css";

// GitHub Pages SPA fallback 路径恢复：
// 404.html 会把原始路径存入 sessionStorage 并重定向到 index.html。
// 此处先取出并用 history.replaceState 恢复浏览器地址栏，
// 再计算 basename，保证 basename 和 BrowserRouter 都基于正确的 pathname。
// 最终 URL 干净无 #，BrowserRouter 能正确识别如 /admin 等路径。
(function restoreSpaRedirect() {
  if (typeof window === 'undefined') return;
  try {
    const redirect = sessionStorage.getItem('spa-redirect');
    if (redirect && redirect !== '/') {
      sessionStorage.removeItem('spa-redirect');
      window.history.replaceState(null, '', redirect);
    }
  } catch {
    // sessionStorage 不可用时忽略
  }
})();

// 动态计算 basename：自动适配根路径部署和 GitHub Pages 子路径部署
// 注意：必须在 restoreSpaRedirect 之后执行，否则 pathname 不正确
const BASENAME = getDynamicBasename();

createRoot(document.getElementById("root")!).render(
  <StrictMode>
    <BrowserRouter basename={BASENAME}>
      <AppContainer>
        <ErrorBoundary
          fallbackRender={({ error, resetErrorBoundary }) => (
            <ErrorRender error={error} resetErrorBoundary={resetErrorBoundary} />
          )}
        >
          <App />
        </ErrorBoundary>
      </AppContainer>
    </BrowserRouter>
  </StrictMode>,
);
