import { MessageCircle } from 'lucide-react';
import { UniversalLink } from '@lark-apaas/client-toolkit-lite';
import { useFooterSettings } from '@/hooks/useFooterSettings';
import { normalizeWhatsAppUrl } from '@/lib/whatsapp';

export default function WhatsAppButton() {
  const { settings } = useFooterSettings();

  const whatsappUrl = normalizeWhatsAppUrl(
    settings.whatsappUrl,
    "Hello, I'm interested in your LED products"
  );

  if (!whatsappUrl || settings.whatsappEnabled === false) return null;

  return (
    <UniversalLink
      to={whatsappUrl}
      target="_blank"
      rel="noopener noreferrer"
      className="fixed bottom-24 right-4 md:bottom-8 md:right-8 z-50 group"
      aria-label="WhatsApp Chat"
    >
      <div className="relative">
        {/* Pulse ring */}
        <div className="absolute inset-0 rounded-full bg-[#25D366] animate-ping opacity-30" />
        {/* Button */}
        <div className="relative w-14 h-14 md:w-16 md:h-16 rounded-full bg-[#25D366] hover:bg-[#128C7E] shadow-2xl flex items-center justify-center transition-all duration-300 group-hover:scale-110">
          <MessageCircle className="w-7 h-7 md:w-8 md:h-8 text-white" strokeWidth={2} />
        </div>
      </div>
    </UniversalLink>
  );
}
