const DEFAULT_SITE_TITLE = 'OWELL Industrial - LED Sensor Light Manufacture';

/**
 * Title 守卫：
 * 妙搭平台 AppContainer 内部的 useAppInfo 会把 document.title 设为 info.name。
 * 当平台应用名称是模板变量（如 {appName}）时，会覆盖正确的页面标题。
 * 此守卫通过 MutationObserver + 轮询双重保障，持续修正异常的 title。
 */
function useTitleGuard() {
  useEffect(() => {
    const isSuspiciousTitle = (title: string): boolean => {
      if (!title) return true;
      // 包含模板变量占位符
      if (/\{[a-zA-Z_][\w]*\}/.test(title)) return true;
      // 纯数字 ID / app_ 开头的纯 ID
      if (/^app_\w+/.test(title)) return true;
      // 标题过短或只有空格
      if (title.trim().length < 5) return true;
      return false;
    };

    const fixTitle = () => {
      const current = document.title;
      if (isSuspiciousTitle(current)) {
        document.title = DEFAULT_SITE_TITLE;
      }
    };

    // 初始修正一次
    fixTitle();

    // 用 MutationObserver 监听 title 元素变化
    let observer: MutationObserver | null = null;
    try {
      const titleEl = document.querySelector('title');
      if (titleEl) {
        observer = new MutationObserver(() => {
          fixTitle();
        });
        observer.observe(titleEl, { childList: true, characterData: true, subtree: true });
      }
    } catch {
      // MutationObserver 不可用时降级为轮询
    }

    // 兜底轮询（应对 title 元素被完全替换的场景）
    const intervalId = window.setInterval(fixTitle, 2000);

    return () => {
      if (observer) observer.disconnect();
      window.clearInterval(intervalId);
    };
  }, []);
}

function useFaviconGuard() {
  useEffect(() => {
    const base = getDynamicBasename();
    const basePath = base === '/' ? '' : base;
    const faviconUrl = `${basePath}/favicon.png`;

    const isBrokenOrTemplate = (href: string): boolean => {
      if (!href) return true;
      // 模板变量占位符
      if (/\{[a-zA-Z_][\w]*\}/.test(href)) return true;
      // 空 data URI
      if (href === 'data:,' || href.startsWith('data:,,')) return true;
      // 只有 app_ 开头的纯 ID 路径（无意义）
      if (/^[\w\-./]*app_\w+[\w\-./]*$/.test(href) && !href.endsWith('.png') && !href.endsWith('.ico')) return true;
      return false;
    };

    const setFavicon = () => {
      // 移除所有已有的 icon link
      const existing = document.querySelectorAll('link[rel="icon"], link[rel="shortcut icon"]');
      let needsReplace = existing.length === 0;
      existing.forEach((el) => {
        if (isBrokenOrTemplate(el.getAttribute('href') || '')) {
          needsReplace = true;
        }
      });

      if (!needsReplace) return;

      // 清除旧的
      existing.forEach((el) => el.remove());

      // 创建新的 favicon link
      const link = document.createElement('link');
      link.rel = 'icon';
      link.type = 'image/png';
      link.sizes = '64x64';
      link.href = faviconUrl;
      document.head.appendChild(link);

      // 补充 shortcut icon（兼容旧浏览器）
      const shortcut = document.createElement('link');
      shortcut.rel = 'shortcut icon';
      shortcut.type = 'image/png';
      shortcut.href = faviconUrl;
      document.head.appendChild(shortcut);
    };

    // 初始设置
    setFavicon();

    // 用 MutationObserver 监听 head 变化，防止平台后续注入覆盖
    let observer: MutationObserver | null = null;
    try {
      observer = new MutationObserver(() => {
        const iconLinks = document.querySelectorAll('link[rel="icon"], link[rel="shortcut icon"]');
        let broken = iconLinks.length === 0;
        iconLinks.forEach((el) => {
          if (isBrokenOrTemplate(el.getAttribute('href') || '')) broken = true;
        });
        if (broken) setFavicon();
      });
      observer.observe(document.head, { childList: true, subtree: false });
    } catch {
      // 降级
    }

    // 兜底轮询
    const intervalId = window.setInterval(setFavicon, 3000);

    return () => {
      if (observer) observer.disconnect();
      window.clearInterval(intervalId);
    };
  }, []);
}

