// 清理旧新闻模块遗留的 localStorage 数据（v1-v5 全部），释放存储配额
function useLegacyNewsCleanup() {
  useEffect(() => {
    const legacyKeys = [
      '__app_ledlight_news',
      '__app_ledlight_news_v2',
      '__app_ledlight_news_v3',
      '__app_ledlight_news_v4',
      '__app_ledlight_news_v5',
    ];
    let cleaned = 0;
    for (const key of legacyKeys) {
      try {
        if (scopedStorage.getItem(key) !== null) {
          scopedStorage.removeItem(key);
          cleaned++;
        }
      } catch {
        // 忽略读取/删除失败
      }
    }
    if (cleaned > 0) {
      logger.info(`Cleaned up ${cleaned} legacy news storage keys`);
    }
  }, []);
}

