/* ========== 图片路径迁移 ========== */
const EXTERNAL_IMAGE_PATTERNS = [/unsplash\.com/i, /doubaocdn\.com/i, /picsum\.photos/i, /pexels\.com/i];
const DEFAULT_PRODUCT_IMAGES = [
  imgPath('/images/product-1.jpg'),
  imgPath('/images/product-2.jpg'),
  imgPath('/images/product-3.jpg'),
  imgPath('/images/product-4.jpg'),
];

function migrateImageUrl(url: string, idx: number = 0): string {
  if (!url) return DEFAULT_PRODUCT_IMAGES[idx % DEFAULT_PRODUCT_IMAGES.length];
  // 如果是外部链接，替换为本地默认图
  if (EXTERNAL_IMAGE_PATTERNS.some((p) => p.test(url))) {
    return DEFAULT_PRODUCT_IMAGES[idx % DEFAULT_PRODUCT_IMAGES.length];
  }
  // 如果是裸 /images/ 开头（旧数据，没有 basename 前缀），用 imgPath 补全
  if (url.startsWith('/images/')) {
    return imgPath(url);
  }
  return url;
}

/* ========== 数据迁移 ========== */
function migrateProduct(raw: unknown): IProduct {
  const r = raw as Record<string, unknown>;
  const galleryArr = Array.isArray(r.gallery)
    ? (r.gallery as string[]).filter((g) => typeof g === 'string' && g.length > 0)
    : [];
  const firstImg = galleryArr[0] ?? (typeof r.image === 'string' ? r.image : '');
  const gallery = firstImg ? [firstImg, ...galleryArr.slice(1)] : [];

  const customFields = Array.isArray(r.customFields)
    ? (r.customFields as Array<{ key: unknown; value: unknown }>)
        .filter(
          (f) =>
            f &&
            (typeof f.key === 'string' || (f.key && typeof f.key === 'object' && 'en' in f.key)) &&
            (typeof f.value === 'string' || (f.value && typeof f.value === 'object' && 'en' in f.value))
        )
        .map((f) => ({
          key: migrateI18n(f.key as string | I18nText),
          value: migrateI18n(f.value as string | I18nText),
        }))
    : [];

  return {
    id: typeof r.id === 'string' ? r.id : `p_mig_${Date.now()}_${Math.random().toString(36).slice(2, 8)}`,
    name: migrateI18n(r.name as string | I18nText | undefined),
    category: typeof r.category === 'string' && r.category ? r.category : 'AC Powered',
    image: migrateImageUrl(firstImg, 0),
    gallery: gallery.map((g, i) => migrateImageUrl(g, i)),
    customFields,
    description: migrateI18n(r.description as string | I18nText | undefined),
    structureInfo: migrateI18n(r.structureInfo as string | I18nText | undefined),
    features: Array.isArray(r.features)
      ? (r.features as Array<string | I18nText>).map((f) =>
          typeof f === 'string' ? createI18nText(f) : migrateI18n(f),
        )
      : [],
    applicationScenes: Array.isArray(r.applicationScenes)
      ? (r.applicationScenes as Array<string | I18nText>).map((s) =>
          typeof s === 'string' ? createI18nText(s) : migrateI18n(s),
        )
      : [],
    oemSupported: typeof r.oemSupported === 'boolean' ? r.oemSupported : true,
    sortOrder: typeof r.sortOrder === 'number' ? r.sortOrder : 0,
    featuredOnHomepage: typeof r.featuredOnHomepage === 'boolean' ? r.featuredOnHomepage : false,
    createdAt: typeof r.createdAt === 'number' ? r.createdAt : Date.now(),
  };
}

/**
 * 从 localStorage 加载旧数据（用于迁移到 IndexedDB）
 * 尝试多种 key 前缀模式，兼容 scopedStorage 和各种历史 key
 */
function loadProductsFromLocalStorage(): IProduct[] | null {
  // 1. 先尝试 scopedStorage（带 appId 前缀的官方方式）
  try {
    const saved = scopedStorage.getItem(STORAGE_KEY);
    if (saved) {
      const parsed = JSON.parse(saved);
      if (Array.isArray(parsed) && parsed.length > 0) {
        return parsed.map(migrateProduct);
      }
    }
  } catch {
    // ignore
  }

  // 2. 再尝试裸 localStorage 中各种可能的 key（兼容历史版本）
  if (typeof localStorage !== 'undefined') {
    const candidates: string[] = [];
    for (let i = 0; i < localStorage.length; i++) {
      const k = localStorage.key(i);
      if (k && k.includes('products') && k.includes('led')) {
        candidates.push(k);
      }
    }
    // 优先用 v3 版本，其次最新的
    candidates.sort((a, b) => {
      const a3 = a.includes('v3') ? 1 : 0;
      const b3 = b.includes('v3') ? 1 : 0;
      return b3 - a3;
    });

    for (const key of candidates) {
      try {
        const saved = localStorage.getItem(key);
        if (saved) {
          const parsed = JSON.parse(saved);
          if (Array.isArray(parsed) && parsed.length > 0) {
            return parsed.map(migrateProduct);
          }
        }
      } catch {
        continue;
      }
    }
  }

  return null;
}

/**
 * Promise 超时包装
 */
function withTimeout<T>(promise: Promise<T>, ms: number, errorMsg: string): Promise<T> {
  return new Promise((resolve, reject) => {
    const timer = setTimeout(() => {
      reject(new Error(errorMsg));
    }, ms);
    promise
      .then((result) => {
        clearTimeout(timer);
        resolve(result);
      })
      .catch((err) => {
        clearTimeout(timer);
        reject(err);
      });
  });
}

/**
 * 初始化产品数据：
 * 1. 先检查 IndexedDB 是否有数据（带超时保护）
 * 2. 没有则尝试从 localStorage 迁移旧数据
 * 3. 都没有则使用默认数据写入 IndexedDB
 * 4. IndexedDB 任何失败都降级到 localStorage + 默认数据
 */
async function initializeProducts(): Promise<IProduct[]> {
  try {
    // 用超时保护 IndexedDB 操作（某些浏览器隐私模式下 IndexedDB 可能永远 pending）
    const hasData = await withTimeout(
      idbHasProducts(),
      INIT_TIMEOUT_MS,
      'IndexedDB hasProducts timed out'
    );

    if (hasData) {
      const products = await withTimeout(
        idbGetAll(),
        INIT_TIMEOUT_MS,
        'IndexedDB getAll timed out'
      );
      // 双重校验：如果 count > 0 但 getAll 返回空，可能数据损坏，走迁移/默认
      if (products.length > 0) {
        logger.info(`Loaded ${products.length} products from IndexedDB`);
        // 关键：IndexedDB 里可能存有旧版本数据（缺 customFields/features 等字段），
        // 统一走一次 migrateProduct 做标准化，避免后续 .map() 报错
        const migrated = products.map(migrateProduct);
        // 归一化 sortOrder，保证同分类内唯一且连续（老数据可能全为 0）
        return assignSortOrders(migrated);
      }
      logger.warn('IndexedDB hasProducts=true but getAll returned empty, re-seeding');
    }

    // IndexedDB 为空，尝试从 localStorage 迁移
    const migrated = loadProductsFromLocalStorage();
    if (migrated && migrated.length > 0) {
      // 归一化 sortOrder
      const normalized = assignSortOrders(migrated);
      try {
        await withTimeout(
          idbAddBatch(normalized),
          INIT_TIMEOUT_MS,
          'IndexedDB migration batch add timed out'
        );
        try { scopedStorage.setItem(MIGRATION_FLAG, '1'); } catch { /* ignore */ }
        logger.info(`Migrated ${migrated.length} products from localStorage to IndexedDB`);
        return normalized;
      } catch (migErr) {
        logger.warn('IndexedDB migration failed, returning migrated data without IDB persistence:', String(migErr));
        // 迁移写入失败，但数据本身可用，先返回给用户用
        return migrated;
      }
    }

    // 都没有，写入默认数据到 IndexedDB
    const seedData = assignSortOrders(DEFAULT_PRODUCTS);
    try {
      await withTimeout(
        idbAddBatch(seedData),
        INIT_TIMEOUT_MS,
        'IndexedDB default seed timed out'
      );
      logger.info(`Seeded IndexedDB with ${DEFAULT_PRODUCTS.length} default products`);
    } catch (seedErr) {
      logger.warn('IndexedDB default seed failed:', String(seedErr));
      // 写入失败，尝试保存到 localStorage 作为兜底
      try {
        scopedStorage.setItem(STORAGE_KEY, JSON.stringify(DEFAULT_PRODUCTS));
      } catch { /* ignore */ }
    }
    return seedData;
  } catch (err) {
    // IndexedDB 全面失败，尝试从 localStorage 读
    logger.warn('IndexedDB init failed, falling back:', String(err));
    try {
      const fallback = loadProductsFromLocalStorage();
      if (fallback && fallback.length > 0) {
        return fallback;
      }
    } catch {
      // ignore
    }
    return assignSortOrders([...DEFAULT_PRODUCTS]);
  }
}

/**
 * 同步写入 localStorage 作为 IndexedDB 的镜像兜底
 * IndexedDB 是主存储，localStorage 是热备（不含大图时够用）
 */
function mirrorToLocalStorage(products: IProduct[]) {
  try {
    // 只存非 base64 的元数据到 localStorage（避免超限），作为降级时的基本数据
    const lite = products.map((p) => ({
      ...p,
      // 如果 gallery 里是 base64，只保留第一张且尝试不存 base64 到 localStorage
      gallery: p.gallery.filter((g) => !g.startsWith('data:')),
      image: p.image.startsWith('data:') ? '' : p.image,
    }));
    scopedStorage.setItem(STORAGE_KEY, JSON.stringify(lite));
  } catch {
    // localStorage 可能超限，忽略
  }
}

/* ========== 排序工具函数 ========== */
function sortProducts(products: IProduct[]): IProduct[] {
  // 先按分类排序（按 PRODUCT_SERIES 顺序），再按 sortOrder 升序，再按 createdAt 降序
  const categoryOrder: Record<string, number> = {};
  PRODUCT_SERIES.forEach((s, i) => {
    categoryOrder[s.key] = i;
  });
  return [...products].sort((a, b) => {
    const ca = categoryOrder[a.category] ?? 999;
    const cb = categoryOrder[b.category] ?? 999;
    if (ca !== cb) return ca - cb;
    if (a.sortOrder !== b.sortOrder) return a.sortOrder - b.sortOrder;
    return b.createdAt - a.createdAt;
  });
}

function getMaxSortOrderInCategory(products: IProduct[], category: string): number {
  let max = -1;
  for (const p of products) {
    if (p.category === category && p.sortOrder > max) {
      max = p.sortOrder;
    }
  }
  return max;
}

/**
 * 同分类内按 (sortOrder, createdAt) 排序后，重新分配连续唯一的 sortOrder (0,1,2...)
 * 用于处理历史数据 sortOrder 全为 0 的情况，保证上移下移有真实效果
 */
function assignSortOrders(products: IProduct[]): IProduct[] {
  // 先按现有规则排序并浅拷贝，避免修改原对象
  const sorted = sortProducts(products).map((p) => ({ ...p }));
  // 按分类分组，每组内从 0 开始重新编号
  const byCategory: Record<string, IProduct[]> = {};
  sorted.forEach((p) => {
    if (!byCategory[p.category]) byCategory[p.category] = [];
    byCategory[p.category].push(p);
  });
  Object.values(byCategory).forEach((list) => {
    list.forEach((p, i) => {
      p.sortOrder = i;
    });
  });
  return sorted;
}

/* ========== 首页产品轮播设置 ========== */
export interface IProductDisplaySettings {
  showProductCarousel: boolean;
  carouselMaxCount: number;
}

const DEFAULT_PRODUCT_SETTINGS: IProductDisplaySettings = {
  showProductCarousel: true,
  carouselMaxCount: 8,
};

let storeProductSettings: IProductDisplaySettings = { ...DEFAULT_PRODUCT_SETTINGS };
const settingsSubscribers = new Set<(settings: IProductDisplaySettings) => void>();

function loadProductSettings(): IProductDisplaySettings {
  try {
    const raw = scopedStorage.getItem(SETTINGS_KEY);
    if (!raw) return { ...DEFAULT_PRODUCT_SETTINGS };
    const parsed = JSON.parse(raw);
    return {
      showProductCarousel: typeof parsed.showProductCarousel === 'boolean' ? parsed.showProductCarousel : true,
      carouselMaxCount: typeof parsed.carouselMaxCount === 'number' && parsed.carouselMaxCount > 0 ? parsed.carouselMaxCount : 8,
    };
  } catch {
    return { ...DEFAULT_PRODUCT_SETTINGS };
  }
}

function saveProductSettings(settings: IProductDisplaySettings) {
  storeProductSettings = settings;
  try {
    scopedStorage.setItem(SETTINGS_KEY, JSON.stringify(settings));
  } catch {
    // ignore
  }
  settingsSubscribers.forEach((cb) => cb(settings));
}

/* ========== 模块级单例 Store（多实例共享） ========== */
// 🔴 同步初始化 storeProducts：首渲染就有默认数据，避免空数组闪烁
// IndexedDB 真实数据在 ensureInit 异步加载后替换
let storeProducts: IProduct[] = assignSortOrders([...DEFAULT_PRODUCTS]);
let storeLoading = true;
let initPromise: Promise<void> | null = null;
const subscribers = new Set<(products: IProduct[], loading: boolean) => void>();

function notifySubscribers() {
  subscribers.forEach((cb) => cb(storeProducts, storeLoading));
}

function setStore(next: IProduct[]) {
  storeProducts = next;
  notifySubscribers();
}

function setStoreLoading(val: boolean) {
  storeLoading = val;
  notifySubscribers();
}

function ensureInit(): Promise<void> {
  if (initPromise) return initPromise;

  initPromise = (async () => {
    try {
      const data = await initializeProducts();
      if (Array.isArray(data) && data.length > 0) {
        storeProducts = data; // initializeProducts 内部已做归一化 + 排序
      } else {
        logger.warn('initializeProducts returned empty, using DEFAULT_PRODUCTS');
        storeProducts = assignSortOrders([...DEFAULT_PRODUCTS]);
      }
    } catch (err) {
      logger.error('useProducts init error:', String(err));
      storeProducts = assignSortOrders([...DEFAULT_PRODUCTS]);
    } finally {
      storeLoading = false;
      notifySubscribers();
    }
  })();

  return initPromise;
}

/* ========== Hook ========== */
export function useProducts(options?: { preferRemote?: boolean }) {
  const preferRemote = options?.preferRemote ?? false;
  const remoteData = useRemoteDataStore<IProduct[]>('products');
  const [products, setProductsState] = useState<IProduct[]>(storeProducts);
  const [loading, setLoadingState] = useState<boolean>(storeLoading);
  const [productSettings, setProductSettingsState] = useState<IProductDisplaySettings>(storeProductSettings);

  /* ---- 设置订阅 ---- */
  useEffect(() => {
    // 初始化时从 localStorage 加载一次
    const loaded = loadProductSettings();
    storeProductSettings = loaded;
    setProductSettingsState(loaded);

    const handler = (next: IProductDisplaySettings) => {
      setProductSettingsState(next);
    };
    settingsSubscribers.add(handler);
    return () => {
      settingsSubscribers.delete(handler);
    };
  }, []);

  const updateProductSettings = useCallback((patch: Partial<IProductDisplaySettings>) => {
    const next = { ...storeProductSettings, ...patch };
    saveProductSettings(next);
  }, []);

  /* ---- 产品订阅 ---- */
  useEffect(() => {
    const handler = (next: IProduct[], nextLoading: boolean) => {
      setProductsState(next);
      setLoadingState(nextLoading);
    };
    subscribers.add(handler);
    // 确保初始化启动（只启动一次）
    ensureInit();
    return () => {
      subscribers.delete(handler);
    };
  }, []);

  const broadcast = useCallback((next: IProduct[]) => {
    setStore(next);
    // 同时派发 window 事件用于跨 tab / iframe 同步
    try {
      const ev = new CustomEvent(SYNC_EVENT_NAME, { detail: next });
      window.dispatchEvent(ev);
    } catch {
      // ignore
    }
  }, []);

  /* ---- CRUD（异步，先写 IndexedDB 成功后再更新 state） ---- */
  const addProduct = useCallback(
    async (
      data: Omit<IProduct, 'id' | 'createdAt' | 'image'> & { gallery: string[]; sortOrder?: number }
    ): Promise<IProduct> => {
      const id = `p_${Date.now()}_${Math.random().toString(36).slice(2, 8)}`;
      const gallery = data.gallery || [];
      // 若调用方没指定 sortOrder，默认排到当前分类最后
      const sortOrder =
        typeof data.sortOrder === 'number' && Number.isFinite(data.sortOrder)
          ? data.sortOrder
          : getMaxSortOrderInCategory(storeProducts, data.category) + 1;
      const newProduct: IProduct = {
        ...data,
        id,
        image: gallery[0] ?? '',
        gallery,
        sortOrder,
        featuredOnHomepage: data.featuredOnHomepage ?? false,
        createdAt: Date.now(),
      };

      // 先写入 IndexedDB，成功再更新 state（保证原子性）
      try {
        await idbAdd(newProduct);
      } catch (err) {
        logger.error('IndexedDB addProduct failed:', String(err));
        throw new Error('Failed to save product. Please try again or reduce image size.');
      }

      const next = sortProducts([newProduct, ...storeProducts]);
      broadcast(next);
      mirrorToLocalStorage(next);
      return newProduct;
    },
    [broadcast]
  );

  const updateProduct = useCallback(
    async (id: string, data: Partial<Omit<IProduct, 'id' | 'createdAt'>>): Promise<IProduct | null> => {
      const existing = storeProducts.find((p) => p.id === id);
      if (!existing) throw new Error('Product not found');

      const gallery = data.gallery ?? existing.gallery;
      const categoryChanged =
        data.category !== undefined && data.category !== existing.category;

      let sortOrder = data.sortOrder ?? existing.sortOrder;
      // 分类改变且调用方没显式传 sortOrder → 放到目标分类末尾
      if (categoryChanged && data.sortOrder === undefined) {
        sortOrder = getMaxSortOrderInCategory(storeProducts, data.category!) + 1;
      }

      const updated: IProduct = {
        ...existing,
        ...data,
        gallery,
        image: gallery[0] ?? existing.image ?? '',
        sortOrder,
      };

      try {
        await idbUpdate(updated);
      } catch (err) {
        logger.error('IndexedDB updateProduct failed:', String(err));
        throw new Error('Failed to update product. Please try again.');
      }

      const next = sortProducts(storeProducts.map((p) => (p.id === id ? updated : p)));
      broadcast(next);
      mirrorToLocalStorage(next);
      return updated;
    },
    [broadcast]
  );

  const moveProduct = useCallback(
    async (id: string, direction: 'up' | 'down'): Promise<void> => {
      const product = storeProducts.find((p) => p.id === id);
      if (!product) return;

      // 取同分类内按 sortOrder 升序排列的列表
      const categoryProducts = storeProducts
        .filter((p) => p.category === product.category)
        .sort((a, b) => a.sortOrder - b.sortOrder || b.createdAt - a.createdAt);

      const currentIndex = categoryProducts.findIndex((p) => p.id === id);
      if (currentIndex === -1) return;

      const targetIndex =
        direction === 'up' ? currentIndex - 1 : currentIndex + 1;

      if (targetIndex < 0 || targetIndex >= categoryProducts.length) return;

      // 防御性归一化：如果同分类存在重复 sortOrder（老数据），先整体重排并写回
      const hasDuplicates = categoryProducts.some((p, i) =>
        i > 0 && p.sortOrder === categoryProducts[i - 1].sortOrder
      );

      let workingList = storeProducts;
      if (hasDuplicates) {
        const normalized = assignSortOrders(storeProducts);
        // 写回所有受影响分类的产品
        try {
          for (const p of normalized) {
            // 只有 sortOrder 变了的才更新，减少写入
            const old = storeProducts.find((o) => o.id === p.id);
            if (!old || old.sortOrder !== p.sortOrder) {
              await idbUpdate(p);
            }
          }
        } catch (err) {
          logger.error('IndexedDB normalize sortOrder failed:', String(err));
          throw new Error('Failed to reorder products.');
        }
        workingList = normalized;
      }

      // 重新在最新数据上找索引
      const freshCategory = workingList
        .filter((p) => p.category === product.category)
        .sort((a, b) => a.sortOrder - b.sortOrder || b.createdAt - a.createdAt);

      const freshIdx = freshCategory.findIndex((p) => p.id === id);
      if (freshIdx === -1) return;

      const newTargetIdx =
        direction === 'up' ? freshIdx - 1 : freshIdx + 1;

      if (newTargetIdx < 0 || newTargetIdx >= freshCategory.length) return;

      const current = freshCategory[freshIdx];
      const target = freshCategory[newTargetIdx];

      // 交换 sortOrder
      const currentOrder = current.sortOrder;
      const targetOrder = target.sortOrder;

      const updatedA: IProduct = { ...current, sortOrder: targetOrder };
      const updatedB: IProduct = { ...target, sortOrder: currentOrder };

      try {
        await idbUpdate(updatedA);
        await idbUpdate(updatedB);
      } catch (err) {
        logger.error('IndexedDB moveProduct failed:', String(err));
        throw new Error('Failed to reorder products.');
      }

      const next = sortProducts(
        workingList.map((p) => {
          if (p.id === updatedA.id) return updatedA;
          if (p.id === updatedB.id) return updatedB;
          return p;
        })
      );
      broadcast(next);
      mirrorToLocalStorage(next);
    },
    [broadcast]
  );

  const deleteProduct = useCallback(
    async (id: string): Promise<void> => {
      try {
        await idbDelete(id);
      } catch (err) {
        logger.error('IndexedDB deleteProduct failed:', String(err));
        throw new Error('Failed to delete product. Please try again.');
      }

      const next = sortProducts(storeProducts.filter((p) => p.id !== id));
      broadcast(next);
      mirrorToLocalStorage(next);
    },
    [broadcast]
  );

  const displayProducts = useMemo(() => {
    if (preferRemote && remoteData && Array.isArray(remoteData) && remoteData.length > 0) {
      return remoteData.map((p) => ({
        ...p,
        name: migrateI18n(p.name as any),
        description: migrateI18n(p.description as any),
        structureInfo: migrateI18n(p.structureInfo as any),
        features: Array.isArray(p.features)
          ? p.features.map((f) => migrateI18n(f as any))
          : [],
        applicationScenes: Array.isArray(p.applicationScenes)
          ? p.applicationScenes.map((a) => migrateI18n(a as any))
          : [],
      })) as IProduct[];
    }
    return products;
  }, [preferRemote, remoteData, products]);

  const displayLoading = preferRemote ? false : loading;

  const getProductById = useCallback(
    (id: string): IProduct | undefined => {
      return displayProducts.find((p) => p.id === id);
    },
    [displayProducts]
  );

  /* ---- 手动刷新 ---- */
  const refresh = useCallback(async (): Promise<void> => {
    try {
      const data = await idbGetAll();
      if (Array.isArray(data) && data.length > 0) {
        broadcast(data);
      }
    } catch (err) {
      logger.error('Failed to refresh products:', String(err));
      toast.error('Failed to refresh products');
    }
  }, [broadcast]);

  /* ---- Storage 优化：批量替换产品图片为 GitHub 路径 ---- */
  const updateProductsWithGithubPaths = useCallback(async (updatedProducts: IProduct[]): Promise<boolean> => {
    try {
      const sorted = sortProducts(updatedProducts);
      // 先更新 IndexedDB
      await idbUpdateBatch(sorted);
      // 再更新内存和 localStorage 镜像
      broadcast(sorted);
      mirrorToLocalStorage(sorted);
      return true;
    } catch (err) {
      logger.error('[Storage-optimize] Failed to batch update products with GitHub paths:', String(err));
      return false;
    }
  }, [broadcast]);

  /* ---- 统计 ---- */
  const stats = useMemo(() => {
    const total = displayProducts.length;
    const byCategory: Record<string, number> = {};
    displayProducts.forEach((p) => {
      byCategory[p.category] = (byCategory[p.category] ?? 0) + 1;
    });
    return { total, byCategory };
  }, [displayProducts]);

  const toggleFeatured = useCallback(
    async (id: string): Promise<void> => {
      const existing = storeProducts.find((p) => p.id === id);
      if (!existing) return;
      const updated: IProduct = {
        ...existing,
        featuredOnHomepage: !existing.featuredOnHomepage,
      };
      try {
        await idbUpdate(updated);
      } catch (err) {
        logger.error('IndexedDB toggleFeatured failed:', String(err));
        throw new Error('Failed to update featured status.');
      }
      const next = storeProducts.map((p) => (p.id === id ? updated : p));
      broadcast(next);
      mirrorToLocalStorage(next);
    },
    [broadcast]
  );

  return {
    products: displayProducts,
    loading: displayLoading,
    stats,
    addProduct,
    updateProduct,
    deleteProduct,
    moveProduct,
    toggleFeatured,
    getProductById,
    refresh,
    updateProductsWithGithubPaths,
    productSettings,
    updateProductSettings,
    isUsingRemoteData: preferRemote && !!remoteData,
  };
}

export default useProducts;
