import { useState, useEffect, useMemo, type FormEvent } from 'react';
import { useSearchParams } from 'react-router-dom';
import { useSeo } from '@/hooks/useSeo';
import { motion } from 'framer-motion';
import { Mail, Phone, MapPin, Clock, MessageCircle, Send, Paperclip, X } from 'lucide-react';
import { Badge } from '@/components/ui/badge';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Textarea } from '@/components/ui/textarea';
import { Card, CardContent } from '@/components/ui/card';
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogDescription } from '@/components/ui/dialog';
import {
  Select,
  SelectContent,
  SelectGroup,
  SelectItem,
  SelectLabel,
  SelectTrigger,
  SelectValue,
} from '@/components/ui/select';
import { useI18n } from '@/i18n/I18nContext';
import { useProducts } from '@/hooks/useProducts';
import { useInquiries } from '@/hooks/useInquiries';
import { useEmailSettings } from '@/hooks/useEmailSettings';
import { useFooterSettings } from '@/hooks/useFooterSettings';
import { normalizeWhatsAppUrl } from '@/lib/whatsapp';
import { imgPath } from '@/utils/img-path';
import { toast } from 'sonner';
import { UniversalLink } from '@lark-apaas/client-toolkit-lite';
import PageBreadcrumb from '@/components/PageBreadcrumb';
import {
  FacebookIcon,
  LinkedinIcon,
  TwitterIcon,
  InstagramIcon,
  WhatsappIcon,
  WechatIcon,
} from '@/components/SocialIcons';

export default function ContactPage() {
  const { t, language } = useI18n();
  const { products } = useProducts({ preferRemote: true });
  const { addInquiry, buildMailto, sendInquiryEmail } = useInquiries();
  const { settings: emailSettings, isConfigured: emailConfigured } = useEmailSettings();
  const { settings: footerSettings } = useFooterSettings({ preferRemote: true });
  const [searchParams] = useSearchParams();
  const categoryParam = searchParams.get('category') || '';
  const productIdParam = searchParams.get('product') || '';

  // 从产品中提取所有类目（去重），询盘表单可选择类目或具体产品
  const categories = Array.from(new Set(products.map((p) => p.category))).sort();

  // 根据 URL 中的 productId 找到对应产品
  const preselectedProduct = useMemo(
    () => products.find((p) => p.id === productIdParam) || null,
    [products, productIdParam]
  );

  useSeo({
    title: t('seo.contactTitle'),
    description: t('seo.contactDescription'),
    keywords: t('seo.contactKeywords'),
    type: 'website',
    pageKey: 'contact',
  });

  const [formData, setFormData] = useState({
    name: '',
    company: '',
    email: '',
    country: '',
    category: categoryParam && categories.includes(categoryParam) ? categoryParam : 'all',
    productId: preselectedProduct?.id || '',
    message: '',
  });
  const [attachment, setAttachment] = useState<File | null>(null);
  const [submitting, setSubmitting] = useState(false);

  // 当 URL 中带 category 参数（从产品列表页跳转过来），且类目在可选列表中时，默认选中
  useEffect(() => {
    if (categoryParam && categories.includes(categoryParam)) {
      setFormData((prev) => ({ ...prev, category: categoryParam }));
    }
  }, [categoryParam, categories]);

  // 当 URL 中带 product 参数（从产品详情页跳转过来），自动填入对应产品
  useEffect(() => {
    if (preselectedProduct) {
      setFormData((prev) => ({
        ...prev,
        category: preselectedProduct.category,
        productId: preselectedProduct.id,
        message: prev.message || `Hi, I'm interested in ${typeof preselectedProduct.name === 'string' ? preselectedProduct.name : preselectedProduct.name.en}. Could you send me more details and a quotation?`,
      }));
    }
  }, [preselectedProduct]);

  const handleSubmit = async (e: FormEvent) => {
    e.preventDefault();
    if (!formData.name || !formData.email || !formData.company) {
      toast.error('Please fill in required fields');
      return;
    }
    setSubmitting(true);
    await new Promise((r) => setTimeout(r, 1200));
    const categoryName = formData.category === 'all' ? t('products.allCategories') : formData.category;
    const productName = preselectedProduct?.name
      ? typeof preselectedProduct.name === 'string'
        ? preselectedProduct.name
        : preselectedProduct.name.en
      : '';
    const inquiryData = {
      name: formData.name,
      company: formData.company,
      email: formData.email,
      country: formData.country,
      product: formData.productId,
      productName,
      category: formData.category,
      categoryName,
      message: formData.message,
      source: 'contact' as const,
      createdAt: Date.now(),
    };
    const newInquiry = addInquiry(inquiryData);
    // 自动发送邮件（异步，不阻塞 UI）
    if (emailConfigured) {
      sendInquiryEmail(newInquiry, emailSettings.endpoint, emailSettings.recipientEmail);
    }
    toast.success(t('contact.successMsg'), {
      action: {
        label: t('contact.sendEmailNotify'),
        onClick: () => {
          const link = document.createElement('a');
          link.href = buildMailto(inquiryData);
          link.rel = 'noopener noreferrer';
          document.body.appendChild(link);
          link.click();
          document.body.removeChild(link);
        },
      },
    });
    setFormData({ name: '', company: '', email: '', country: '', category: 'all', productId: '', message: '' });
    setAttachment(null);
    setSubmitting(false);
  };

  const whatsappUrl = normalizeWhatsAppUrl(
    footerSettings.whatsappUrl,
    'Hello, I would like to inquire about LED lights'
  );

  const [qrOpen, setQrOpen] = useState(false);
  const [qrHover, setQrHover] = useState(false);
  const wechatQrSrc = footerSettings.wechatQrImage || imgPath('/images/wechat-qr.png');

  const socialLinks = useMemo(() => [
    { name: 'Facebook', url: footerSettings.facebookUrl, Icon: FacebookIcon, enabled: footerSettings.facebookEnabled !== false },
    { name: 'LinkedIn', url: footerSettings.linkedinUrl, Icon: LinkedinIcon, enabled: footerSettings.linkedinEnabled !== false },
    { name: 'Twitter', url: footerSettings.twitterHandle?.startsWith('@') ? `https://twitter.com/${footerSettings.twitterHandle.slice(1)}` : footerSettings.twitterHandle, Icon: TwitterIcon, enabled: footerSettings.twitterEnabled !== false },
    { name: 'Instagram', url: footerSettings.instagramUrl, Icon: InstagramIcon, enabled: footerSettings.instagramEnabled !== false },
    { name: 'WhatsApp', url: footerSettings.whatsappUrl, Icon: WhatsappIcon, enabled: footerSettings.whatsappEnabled !== false },
    { name: 'WeChat', url: footerSettings.wechatUrl, Icon: WechatIcon, enabled: footerSettings.wechatEnabled !== false, isWechat: true },
  ].filter((s) => s.enabled !== false && (s.isWechat || (s.url && s.url.trim().length > 0))), [footerSettings]);

  return (
    <div className="min-h-screen bg-background">
      {/* Breadcrumb */}
      <div className="w-full border-b border-border bg-card/20">
        <div className="max-w-7xl mx-auto px-4 md:px-6 py-3">
          <PageBreadcrumb
            firstItem={{ label: t('nav.home'), href: '/', icon: 'home' }}
            items={[{ label: t('nav.contact') }]}
          />
        </div>
      </div>

      {/* Hero */}
      <section className="w-full py-16 md:py-20 bg-muted/30 border-b border-border/40">
        <div className="max-w-7xl mx-auto px-4 md:px-6">
          <h1 className="text-3xl md:text-5xl font-bold text-foreground mb-3">
            {t('contact.title')}
          </h1>
          <p className="text-muted-foreground max-w-2xl">{t('contact.subtitle')}</p>
        </div>
      </section>

      {/* 12-hour reply banner */}
      <section className="w-full bg-primary py-6">
        <div className="max-w-7xl mx-auto px-4 md:px-6 flex items-center justify-center gap-4">
          <Clock className="size-6 text-primary-foreground shrink-0" />
          <div>
            <h3 className="text-lg font-bold text-primary-foreground">{t('contact.replyBanner')}</h3>
            <p className="text-sm text-primary-foreground/80">{t('contact.replyBannerSub')}</p>
          </div>
        </div>
      </section>

      <section className="w-full py-12 md:py-16">
        <div className="max-w-7xl mx-auto px-4 md:px-6">
          <div className="grid grid-cols-1 lg:grid-cols-3 gap-6 lg:gap-8">
            {/* Contact info */}
            <div className="space-y-4">
              <h2 className="text-xl font-bold text-foreground mb-4">{t('contact.infoTitle')}</h2>

              <Card className="border-border/40 bg-card">
                <CardContent className="p-5 flex items-start gap-4">
                  <div className="w-10 h-10 rounded-lg bg-primary/10 flex items-center justify-center shrink-0">
                    <Mail className="size-5 text-primary" />
                  </div>
                  <div>
                    <h4 className="text-sm font-semibold text-foreground mb-0.5">
                      {t('contact.emailLabel')}
                    </h4>
                     <UniversalLink
                       to={`mailto:${footerSettings.email}`}
                       className="text-sm text-muted-foreground hover:text-primary transition-colors"
                     >
                       {footerSettings.email}
                     </UniversalLink>
                  </div>
                </CardContent>
              </Card>

              <Card className="border-border/40 bg-card">
                <CardContent className="p-5 flex items-start gap-4">
                  <div className="w-10 h-10 rounded-lg bg-primary/10 flex items-center justify-center shrink-0">
                    <Phone className="size-5 text-primary" />
                  </div>
                  <div>
                    <h4 className="text-sm font-semibold text-foreground mb-0.5">
                      {t('contact.phoneLabel')}
                    </h4>
                     <p className="text-sm text-muted-foreground">{footerSettings.phone}</p>
                  </div>
                </CardContent>
              </Card>

              <Card className="border-border/40 bg-card">
                <CardContent className="p-5 flex items-start gap-4">
                  <div className="w-10 h-10 rounded-lg bg-primary/10 flex items-center justify-center shrink-0">
                    <MapPin className="size-5 text-primary" />
                  </div>
                  <div>
                    <h4 className="text-sm font-semibold text-foreground mb-0.5">
                      {t('contact.addressLabel')}
                    </h4>
                     <p className="text-sm text-muted-foreground">{footerSettings.address}</p>
                  </div>
                </CardContent>
              </Card>

              {/* WhatsApp CTA */}
              <UniversalLink
                to={whatsappUrl}
                target="_blank"
                rel="noopener noreferrer"
                className="block"
              >
                <Card className="border-[#25D366]/30 bg-[#25D366]/10 hover:bg-[#25D366]/20 transition-colors cursor-pointer">
                  <CardContent className="p-5 flex items-center gap-4">
                    <div className="w-10 h-10 rounded-lg bg-[#25D366] flex items-center justify-center shrink-0">
                      <MessageCircle className="size-5 text-white" />
                    </div>
                    <div>
                      <h4 className="text-sm font-semibold text-foreground mb-0.5">
                        {t('contact.whatsapp')}
                      </h4>
                      <p className="text-sm text-muted-foreground">{t('contact.whatsappCta')}</p>
                    </div>
                  </CardContent>
                 </Card>
               </UniversalLink>

               {/* Social Media */}
               {socialLinks.length > 0 && (
                 <Card className="border-border/40 bg-card">
                   <CardContent className="p-5">
                     <h4 className="text-sm font-semibold text-foreground mb-3">
                       {t('contact.followUs')}
                     </h4>
                     <div className="flex items-center gap-3 flex-wrap">
                       {socialLinks.map(({ name, url, Icon, isWechat }) => (
                         isWechat ? (
                           <div
                             key={name}
                             className="relative"
                             onMouseEnter={() => setQrHover(true)}
                             onMouseLeave={() => setQrHover(false)}
                           >
                             {/* Hover Popover (desktop, above icon) */}
                             <div
                               className={`absolute bottom-full left-1/2 -translate-x-1/2 mb-3 z-50 transition-all duration-200 ease-out pointer-events-none ${
                                 qrHover
                                   ? 'opacity-100 translate-y-0'
                                   : 'opacity-0 translate-y-1'
                               }`}
                             >
                               <div className="relative bg-card border border-border rounded-sm shadow-lg p-3 w-44">
                                 <p className="text-xs font-semibold text-foreground mb-2 text-center">
                                   Scan QR Code
                                 </p>
                                   <img
                                     src={wechatQrSrc}
                                     alt="WeChat QR Code"
                                     width={144}
                                     height={144}
                                     loading="lazy"
                                     decoding="async"
                                     className="w-36 h-36 object-contain rounded-sm mx-auto bg-background"
                                   />
                                 <p className="text-[11px] text-muted-foreground mt-2 text-center">
                                   Scan with WeChat to add us
                                 </p>
                                 <div className="absolute left-1/2 -translate-x-1/2 -bottom-1.5 w-3 h-3 rotate-45 bg-card border-r border-b border-border" />
                               </div>
                             </div>
                             <button
                               type="button"
                               onClick={() => setQrOpen(true)}
                               aria-label={name}
                               className="group flex items-center justify-center size-10 rounded-full bg-background/60 border border-border/60 transition-all duration-200 hover:scale-110 hover:shadow-lg hover:border-primary/40"
                             >
                               <Icon />
                             </button>
                           </div>
                         ) : (
                           <UniversalLink
                             key={name}
                             to={url}
                             target="_blank"
                             rel="noopener noreferrer"
                             aria-label={name}
                             className="group flex items-center justify-center size-10 rounded-full bg-background/60 border border-border/60 transition-all duration-200 hover:scale-110 hover:shadow-lg hover:border-primary/40"
                           >
                             <Icon />
                           </UniversalLink>
                         )
                       ))}
                     </div>
                   </CardContent>
                 </Card>
               )}
             </div>

            {/* Inquiry form */}
            <div className="lg:col-span-2">
              <Card className="border-border/40 bg-card h-full">
                <CardContent className="p-6 md:p-8">
                  <h2 className="text-xl font-bold text-foreground mb-2">
                    {t('contact.formTitle')}
                  </h2>
                  <p className="text-sm text-muted-foreground mb-6">{t('contact.formSubtitle')}</p>

                  <form onSubmit={handleSubmit} className="space-y-4">
                    <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                      <div>
                        <label className="text-xs font-medium text-foreground mb-1.5 block">
                          {t('contact.name')} *
                        </label>
                        <Input
                          value={formData.name}
                          onChange={(e) => setFormData({ ...formData, name: e.target.value })}
                          placeholder="Your Name"
                          required
                        />
                      </div>
                      <div>
                        <label className="text-xs font-medium text-foreground mb-1.5 block">
                          {t('contact.company')} *
                        </label>
                        <Input
                          value={formData.company}
                          onChange={(e) => setFormData({ ...formData, company: e.target.value })}
                          placeholder="Your Company Ltd."
                          required
                        />
                      </div>
                    </div>

                    <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                      <div>
                        <label className="text-xs font-medium text-foreground mb-1.5 block">
                          {t('contact.email')} *
                        </label>
                        <Input
                          type="email"
                          value={formData.email}
                          onChange={(e) => setFormData({ ...formData, email: e.target.value })}
                          placeholder="you@company.com"
                          required
                        />
                      </div>
                      <div>
                        <label className="text-xs font-medium text-foreground mb-1.5 block">
                          {t('contact.country')}
                        </label>
                        <Input
                          value={formData.country}
                          onChange={(e) => setFormData({ ...formData, country: e.target.value })}
                          placeholder="United States"
                        />
                      </div>
                       <div>
                         <label className="text-xs font-medium text-foreground mb-1.5 block">
                           {t('contact.interestedProduct')}
                         </label>
                         {preselectedProduct ? (
                           // 从产品详情页跳转：显示具体产品选择器（按类目分组）
                           <Select
                             value={formData.productId || 'all'}
                             onValueChange={(v) => {
                               if (v === 'all') {
                                 setFormData({ ...formData, productId: '', category: 'all' });
                               } else {
                                 const p = products.find((prod) => prod.id === v);
                                 setFormData({
                                   ...formData,
                                   productId: v,
                                   category: p?.category || formData.category,
                                 });
                               }
                             }}
                           >
                             <SelectTrigger>
                               <SelectValue placeholder="Select product" />
                             </SelectTrigger>
                             <SelectContent>
                               <SelectItem value="all">{t('products.allCategories')}</SelectItem>
                               {categories.map((cat) => (
                                 <SelectGroup key={cat}>
                                   <SelectLabel>{cat}</SelectLabel>
                                   {products
                                     .filter((p) => p.category === cat)
                                     .map((p) => (
                                       <SelectItem key={p.id} value={p.id}>
                                         {typeof p.name === 'string' ? p.name : p.name.en}
                                       </SelectItem>
                                     ))}
                                 </SelectGroup>
                               ))}
                             </SelectContent>
                           </Select>
                         ) : (
                           // 直接访问或从其他页面跳转：只显示类目选择器
                           <Select
                             value={formData.category}
                             onValueChange={(v) => setFormData({ ...formData, category: v, productId: '' })}
                           >
                             <SelectTrigger>
                               <SelectValue placeholder="Select category" />
                             </SelectTrigger>
                             <SelectContent>
                               <SelectItem value="all">{t('products.allCategories')}</SelectItem>
                               {categories.map((cat) => (
                                 <SelectItem key={cat} value={cat}>
                                   {cat}
                                 </SelectItem>
                               ))}
                             </SelectContent>
                           </Select>
                         )}
                       </div>
                    </div>

                    <div>
                      <label className="text-xs font-medium text-foreground mb-1.5 block">
                        {t('contact.message')} *
                      </label>
                      <Textarea
                        value={formData.message}
                        onChange={(e) => setFormData({ ...formData, message: e.target.value })}
                        placeholder="Please describe your requirements, quantity, specifications..."
                        rows={5}
                        required
                        className="resize-none"
                      />
                    </div>

                      <div className="space-y-2">
                        <label className="text-xs font-medium text-foreground mb-1.5 block">
                          {t('contact.attachment')}
                        </label>
                        <div className="flex items-stretch gap-2">
                          <div className="flex-1 min-w-0 h-10 px-3 bg-input border border-input rounded-sm flex items-center text-sm overflow-hidden">
                            {attachment ? (
                              <span className="truncate text-foreground">{attachment.name}</span>
                            ) : (
                              <span className="text-muted-foreground truncate">{t('contact.noFileChosen')}</span>
                            )}
                          </div>
                          <label className="cursor-pointer shrink-0">
                            <input
                              type="file"
                              accept=".pdf,.jpg,.jpeg,.png,.dxf,.step,.stl,.doc,.docx,.xls,.xlsx"
                              multiple
                              onChange={(e) => {
                                const file = e.target.files?.[0];
                                if (file) {
                                  if (file.size > 20 * 1024 * 1024) {
                                    toast.error('File too large. Maximum size is 20MB.');
                                    return;
                                  }
                                  setAttachment(file);
                                }
                                e.target.value = '';
                              }}
                              className="sr-only"
                            />
                            <span className="inline-flex items-center justify-center h-10 px-4 rounded-sm bg-secondary text-secondary-foreground text-sm font-medium hover:bg-secondary/80 border border-border transition-colors">
                              <Paperclip className="size-4 mr-1.5" />
                              {t('contact.chooseFile')}
                            </span>
                          </label>
                          {attachment && (
                            <button
                              type="button"
                              onClick={() => setAttachment(null)}
                              className="shrink-0 h-10 px-3 rounded-sm bg-secondary text-secondary-foreground hover:bg-secondary/80 border border-border flex items-center justify-center transition-colors"
                              aria-label="Remove attachment"
                            >
                              <X className="size-4" />
                            </button>
                          )}
                        </div>
                        <p className="text-[11px] text-muted-foreground">
                          PDF, JPG, PNG, DXF, STEP, DOC — max 20MB
                        </p>
                      </div>

                    <Button
                      type="submit"
                      size="lg"
                      className="w-full bg-primary hover:bg-primary/90 text-primary-foreground"
                      disabled={submitting}
                    >
                      {submitting ? t('contact.submitting') : t('contact.submit')}
                      {!submitting && <Send className="size-4 ml-2" />}
                    </Button>
                  </form>
                </CardContent>
              </Card>
            </div>
          </div>
        </div>
      </section>

      {/* WeChat QR Dialog (mobile click fallback) */}
      <Dialog open={qrOpen} onOpenChange={setQrOpen}>
        <DialogContent className="sm:max-w-md bg-card border-border text-foreground">
          <DialogHeader>
            <DialogTitle className="text-center text-lg font-semibold">Scan QR Code</DialogTitle>
            <DialogDescription className="text-center text-muted-foreground">
              Open WeChat and scan the QR code to add us
            </DialogDescription>
          </DialogHeader>
          <div className="flex flex-col items-center justify-center gap-4 py-4">
            <div className="relative rounded-lg border border-border bg-background p-3">
              <img
                src={wechatQrSrc}
                alt="WeChat QR Code"
                width={256}
                height={256}
                loading="lazy"
                decoding="async"
                className="w-64 h-64 object-contain rounded-md"
              />
            </div>
            <p className="text-sm text-muted-foreground">
              Scan with WeChat to connect with us
            </p>
          </div>
        </DialogContent>
      </Dialog>
    </div>
  );
}
