import { useState, useMemo, useEffect } from 'react';
import { useNavigate, useSearchParams } from 'react-router-dom';
import { useSeo } from '@/hooks/useSeo';
import { motion, AnimatePresence } from 'framer-motion';
import {
  Search,
  Filter,
  ChevronRight,
  ChevronLeft,
  Zap,
  Sun,
  Battery,
  BatteryCharging,
  RefreshCw,
  Lamp,
  Flashlight,
  Layers,
  X,
  Package,
} from 'lucide-react';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Card } from '@/components/ui/card';
import { Image } from '@/components/ui/image';
import { useProducts } from '@/hooks/useProducts';
import { useCategories } from '@/hooks/useCategories';
import { useI18n } from '@/i18n/I18nContext';
import { cn } from '@/lib/utils';
import { getI18nValue } from '@/lib/i18n-text';
import PageBreadcrumb from '@/components/PageBreadcrumb';
import type { IProduct } from '@/hooks/useProducts';

const SERIES_ICONS: Record<string, typeof Zap> = {
  'AC Powered': Zap,
  'Dry Battery': Battery,
  Solar: Sun,
  Hybrid: RefreshCw,
  Rechargeable: BatteryCharging,
  'Table Lamp': Lamp,
  'Work Light': Flashlight,
};

export default function ProductsPage() {
  const { t, language } = useI18n();
  const navigate = useNavigate();
  const { products, stats } = useProducts({ preferRemote: true });
  const { enabledCategories, slugMap } = useCategories({ preferRemote: true });

  useSeo({
    title: t('seo.productsTitle'),
    description: t('seo.productsDescription'),
    keywords: t('seo.productsKeywords'),
    type: 'website',
    pageKey: 'products',
  });

  const [searchParams] = useSearchParams();
  const [activeSeries, setActiveSeries] = useState<string>(() => {
    const cat = searchParams.get('category');
    return cat || 'all';
  });
  const [search, setSearch] = useState('');
  const [mobileFilterOpen, setMobileFilterOpen] = useState(false);
  const [page, setPage] = useState(1);
  const PAGE_SIZE = 6;

  const filteredProducts = useMemo(() => {
    let list = products;
    if (activeSeries !== 'all') {
      list = list.filter((p) => p.category === activeSeries);
    }
    if (search.trim()) {
      const kw = search.trim().toLowerCase();
      list = list.filter(
        (p) =>
          getI18nValue(p.name, language).toLowerCase().includes(kw) ||
          p.customFields.some(
            (f) =>
              getI18nValue(f.key, language).toLowerCase().includes(kw) ||
              getI18nValue(f.value, language).toLowerCase().includes(kw)
          )
      );
    }
    return list;
  }, [products, activeSeries, search, language]);

  const totalPages = Math.max(1, Math.ceil(filteredProducts.length / PAGE_SIZE));
  const currentPage = Math.min(page, totalPages);
  const paginatedProducts = useMemo(() => {
    const start = (currentPage - 1) * PAGE_SIZE;
    return filteredProducts.slice(start, start + PAGE_SIZE);
  }, [filteredProducts, currentPage]);

  // 筛选/搜索变化时重置到第1页
  useEffect(() => {
    setPage(1);
  }, [activeSeries, search]);

  const handleInquiry = (productName: string) => {
    navigate(`/contact?product=${encodeURIComponent(productName)}`);
  };

  const allCount = stats.total;

  return (
    <div className="min-h-screen bg-background">
      {/* Breadcrumb */}
      <div className="w-full border-b border-border bg-card/20">
        <div className="max-w-7xl mx-auto px-4 md:px-6 py-3">
          <PageBreadcrumb
            firstItem={{ label: t('nav.home'), href: '/', icon: 'home' }}
            items={[{ label: t('nav.products') }]}
          />
        </div>
      </div>

      {/* ========== Page Header ========== */}
      <section className="w-full border-b border-border bg-card/30">
        <div className="max-w-7xl mx-auto px-4 md:px-6 py-12 md:py-16">
          <motion.div
            initial={{ opacity: 0, y: 20 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ duration: 0.5 }}
            className="space-y-3"
            >
            <h1 className="text-4xl md:text-5xl font-bold text-foreground tracking-tight">
              {t('products.title')}
            </h1>
            <p className="text-muted-foreground max-w-2xl">
              {t('products.subtitle') ||
                'Professional LED lighting solutions with PIR motion sensor. 7 product series for every application scenario. OEM & ODM customization available.'}
            </p>
          </motion.div>
        </div>
      </section>

      {/* ========== Main Content ========== */}
      <section className="w-full py-8 md:py-12">
        <div className="max-w-7xl mx-auto px-4 md:px-6">
          {/* Mobile Filter Toggle */}
          <div className="md:hidden mb-4 flex gap-2">
            <Button
              variant="outline"
              size="sm"
              onClick={() => setMobileFilterOpen(true)}
              className="flex-1"
            >
              <Filter className="size-4 mr-2" />
              {t('products.filter')}
            </Button>
          </div>

          <div className="flex gap-6 md:gap-8">
            {/* ========== Left Sidebar (Desktop) ========== */}
            <aside className="hidden md:block w-60 shrink-0">
              <div className="sticky top-24 space-y-1 bg-card/40 rounded-lg border border-border/50 p-3">
                <div className="flex items-center gap-2 px-1 pb-2 mb-2 border-b border-border/50">
                  <div className="w-1 h-4 bg-primary rounded-full" />
                  <div className="text-xs font-semibold text-foreground uppercase tracking-wider">
                    {t('products.categories')}
                  </div>
                </div>
                <button
                  onClick={() => setActiveSeries('all')}
                  className={cn(
                    'w-full flex items-center justify-between px-3 py-2.5 rounded-md text-sm transition-all duration-200 text-left group',
                    activeSeries === 'all'
                      ? 'bg-primary/10 text-primary font-medium'
                      : 'text-muted-foreground hover:text-foreground hover:bg-card/80'
                  )}
                >
                  <span className="flex items-center gap-2.5">
                    <div className={cn(
                      'size-7 rounded-md flex items-center justify-center transition-colors',
                      activeSeries === 'all' ? 'bg-primary/20 text-primary' : 'bg-muted/50 text-muted-foreground group-hover:text-foreground'
                    )}>
                      <Layers className="size-4" />
                    </div>
                    {t('products.allSeries')}
                  </span>
                  <span className={cn(
                    'text-xs px-1.5 py-0.5 rounded-full transition-colors',
                    activeSeries === 'all' ? 'bg-primary/20 text-primary' : 'bg-muted/50 text-muted-foreground'
                  )}>{allCount}</span>
                </button>

                {enabledCategories.map((cat) => {
                  const Icon = SERIES_ICONS[cat.icon] ?? SERIES_ICONS[cat.slug] ?? Package;
                  const count = stats.byCategory[cat.slug] ?? 0;
                  const label = getI18nValue(cat.name, language) || cat.slug;
                  const isActive = activeSeries === cat.slug;
                  return (
                    <button
                      key={cat.slug}
                      onClick={() => setActiveSeries(cat.slug)}
                      className={cn(
                        'w-full flex items-center justify-between px-3 py-2.5 rounded-md text-sm transition-all duration-200 text-left group',
                        isActive
                          ? 'bg-primary/10 text-primary font-medium'
                          : 'text-muted-foreground hover:text-foreground hover:bg-card/80'
                      )}
                    >
                      <span className="flex items-center gap-2.5">
                        <div className={cn(
                          'size-7 rounded-md flex items-center justify-center transition-colors',
                          isActive ? 'bg-primary/20 text-primary' : 'bg-muted/50 text-muted-foreground group-hover:text-foreground'
                        )}>
                          {cat.iconImage ? (
                            <Image
                              src={cat.iconImage}
                              alt={label}
                              className="size-4 object-contain"
                            />
                          ) : (
                            <Icon className="size-4" />
                          )}
                        </div>
                        {label}
                      </span>
                      <span className={cn(
                        'text-xs px-1.5 py-0.5 rounded-full transition-colors',
                        isActive ? 'bg-primary/20 text-primary' : 'bg-muted/50 text-muted-foreground'
                      )}>{count}</span>
                    </button>
                  );
                })}
              </div>
            </aside>

            {/* ========== Right Content ========== */}
            <div className="flex-1 min-w-0">
              {/* Search + Result Count */}
              <div className="flex flex-col sm:flex-row gap-3 mb-6 items-start sm:items-center justify-between">
                <div className="relative w-full sm:w-80">
                  <Search className="pointer-events-none absolute left-3 top-1/2 size-4 -translate-y-1/2 text-muted-foreground" />
                  <Input
                    type="search"
                    value={search}
                    onChange={(e) => setSearch(e.target.value)}
                    placeholder={t('products.searchPlaceholder')}
                    className="bg-card pl-9 h-10"
                  />
                </div>
                <div className="text-sm text-muted-foreground">
                  {filteredProducts.length}{' '}
                  {filteredProducts.length === 1 ? t('products.product') : t('products.products')}
                </div>
              </div>

              {/* Product Grid */}
              <AnimatePresence mode="popLayout">
                {filteredProducts.length > 0 ? (
                  <motion.div
                    key="grid"
                    layout
                    className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-5"
                  >
                     {paginatedProducts.map((product, i) => (
                       <ProductCard
                         key={product.id}
                         product={product}
                         index={i}
                         onInquiry={handleInquiry}
                         onClick={() => navigate(`/products/${product.id}`)}
                       />
                     ))}
                  </motion.div>
                ) : (
                  <motion.div
                    key="empty"
                    initial={{ opacity: 0 }}
                    animate={{ opacity: 1 }}
                    className="flex flex-col items-center justify-center py-20 text-center"
                  >
                    <Package className="size-12 text-muted-foreground/50 mb-4" />
                    <h3 className="text-lg font-medium text-foreground mb-2">
                      {t('products.noResults')}
                    </h3>
                    <p className="text-sm text-muted-foreground mb-6 max-w-sm">
                      {t('products.noResultsDesc') ||
                        'Try adjusting your search or filter to find what you are looking for.'}
                    </p>
                    <Button
                      variant="outline"
                      onClick={() => {
                        setActiveSeries('all');
                        setSearch('');
                      }}
                    >
                      {t('products.viewAll')}
                    </Button>
                  </motion.div>
                )}
               </AnimatePresence>

               {/* Pagination */}
               {filteredProducts.length > PAGE_SIZE && (
                 <div className="flex items-center justify-center gap-2 mt-10 pt-6 border-t border-border/60">
                   <Button
                     variant="outline"
                     size="sm"
                     disabled={currentPage === 1}
                     onClick={() => setPage((p) => Math.max(1, p - 1))}
                     className="gap-1"
                   >
                     <ChevronLeft className="size-4" />
                     Prev
                   </Button>
                   <div className="flex items-center gap-1">
                     {Array.from({ length: totalPages }, (_, i) => i + 1).map((p) => (
                       <Button
                         key={p}
                         size="sm"
                         variant={p === currentPage ? 'default' : 'outline'}
                         onClick={() => setPage(p)}
                         className="min-w-9 w-9 h-9 p-0"
                       >
                         {p}
                       </Button>
                     ))}
                   </div>
                   <Button
                     variant="outline"
                     size="sm"
                     disabled={currentPage === totalPages}
                     onClick={() => setPage((p) => Math.min(totalPages, p + 1))}
                     className="gap-1"
                   >
                     Next
                     <ChevronRight className="size-4" />
                   </Button>
                 </div>
               )}
             </div>
           </div>
         </div>
       </section>

      {/* ========== Mobile Filter Drawer ========== */}
      <AnimatePresence>
        {mobileFilterOpen && (
          <>
            <motion.div
              initial={{ opacity: 0 }}
              animate={{ opacity: 1 }}
              exit={{ opacity: 0 }}
              className="fixed inset-0 z-50 bg-black/60 md:hidden"
              onClick={() => setMobileFilterOpen(false)}
            />
            <motion.div
              initial={{ x: '-100%' }}
              animate={{ x: 0 }}
              exit={{ x: '-100%' }}
              transition={{ type: 'tween', duration: 0.25 }}
              className="fixed top-0 left-0 bottom-0 z-50 w-72 bg-card border-r border-border p-4 md:hidden overflow-y-auto"
            >
              <div className="flex items-center justify-between mb-6">
                <h3 className="font-semibold text-foreground">
                  {t('products.filter')}
                </h3>
                <Button
                  size="icon"
                  variant="ghost"
                  onClick={() => setMobileFilterOpen(false)}
                >
                  <X className="size-5" />
                </Button>
              </div>
              <div className="space-y-1">
                <button
                  onClick={() => {
                    setActiveSeries('all');
                    setMobileFilterOpen(false);
                  }}
                  className={cn(
                    'w-full flex items-center justify-between px-3 py-2.5 rounded-sm text-sm transition-colors text-left',
                    activeSeries === 'all'
                      ? 'bg-primary/10 text-primary border-l-2 border-primary'
                      : 'text-muted-foreground hover:text-foreground hover:bg-background'
                  )}
                >
                  <span className="flex items-center gap-2">
                    <Layers className="size-4" />
                    {t('products.allSeries')}
                  </span>
                  <span className="text-xs">{allCount}</span>
                </button>
                {enabledCategories.map((cat) => {
                  const Icon = SERIES_ICONS[cat.icon] ?? SERIES_ICONS[cat.slug] ?? Package;
                  const count = stats.byCategory[cat.slug] ?? 0;
                  const label = getI18nValue(cat.name, language) || cat.slug;
                  return (
                    <button
                      key={cat.slug}
                      onClick={() => {
                        setActiveSeries(cat.slug);
                        setMobileFilterOpen(false);
                      }}
                      className={cn(
                        'w-full flex items-center justify-between px-3 py-2.5 rounded-sm text-sm transition-colors text-left',
                        activeSeries === cat.slug
                          ? 'bg-primary/10 text-primary border-l-2 border-primary'
                          : 'text-muted-foreground hover:text-foreground hover:bg-background'
                      )}
                    >
                       <span className="flex items-center gap-2">
                         {cat.iconImage ? (
                           <Image
                             src={cat.iconImage}
                             alt={label}
                             className="size-4 object-contain"
                           />
                         ) : (
                           <Icon className="size-4" />
                         )}
                         {label}
                       </span>
                       <span className="text-xs">{count}</span>
                     </button>
                   );
                 })}
               </div>
             </motion.div>
           </>
         )}
       </AnimatePresence>
    </div>
  );
}

/* ========== Product Card ========== */
interface ProductCardProps {
  product: IProduct;
  index: number;
  onInquiry: (name: string) => void;
  onClick: () => void;
}

function ProductCard({ product, index, onInquiry, onClick }: ProductCardProps) {
  const { t, language } = useI18n();
  const [imgError, setImgError] = useState(false);
  const productName = getI18nValue(product.name, language);

  return (
    <motion.div
      layout
      initial={{ opacity: 0, y: 20 }}
      animate={{ opacity: 1, y: 0 }}
      exit={{ opacity: 0, scale: 0.95 }}
      transition={{ duration: 0.4, delay: index * 0.05 }}
      whileHover={{ y: -3, transition: { duration: 0.2 } }}
    >
      <Card className="h-full flex flex-col bg-card border-border overflow-hidden group cursor-pointer hover:border-primary/40 transition-colors">
        {/* Image */}
        <div
          className="relative aspect-square bg-[hsl(0_0%_96%)] flex items-center justify-center overflow-hidden"
          onClick={onClick}
        >
          {imgError || !product.image ? (
            <Package className="size-16 text-muted-foreground/30" />
          ) : (
            <Image
              src={product.image}
              alt={productName}
              className="w-full h-full object-contain transition-transform duration-500 group-hover:scale-105"
              onError={() => setImgError(true)}
            />
          )}
          <ChevronRight className="absolute right-3 top-1/2 -translate-y-1/2 size-5 text-primary opacity-0 group-hover:opacity-100 transition-opacity" />
        </div>

        {/* Content */}
        <div className="p-4 flex-1 flex flex-col" onClick={onClick}>
          <h3 className="text-sm font-semibold text-foreground mb-4 line-clamp-2 min-h-[2.5rem] group-hover:text-primary transition-colors">
            {productName}
          </h3>

          {/* Inquiry Button */}
          <Button
            size="sm"
            className="w-full bg-primary hover:bg-primary/90 text-primary-foreground mt-auto"
            onClick={(e) => {
              e.stopPropagation();
              onInquiry(productName);
            }}
          >
            {t('products.inquiry')}
          </Button>
        </div>
      </Card>
    </motion.div>
  );
}
