import { useState, useEffect, useCallback, useRef } from 'react';
import { resolveAssetUrl } from '@/utils/basename';
import { logger } from '@lark-apaas/client-toolkit-lite';

const DB_NAME = 'app_ledlight_db';
const STORE_NAME = 'pdf_files';
const DB_VERSION = 1;
const CATALOG_ID = 'catalog';

// 默认静态 PDF 文件名（路径在运行时通过 resolveAssetUrl 动态拼接，
// 兼容妙搭平台 / GitHub Pages 子路径 / 根路径部署等多种环境）
const DEFAULT_PDF_PATH = '/files/Catalog.pdf';
const DEFAULT_PDF_NAME = 'Catalog.pdf';

function getDefaultPdfUrl(): string {
  try {
    return resolveAssetUrl(DEFAULT_PDF_PATH);
  } catch (e) {
    logger.error('getDefaultPdfUrl failed:', String(e));
    return DEFAULT_PDF_PATH;
  }
}

function openDB(): Promise<IDBDatabase> {
  return new Promise((resolve, reject) => {
    const request = indexedDB.open(DB_NAME, DB_VERSION);
    request.onerror = () => reject(request.error);
    request.onsuccess = () => resolve(request.result);
    request.onupgradeneeded = (e) => {
      const db = (e.target as IDBOpenDBRequest).result;
      if (!db.objectStoreNames.contains(STORE_NAME)) {
        db.createObjectStore(STORE_NAME, { keyPath: 'id' });
      }
    };
  });
}

export interface IPDFRecord {
  id: string;
  file: Blob;
  name: string;
  size: number;
  uploadDate: number;
}

export interface IPDFInfo {
  url: string;        // object URL 或默认静态 URL
  name: string;
  size: number;
  isCustom: boolean;  // 是否为用户上传
  uploadDate?: number;
}

async function getPDFRecord(db: IDBDatabase, id: string): Promise<IPDFRecord | null> {
  return new Promise((resolve, reject) => {
    const tx = db.transaction(STORE_NAME, 'readonly');
    const store = tx.objectStore(STORE_NAME);
    const request = store.get(id);
    request.onerror = () => reject(request.error);
    request.onsuccess = () => resolve(request.result || null);
  });
}

async function savePDFRecord(db: IDBDatabase, record: IPDFRecord): Promise<void> {
  return new Promise((resolve, reject) => {
    const tx = db.transaction(STORE_NAME, 'readwrite');
    const store = tx.objectStore(STORE_NAME);
    store.put(record);
    tx.oncomplete = () => resolve();
    tx.onerror = () => reject(tx.error);
  });
}

async function deletePDFRecord(db: IDBDatabase, id: string): Promise<void> {
  return new Promise((resolve, reject) => {
    const tx = db.transaction(STORE_NAME, 'readwrite');
    const store = tx.objectStore(STORE_NAME);
    store.delete(id);
    tx.oncomplete = () => resolve();
    tx.onerror = () => reject(tx.error);
  });
}

export function useCatalogPDF() {
  const [pdfInfo, setPdfInfo] = useState<IPDFInfo>({
    url: getDefaultPdfUrl(),
    name: DEFAULT_PDF_NAME,
    size: 0,
    isCustom: false,
  });
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);
  const objectUrlRef = useRef<string | null>(null);

  const revokeCurrentUrl = useCallback(() => {
    if (objectUrlRef.current) {
      URL.revokeObjectURL(objectUrlRef.current);
      objectUrlRef.current = null;
    }
  }, []);

  // 初始化：从 IndexedDB 读取
  useEffect(() => {
    let cancelled = false;
    async function load() {
      try {
        const db = await openDB();
        const record = await getPDFRecord(db, CATALOG_ID);
        db.close();
        if (record && record.file) {
          revokeCurrentUrl();
          const url = URL.createObjectURL(record.file);
          objectUrlRef.current = url;
          if (!cancelled) {
            setPdfInfo({
              url,
              name: record.name,
              size: record.size,
              isCustom: true,
              uploadDate: record.uploadDate,
            });
          }
        }
        // 没有自定义 PDF 时保持默认
      } catch {
        // IndexedDB 不可用或读取失败，回退到默认 PDF
      } finally {
        if (!cancelled) setLoading(false);
      }
    }
    load();
    return () => {
      cancelled = true;
    };
  }, [revokeCurrentUrl]);

  // 组件卸载时释放 object URL
  useEffect(() => {
    return () => {
      revokeCurrentUrl();
    };
  }, [revokeCurrentUrl]);

  const uploadPDF = useCallback(async (file: File): Promise<boolean> => {
    if (file.type !== 'application/pdf') {
      return false;
    }
    // 50MB 限制
    if (file.size > 50 * 1024 * 1024) {
      return false;
    }
    setSaving(true);
    try {
      const db = await openDB();
      const record: IPDFRecord = {
        id: CATALOG_ID,
        file: file,
        name: file.name,
        size: file.size,
        uploadDate: Date.now(),
      };
      await savePDFRecord(db, record);
      db.close();

      // 更新状态
      revokeCurrentUrl();
      const url = URL.createObjectURL(file);
      objectUrlRef.current = url;
      setPdfInfo({
        url,
        name: file.name,
        size: file.size,
        isCustom: true,
        uploadDate: record.uploadDate,
      });
      return true;
    } catch {
      return false;
    } finally {
      setSaving(false);
    }
  }, [revokeCurrentUrl]);

  const resetToDefault = useCallback(async (): Promise<boolean> => {
    try {
      const db = await openDB();
      await deletePDFRecord(db, CATALOG_ID);
      db.close();

      revokeCurrentUrl();
      setPdfInfo({
        url: getDefaultPdfUrl(),
        name: DEFAULT_PDF_NAME,
        size: 0,
        isCustom: false,
      });
      return true;
    } catch {
      return false;
    }
  }, [revokeCurrentUrl]);

  return {
    pdfInfo,
    loading,
    saving,
    uploadPDF,
    resetToDefault,
    defaultPdfUrl: getDefaultPdfUrl(),
    defaultPdfName: DEFAULT_PDF_NAME,
  };
}
