import { useState, useEffect, useCallback } from 'react';
import { scopedStorage, logger } from '@lark-apaas/client-toolkit-lite';
import { imgPath } from '@/utils/img-path';

const STORAGE_KEY = '__app_ledlight_site_images';
const CHANGE_EVENT_NAME = '__app_ledlight_site_images_changed__';

export interface ISiteImageSlot {
  /** 唯一标识，前台用此 key 取图 */
  key: string;
  /** 分组（便于后台页面分组展示） */
  group: 'Home Page' | 'About Page' | 'Contact Page' | 'Header / Footer' | 'Other';
  /** 展示名称 */
  label: string;
  /** 描述 */
  description?: string;
  /** 默认图片 URL（用户未上传时使用） */
  defaultUrl: string;
}

/**
 * 所有可管理的图片位置清单。
 * 新增位置只需在这里加一条，后台和 hook 自动同步。
 */
export const SITE_IMAGE_SLOTS: ISiteImageSlot[] = [
  // 首页
  { key: 'hero_slide_1', group: 'Home Page', label: 'Hero Slides · Slide 1', description: '首页 Hero 轮播第 1 张', defaultUrl: '/images/hero-slide-1.jpg' },
  { key: 'hero_slide_2', group: 'Home Page', label: 'Hero Slides · Slide 2', description: '首页 Hero 轮播第 2 张', defaultUrl: '/images/hero-slide-2.jpg' },
  { key: 'hero_slide_3', group: 'Home Page', label: 'Hero Slides · Slide 3', description: '首页 Hero 轮播第 3 张', defaultUrl: '/images/hero-slide-3.jpg' },
  { key: 'home_factory', group: 'Home Page', label: 'Why Choose Us · Factory Image', description: '首页 Why Choose Us 板块右侧工厂大图', defaultUrl: '/images/why-choose-us.jpg' },

  // 关于我们
  { key: 'about_hero', group: 'About Page', label: 'About Hero Banner', description: '关于我们页 Hero 背景图', defaultUrl: '/images/about-hero.jpg' },
  { key: 'about_gallery_1', group: 'About Page', label: 'Gallery · Production Workshop', description: '工厂画廊第 1 张（生产车间）', defaultUrl: '/images/factory-production.jpg' },
  { key: 'about_gallery_2', group: 'About Page', label: 'Gallery · QC Laboratory', description: '工厂画廊第 2 张（质检实验室）', defaultUrl: '/images/factory-qc.jpg' },
  { key: 'about_gallery_3', group: 'About Page', label: 'Gallery · Warehouse', description: '工厂画廊第 3 张（仓库设施）', defaultUrl: '/images/factory-warehouse.jpg' },
  { key: 'about_gallery_4', group: 'About Page', label: 'Gallery · R&D Center', description: '工厂画廊第 4 张（研发中心）', defaultUrl: '/images/factory-rd.jpg' },
  { key: 'about_gallery_5', group: 'About Page', label: 'Gallery · Assembly Line', description: '工厂画廊第 5 张（装配流水线）', defaultUrl: '/images/factory-assembly.jpg' },
  { key: 'about_gallery_6', group: 'About Page', label: 'Gallery · Testing Center', description: '工厂画廊第 6 张（测试中心）', defaultUrl: '/images/factory-showroom.jpg' },
  { key: 'about_oem', group: 'About Page', label: 'OEM / ODM Section Image', description: '关于页 OEM/ODM 板块插图', defaultUrl: '/images/oem-odm.jpg' },

  // 联系页
  { key: 'contact_hero', group: 'Contact Page', label: 'Contact Hero Background', description: '联系页 Hero 背景图', defaultUrl: '/images/hero-slide-2.jpg' },

  // Logo —— 默认不设外部 URL，直接显示内置 SVG 文字 Logo
  // 用户可在后台上传自定义 Logo，上传后走 base64 存储
  { key: 'logo_header', group: 'Header / Footer', label: 'Header Logo', description: '顶部导航栏 Logo', defaultUrl: '' },
  { key: 'logo_footer', group: 'Header / Footer', label: 'Footer Logo', description: '页脚 Logo', defaultUrl: '' },
];

/** 存储结构：{ [key]: base64Url 或 空串 }，空串表示使用默认图 */
type SiteImageMap = Record<string, string>;

export function useSiteImages() {
  const [overrides, setOverrides] = useState<SiteImageMap>({});
  const [ready, setReady] = useState(false);

  // 初始化：从 localStorage 读取已上传的图片
  useEffect(() => {
    try {
      const saved = scopedStorage.getItem(STORAGE_KEY);
      if (saved) {
        const parsed = JSON.parse(saved);
        if (parsed && typeof parsed === 'object') {
          setOverrides(parsed as SiteImageMap);
        }
      }
    } catch {
      // ignore
    }
    setReady(true);
  }, []);

  // 监听 localStorage 变化（跨标签页 / 跨组件同步）
  useEffect(() => {
    const handleStorage = (e: StorageEvent) => {
      if (e.key !== STORAGE_KEY && !e.key?.endsWith(STORAGE_KEY)) return;
      try {
        const saved = e.newValue;
        if (saved) {
          const parsed = JSON.parse(saved);
          if (parsed && typeof parsed === 'object') {
            setOverrides(parsed as SiteImageMap);
          }
        } else {
          setOverrides({});
        }
      } catch {
        // ignore
      }
    };

    // 监听同一页面内的自定义事件（storage event 只在跨标签页触发，同页不触发）
    const handleCustomChange = (e: Event) => {
      const customEvent = e as CustomEvent<SiteImageMap>;
      if (customEvent.detail) {
        setOverrides(customEvent.detail);
      }
    };

    window.addEventListener('storage', handleStorage);
    window.addEventListener(CHANGE_EVENT_NAME, handleCustomChange);
    return () => {
      window.removeEventListener('storage', handleStorage);
      window.removeEventListener(CHANGE_EVENT_NAME, handleCustomChange);
    };
  }, []);

  const saveOverrides = useCallback((next: SiteImageMap) => {
    setOverrides(next);
    try {
      scopedStorage.setItem(STORAGE_KEY, JSON.stringify(next));
      // 广播自定义事件，通知同一页面内的其他 useSiteImages 实例同步更新
      // （storage 事件只在跨标签页时触发，同页面内不触发，所以需要自定义事件）
      window.dispatchEvent(new CustomEvent(CHANGE_EVENT_NAME, { detail: next }));
    } catch (e) {
      // 可能是 localStorage 容量不足
      logger.warn('Failed to save site images to storage: ' + String(e));
    }
  }, []);

  /** 获取指定 key 的图片 URL（优先返回用户上传的，否则返回默认图） */
  const getImage = useCallback(
    (key: string): string => {
      const slot = SITE_IMAGE_SLOTS.find((s) => s.key === key);
      const override = overrides[key];
      if (override) return override;
      const defaultUrl = slot?.defaultUrl ?? '';
      // 本地默认图路径加 basename 前缀，确保子路径部署下正确加载
      if (defaultUrl.startsWith('/images/')) return imgPath(defaultUrl);
      return defaultUrl;
    },
    [overrides]
  );

  /** 获取指定 key 的图片 URL（用于函数式取图的工具，返回数组形式便于解构） */
  const getImages = useCallback(
    (keys: string[]): string[] => keys.map((k) => getImage(k)),
    [getImage]
  );

  /** 上传/更新单张图片 */
  const setImage = useCallback(
    (key: string, dataUrl: string): boolean => {
      let success = true;
      // 使用函数式更新，避免 setState 异步竞态导致覆盖
      setOverrides((prev) => {
        const next = { ...prev, [key]: dataUrl };
        try {
          scopedStorage.setItem(STORAGE_KEY, JSON.stringify(next));
          window.dispatchEvent(new CustomEvent(CHANGE_EVENT_NAME, { detail: next }));
        } catch (e) {
          success = false;
          logger.warn('Failed to save site image to storage: ' + String(e));
          // 写入失败，不更新内存状态，保持原值
          return prev;
        }
        return next;
      });
      return success;
    },
    []
  );

  /** 恢复单张图片为默认图 */
  const resetImage = useCallback(
    (key: string) => {
      setOverrides((prev) => {
        const next = { ...prev };
        delete next[key];
        try {
          scopedStorage.setItem(STORAGE_KEY, JSON.stringify(next));
          window.dispatchEvent(new CustomEvent(CHANGE_EVENT_NAME, { detail: next }));
        } catch (e) {
          logger.warn('Failed to reset site image: ' + String(e));
          return prev;
        }
        return next;
      });
    },
    []
  );

  /** 恢复所有图片为默认图 */
  const resetAll = useCallback(() => {
    setOverrides(() => {
      try {
        scopedStorage.setItem(STORAGE_KEY, JSON.stringify({}));
        window.dispatchEvent(new CustomEvent(CHANGE_EVENT_NAME, { detail: {} }));
      } catch (e) {
        logger.warn('Failed to reset all site images: ' + String(e));
      }
      return {};
    });
  }, []);

  /** 某张图是否是用户自定义上传的 */
  const isCustomized = useCallback(
    (key: string): boolean => Boolean(overrides[key]),
    [overrides]
  );

  return {
    ready,
    slots: SITE_IMAGE_SLOTS,
    getImage,
    getImages,
    setImage,
    resetImage,
    resetAll,
    isCustomized,
  };
}
