import { useState, useEffect } from 'react';
import { scopedStorage } from '@lark-apaas/client-toolkit-lite';
import { X, Cookie } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { Link } from 'react-router-dom';
import { useI18n } from '@/i18n/I18nContext';

const STORAGE_KEY = '__app_ledlight_cookie_consent';

export default function CookieBanner() {
  const { t } = useI18n();
  const [visible, setVisible] = useState(false);

  useEffect(() => {
    try {
      const saved = scopedStorage.getItem(STORAGE_KEY);
      if (!saved) {
        const timer = setTimeout(() => setVisible(true), 1500);
        return () => clearTimeout(timer);
      }
    } catch {
      // ignore
    }
  }, []);

  const handleAccept = () => {
    try {
      scopedStorage.setItem(STORAGE_KEY, 'accepted');
    } catch {
      // ignore
    }
    setVisible(false);
  };

  const handleReject = () => {
    try {
      scopedStorage.setItem(STORAGE_KEY, 'rejected');
    } catch {
      // ignore
    }
    setVisible(false);
  };

  if (!visible) return null;

  return (
    <div className="fixed bottom-4 left-4 right-4 md:left-auto md:right-6 md:bottom-6 md:max-w-md z-[60] bg-card border border-border rounded-lg shadow-2xl p-5">
      <div className="flex items-start gap-3">
        <div className="size-10 rounded-full bg-primary/10 flex items-center justify-center shrink-0">
          <Cookie className="size-5 text-primary" />
        </div>
        <div className="flex-1 min-w-0">
          <h4 className="font-semibold text-foreground text-sm mb-1">{t('cookie.title')}</h4>
          <p className="text-xs text-muted-foreground leading-relaxed mb-3">
            {t('cookie.description')}{' '}
            <Link
              to="/privacy-policy"
              onClick={() => setVisible(false)}
              className="text-primary hover:underline"
            >
              {t('cookie.privacyLink')}
            </Link>
          </p>
          <div className="flex items-center gap-2">
            <Button size="sm" onClick={handleAccept} className="bg-primary hover:bg-primary/90 flex-1">
              {t('cookie.accept')}
            </Button>
            <Button size="sm" variant="outline" onClick={handleReject} className="flex-1">
              {t('cookie.reject')}
            </Button>
          </div>
        </div>
        <Button
          variant="ghost"
          size="icon"
          className="!absolute top-2 right-2 h-7 w-7 text-muted-foreground hover:text-foreground"
          onClick={() => setVisible(false)}
        >
          <X className="size-4" />
        </Button>
      </div>
    </div>
  );
}
