/* ========== 图片路径迁移 ========== */
const EXTERNAL_IMAGE_PATTERNS = [/unsplash\.com/i, /doubaocdn\.com/i, /picsum\.photos/i, /pexels\.com/i];

function migrateImageUrl(url: string): string {
  // 外部链接 / 裸 /images/ 路径 → 清空，统一改走 imageKey + useSiteImages 管理
  if (!url) return '';
  if (EXTERNAL_IMAGE_PATTERNS.some((p) => p.test(url))) return '';
  if (url.startsWith('/images/')) return '';
  // base64 / blob 等用户自定义上传保留
  return url;
}

