/**
 * 旧数据迁移：字符串字段 -> I18nText 对象
 * 支持 v1（纯数组）和 v2（带 __version 的数组）结构
 */
function migrateFromLegacy(raw: unknown): IHeroSlide[] | null {
  let arr: unknown[] = [];
  if (Array.isArray(raw)) {
    arr = raw;
  } else if (raw && typeof raw === 'object' && Array.isArray((raw as { data?: unknown[] }).data)) {
    arr = (raw as { data: unknown[] }).data;
  }

  if (!arr.length) return null;

  try {
    return arr.map((item: unknown, idx: number) => {
      const s = item as Record<string, unknown>;
      return {
        id: String(s.id ?? `legacy_${idx}`),
        image: migrateImageUrl(String(s.image ?? '')),
        imageKey: String(s.imageKey ?? `hero_slide_${Math.min(idx + 1, 3)}`),
        badge: migrateI18n(s.badge as string | I18nText),
        title: migrateI18n(s.title as string | I18nText),
        subtitle: migrateI18n(s.subtitle as string | I18nText),
        ctaText: migrateI18n(s.ctaText as string | I18nText),
        ctaLink: String(s.ctaLink ?? '/contact'),
        secondCtaText: migrateI18n(s.secondCtaText as string | I18nText),
        secondCtaLink: String(s.secondCtaLink ?? '/products'),
        order: Number(s.order ?? idx + 1),
      };
    });
  } catch (e) {
    logger.warn('Hero slides migration failed: ' + String(e));
    return null;
  }
}

function readLocalHeroSlides(): IHeroSlide[] {
  try {
    const saved = scopedStorage.getItem(STORAGE_KEY);
    if (saved) {
      const parsed = JSON.parse(saved);
      // v4：直接读取
      if (
        parsed.__version === STORAGE_VERSION &&
        Array.isArray(parsed.data) &&
        parsed.data.length > 0
      ) {
        return parsed.data
          .map((s: Record<string, unknown>) => ({
            ...s,
            badge: migrateI18n(s.badge as string | I18nText | undefined),
            title: migrateI18n(s.title as string | I18nText | undefined),
            subtitle: migrateI18n(s.subtitle as string | I18nText | undefined),
            ctaText: migrateI18n(s.ctaText as string | I18nText | undefined),
            secondCtaText: migrateI18n(s.secondCtaText as string | I18nText | undefined),
          }))
          .sort((a: IHeroSlide, b: IHeroSlide) => a.order - b.order);
      }
      // v3 或旧版本：尝试迁移（快速路径，不做 v3→v4 语言补全，后续 useEffect 会处理）
      const migrated = migrateFromLegacy(parsed);
      if (migrated && migrated.length > 0) {
        return migrated.sort((a, b) => a.order - b.order);
      }
    }
  } catch {
    // ignore
  }
  return DEFAULT_HERO_SLIDES;
}

export function useHeroSlides(options?: { preferRemote?: boolean }) {
  const preferRemote = options?.preferRemote ?? false;
  const remoteData = useRemoteDataStore<IHeroSlide[]>('heroSlides');
  // 🔴 同步初始化：直接读 localStorage 作为初始值，避免首帧默认值 → 第二帧同值不同引用的重渲染
  const [slides, setSlides] = useState<IHeroSlide[]>(() => {
    try {
      const saved = scopedStorage.getItem(STORAGE_KEY);
      if (saved) {
        const parsed = JSON.parse(saved);
        // v4：直接返回
        if (
          parsed.__version === STORAGE_VERSION &&
          Array.isArray(parsed.data) &&
          parsed.data.length > 0
        ) {
          return parsed.data
            .map((s: Record<string, unknown>) => ({
              ...s,
              badge: migrateI18n(s.badge as string | I18nText | undefined),
              title: migrateI18n(s.title as string | I18nText | undefined),
              subtitle: migrateI18n(s.subtitle as string | I18nText | undefined),
              ctaText: migrateI18n(s.ctaText as string | I18nText | undefined),
              secondCtaText: migrateI18n(s.secondCtaText as string | I18nText | undefined),
            }))
            .sort((a: IHeroSlide, b: IHeroSlide) => a.order - b.order);
        }
        // 旧版本迁移（快速路径，v3→v4 语言补全留到后台编辑时处理）
        const migrated = migrateFromLegacy(parsed);
        if (migrated && migrated.length > 0) {
          return migrated.sort((a, b) => a.order - b.order);
        }
      }
    } catch (e) {
      logger.warn('Failed to init hero slides: ' + String(e));
    }
    // 没有本地数据或读取失败，用默认值并持久化
    setTimeout(() => persistSlides(DEFAULT_HERO_SLIDES), 0);
    return DEFAULT_HERO_SLIDES;
  });

  // loading 始终为 false：本地数据同步初始化完成
  const loading = false;

  const displaySlides = useMemo(() => {
    if (preferRemote && remoteData && Array.isArray(remoteData) && remoteData.length > 0) {
      return remoteData
        .map((s) => ({
          ...s,
          badge: migrateI18n(s.badge),
          title: migrateI18n(s.title),
          subtitle: migrateI18n(s.subtitle),
          ctaText: migrateI18n(s.ctaText),
          secondCtaText: migrateI18n(s.secondCtaText),
        }))
        .sort((a: IHeroSlide, b: IHeroSlide) => a.order - b.order);
    }
    return slides;
  }, [preferRemote, remoteData, slides]);

  const persistSlides = (items: IHeroSlide[]): boolean => {
    try {
      scopedStorage.setItem(
        STORAGE_KEY,
        JSON.stringify({ __version: STORAGE_VERSION, data: items })
      );
      return true;
    } catch (e) {
      logger.warn('Failed to save hero slides: ' + String(e));
      return false;
    }
  };

  const saveSlides = useCallback((items: IHeroSlide[]): boolean => {
    const sorted = [...items].sort((a, b) => a.order - b.order);
    setSlides(sorted);
    return persistSlides(sorted);
  }, []);

  const addSlide = useCallback(
    (slide: Omit<IHeroSlide, 'id'>): boolean => {
      const newItem: IHeroSlide = {
        ...slide,
        id: `hero_${Date.now()}_${Math.random().toString(36).slice(2, 8)}`,
      };
      return saveSlides([...slides, newItem]);
    },
    [slides, saveSlides]
  );

  const updateSlide = useCallback(
    (id: string, updates: Partial<IHeroSlide>): boolean => {
      const updated = slides.map((s) => (s.id === id ? { ...s, ...updates } : s));
      return saveSlides(updated);
    },
    [slides, saveSlides]
  );

  const deleteSlide = useCallback(
    (id: string): boolean => {
      return saveSlides(slides.filter((s) => s.id !== id));
    },
    [slides, saveSlides]
  );

  const moveSlide = useCallback(
    (id: string, direction: 'up' | 'down'): boolean => {
      const idx = slides.findIndex((s) => s.id === id);
      if (idx === -1) return false;
      const targetIdx = direction === 'up' ? idx - 1 : idx + 1;
      if (targetIdx < 0 || targetIdx >= slides.length) return false;
      const next = [...slides];
      const tmp = next[idx].order;
      next[idx] = { ...next[idx], order: next[targetIdx].order };
      next[targetIdx] = { ...next[targetIdx], order: tmp };
      return saveSlides(next);
    },
    [slides, saveSlides]
  );

  return {
    slides: displaySlides,
    loading,
    addSlide,
    updateSlide,
    deleteSlide,
    moveSlide,
    saveSlides,
    isUsingRemoteData: preferRemote && !!remoteData,
  };
}
