import { useState } from 'react';
import { NavLink, Link } from 'react-router-dom';
import { Mail, Phone, MapPin, Shield, QrCode } from 'lucide-react';
import { useI18n } from '@/i18n/I18nContext';
import { UniversalLink } from '@lark-apaas/client-toolkit-lite';
import { imgPath } from '@/utils/img-path';
import { useFooterSettings } from '@/hooks/useFooterSettings';
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogDescription } from '@/components/ui/dialog';
import {
  FacebookIcon,
  LinkedinIcon,
  TwitterIcon,
  InstagramIcon,
  WhatsappIcon,
  WechatIcon,
} from '@/components/SocialIcons';

export default function Footer() {
  const { t } = useI18n();
  const { settings } = useFooterSettings({ preferRemote: true });
  const year = new Date().getFullYear();
  const [qrOpen, setQrOpen] = useState(false);
  const [qrHover, setQrHover] = useState(false);

  const wechatQrSrc = settings.wechatQrImage || imgPath('/images/wechat-qr.png');
  const footerLogoSrc = settings.footerLogo || imgPath('/images/owell-logo.png');

  const socialLinks = [
    { name: 'Facebook', url: settings.facebookUrl, Icon: FacebookIcon, enabled: settings.facebookEnabled !== false },
    { name: 'LinkedIn', url: settings.linkedinUrl, Icon: LinkedinIcon, enabled: settings.linkedinEnabled !== false },
    { name: 'Twitter', url: settings.twitterHandle?.startsWith('@') ? `https://twitter.com/${settings.twitterHandle.slice(1)}` : settings.twitterHandle, Icon: TwitterIcon, enabled: settings.twitterEnabled !== false },
    { name: 'Instagram', url: settings.instagramUrl, Icon: InstagramIcon, enabled: settings.instagramEnabled !== false },
    { name: 'WhatsApp', url: settings.whatsappUrl, Icon: WhatsappIcon, enabled: settings.whatsappEnabled !== false },
    { name: 'WeChat', url: settings.wechatUrl, Icon: WechatIcon, enabled: settings.wechatEnabled !== false, isWechat: true },
  ].filter((s) => s.enabled !== false && (s.isWechat || (s.url && s.url.trim().length > 0)));

  return (
    <footer className="w-full bg-card border-t border-border/60">
      <div className="max-w-7xl mx-auto px-4 md:px-6 py-12 md:py-16">
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-8 md:gap-10">
          {/* Brand */}
          <div className="space-y-4">
            <Link to="/" className="flex items-center gap-2">
              <img
                src={footerLogoSrc}
                alt="OWELL Industrial"
                width={40}
                height={40}
                loading="lazy"
                decoding="async"
                className="h-9 md:h-10 w-auto object-contain bg-transparent"
              />
            </Link>
            <p className="text-sm text-muted-foreground leading-relaxed">
              {settings.brandText}
            </p>
            {socialLinks.length > 0 && (
              <div className="flex items-center gap-3 pt-1">
                  {socialLinks.map(({ name, url, Icon, isWechat }) => (
                    isWechat ? (
                      <div
                        key={name}
                        className="relative"
                        onMouseEnter={() => setQrHover(true)}
                        onMouseLeave={() => setQrHover(false)}
                      >
                        {/* Hover Popover (desktop, above icon) */}
                        <div
                          className={`absolute bottom-full left-1/2 -translate-x-1/2 mb-3 z-50 transition-all duration-200 ease-out pointer-events-none ${
                            qrHover
                              ? 'opacity-100 translate-y-0'
                              : 'opacity-0 translate-y-1'
                          }`}
                        >
                          <div className="relative bg-card border border-border rounded-sm shadow-lg p-3 w-44">
                            <p className="text-xs font-semibold text-foreground mb-2 text-center">
                              Scan QR Code
                            </p>
                             <img
                                 src={wechatQrSrc}
                                 alt="WeChat QR Code"
                                 width={144}
                                 height={144}
                                 loading="lazy"
                                 decoding="async"
                                 className="w-36 h-36 object-contain rounded-sm mx-auto bg-background"
                               />
                            <p className="text-[11px] text-muted-foreground mt-2 text-center">
                              Scan with WeChat to add us
                            </p>
                            {/* Arrow pointing down to icon */}
                            <div className="absolute left-1/2 -translate-x-1/2 -bottom-1.5 w-3 h-3 rotate-45 bg-card border-r border-b border-border" />
                          </div>
                        </div>

                        {/* Icon Button */}
                        <button
                          type="button"
                          onClick={() => setQrOpen(true)}
                          aria-label={name}
                          className="group flex items-center justify-center size-10 rounded-full bg-background/60 border border-border/60 transition-all duration-200 hover:scale-110 hover:shadow-lg hover:border-primary/40"
                        >
                          <Icon />
                        </button>
                      </div>
                    ) : (
                      <UniversalLink
                        key={name}
                        to={url}
                        target="_blank"
                        rel="noopener noreferrer"
                        aria-label={name}
                        className="group flex items-center justify-center size-10 rounded-full bg-background/60 border border-border/60 transition-all duration-200 hover:scale-110 hover:shadow-lg hover:border-primary/40"
                      >
                        <Icon />
                      </UniversalLink>
                    )
                  ))}
                </div>
            )}
          </div>

          {/* Quick Links */}
          <div>
            <h4 className="text-sm font-semibold text-foreground mb-4">{t('footer.quickLinks')}</h4>
            <ul className="space-y-2.5">
              <li>
                <NavLink to="/" end className="text-sm text-muted-foreground hover:text-primary transition-colors">
                  {t('nav.home')}
                </NavLink>
              </li>
              <li>
                <NavLink to="/products" className="text-sm text-muted-foreground hover:text-primary transition-colors">
                  {t('nav.products')}
                </NavLink>
              </li>
              <li>
                <NavLink to="/news" className="text-sm text-muted-foreground hover:text-primary transition-colors">
                  {t('nav.news')}
                </NavLink>
              </li>
              <li>
                <NavLink to="/about" className="text-sm text-muted-foreground hover:text-primary transition-colors">
                  {t('nav.about')}
                </NavLink>
              </li>
              <li>
                <NavLink to="/contact" className="text-sm text-muted-foreground hover:text-primary transition-colors">
                  {t('nav.contact')}
                </NavLink>
              </li>
            </ul>
          </div>

          {/* Support */}
          <div>
            <h4 className="text-sm font-semibold text-foreground mb-4">{t('footer.support')}</h4>
            <ul className="space-y-2.5">
              <li>
                <NavLink to="/privacy-policy" className="text-sm text-muted-foreground hover:text-primary transition-colors">
                  {t('footer.privacyPolicy')}
                </NavLink>
              </li>
              <li>
                <NavLink to="/contact" className="text-sm text-muted-foreground hover:text-primary transition-colors">
                  {t('footer.contactUs')}
                </NavLink>
              </li>
            </ul>
          </div>

          {/* Contact Info */}
          <div>
            <h4 className="text-sm font-semibold text-foreground mb-4">{t('footer.contactInfo')}</h4>
            <ul className="space-y-3">
              <li className="flex items-start gap-3">
                <Mail className="size-4 text-primary shrink-0 mt-0.5" />
                <UniversalLink
                  to={`mailto:${settings.email}`}
                  className="text-sm text-muted-foreground hover:text-primary transition-colors"
                >
                  {settings.email}
                </UniversalLink>
              </li>
              <li className="flex items-start gap-3">
                <Phone className="size-4 text-primary shrink-0 mt-0.5" />
                <span className="text-sm text-muted-foreground">{settings.phone}</span>
              </li>
              <li className="flex items-start gap-3">
                <MapPin className="size-4 text-primary shrink-0 mt-0.5" />
                <span className="text-sm text-muted-foreground">{settings.address}</span>
              </li>
            </ul>
          </div>
        </div>

        {/* Bottom bar */}
        <div className="mt-10 pt-6 border-t border-border/60 flex flex-col md:flex-row items-center justify-between gap-4">
          <p className="text-xs text-muted-foreground">
            © {year} {settings.copyright} {t('footer.rightsReserved')}
          </p>
          <div className="flex items-center gap-4">
            {settings.certifications.length > 0 && (
              <div className="flex flex-wrap items-center gap-2 text-xs text-muted-foreground">
                <Shield className="size-3.5 text-primary shrink-0" />
                {settings.certifications.map((cert) => (
                  <span
                    key={cert}
                    className="px-2 py-0.5 rounded-sm border border-primary/30 text-foreground/80 bg-primary/5 font-medium tracking-wide"
                  >
                    {cert}
                  </span>
                ))}
              </div>
            )}
          </div>
        </div>
      </div>

      {/* WeChat QR Dialog */}
      <Dialog open={qrOpen} onOpenChange={setQrOpen}>
        <DialogContent className="sm:max-w-md bg-card border-border text-foreground">
          <DialogHeader>
            <DialogTitle className="text-center text-lg font-semibold">Scan QR Code</DialogTitle>
            <DialogDescription className="text-center text-muted-foreground">
              Open WeChat and scan the QR code to add us
            </DialogDescription>
          </DialogHeader>
          <div className="flex flex-col items-center justify-center gap-4 py-4">
            <div className="relative rounded-lg border border-border bg-background p-3">
              <img
                src={wechatQrSrc}
                alt="WeChat QR Code"
                width={256}
                height={256}
                loading="lazy"
                decoding="async"
                className="w-64 h-64 object-contain rounded-md"
              />
            </div>
            <p className="text-sm text-muted-foreground">
              Scan with WeChat to connect with us
            </p>
          </div>
        </DialogContent>
      </Dialog>
    </footer>
  );
}
